// Correcciones Simulia — tanda 3 — parte 6 de 7: protocolos y escalas (preguntas propias) (10 oct 2026)
// Pegar en mongosh (Compass) conectado a SimuLIA. Guarda copia de cada original antes de tocarlo.
const db2 = db.getSiblingDB('CSV');
const backup = db2.getCollection('backup_correcciones_2026_10_10_t3');
let ok=0, del=0, warn=0;
function fix(coll, filter, set) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], savedAt: new Date() });
  c.updateOne({ _id: d[0]._id }, { $set: set }); ok++;
}
function rm(coll, filter) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], deleted: true, savedAt: new Date() });
  c.deleteOne({ _id: d[0]._id }); del++;
}

fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd2") }, {"long_answer": "Tetraxim tiene autorizada la primovacunación con 3 dosis a partir de los 2 meses de edad, separadas por intervalos de 1 o 2 meses, seguida de dosis de recuerdo según el calendario. Por eso puede utilizarse en la vacunación acelerada de menores que no han recibido la pauta completa. No se administra en dosis única a los 6 meses, no existe una pauta de 5 dosis entre los 2 y los 7 años y su uso no se limita a dosis de recuerdo a partir de los 7 años, edad a partir de la cual se prefieren vacunas de baja carga antigénica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd6") }, {"option_1": "Administrarlas en lugares anatómicos diferentes y, si coinciden en la misma extremidad, separarlas al menos 2-3 cm para evitar el solapamiento de reacciones locales.", "long_answer": "Cuando se administran varias vacunas en la misma sesión a un menor sin registro vacunal, se recomienda ponerlas en lugares anatómicos diferentes y, si dos inyecciones coinciden en la misma extremidad, separarlas al menos 2-3 cm para poder distinguir y no solapar las reacciones locales. Ponerlas todas en el mismo punto aumenta las reacciones y dificulta atribuirlas. Limitarse a una vacuna por visita retrasa innecesariamente la protección, justo lo que la vacunación acelerada pretende evitar. No hay motivo para usar solo el brazo derecho."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fdd") }, {"long_answer": "La mayoría de las infecciones por poliovirus son asintomáticas (alrededor del 70%) o cursan como un cuadro febril leve inespecífico, y una pequeña proporción produce meningitis aséptica. Solo menos del 1% de las infecciones evoluciona a poliomielitis paralítica con parálisis flácida aguda, lo que explica que el virus pueda circular de forma silenciosa durante mucho tiempo antes de detectarse un caso. Por eso los porcentajes de más del 90%, entre el 5 y el 15% o alrededor del 50% sobrestiman ampliamente la proporción de formas paralíticas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fde") }, {"long_answer": "Se considera caso prioritario o hot case de parálisis flácida aguda el que aparece en un menor de 15 años con menos de tres dosis documentadas de vacuna frente a la poliomielitis, así como otros casos con alta sospecha clínica o antecedente de viaje a zonas con circulación de poliovirus. Estos casos exigen una investigación inmediata. Un caso con más de 3 dosis presenta menor riesgo. Los adultos mayores quedan fuera de la vigilancia sistemática de PFA, que se centra en menores de 15 años, y la ausencia de viaje no convierte un caso en prioritario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fdf") }, {"long_answer": "Un poliovirus derivado de vacuna (PVDV) es una cepa procedente de la vacuna oral atenuada que, tras replicarse de forma prolongada, acumula mutaciones y presenta una divergencia en la secuencia de la región VP1 superior al 1% respecto a la cepa vacunal original (o superior al 0,6% en el caso del tipo 2). Por debajo de esos umbrales se habla de virus similares a Sabin, no de PVDV. La ausencia total de mutaciones corresponde a la cepa vacunal. Los PVDV sí se replican y pueden recuperar neurovirulencia y transmisibilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe2") }, {"long_answer": "Las personas con trastornos de inmunodeficiencia primaria pueden excretar de forma prolongada poliovirus derivados de la vacuna oral. Como en España no se utiliza vacuna oral, la detección de poliovirus en una persona con TIP se considera vinculada a la vacunación o a la transmisión en zonas donde se usa VPO, se clasifica como evento importado o relacionado con esa transmisión y exige estudio y seguimiento epidemiológico del caso y sus contactos. Nunca se ignora ni se descarta, aunque no haya parálisis, porque esa persona puede diseminar el virus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fea") }, {"long_answer": "Los poliovirus salvajes son virus naturales que han circulado de forma persistente en la comunidad y cuya secuencia de la región VP1 difiere en más de un 15% de las cepas vacunales Sabin. No se parecen genéticamente a la cepa vacunal, a diferencia de los virus similares a Sabin o de los derivados de vacuna. Tampoco son virus de laboratorio atenuados sin capacidad de replicación. Los virus derivados de cepas Sabin modificadas son, precisamente, los PVDV, no los poliovirus salvajes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff3") }, {"long_answer": "Desde 2017, el calendario sistemático español frente a la poliomielitis utiliza la pauta 2+1 con vacuna hexavalente, es decir, dos dosis de primovacunación a los 2 y 4 meses y una dosis de recuerdo a los 11 meses, y añade otra dosis de recuerdo a los 6 años con la vacuna dTpa-VPI. Así se alcanzan cuatro dosis de VPI. La pauta de tres dosis sin recuerdo no es la vigente. No se administra una dosis anual durante cinco años, y tampoco existen dosis al nacimiento, propias de la vacuna oral en algunos países."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ffb") }, {"long_answer": "A las personas que viajan a zonas con circulación activa de poliovirus se les debe revisar y actualizar su estado de vacunación, completando la pauta según su edad si está incompleta y valorando una dosis de recuerdo de VPI en adultos ya vacunados, de acuerdo con las recomendaciones del Reglamento Sanitario Internacional. La duración del viaje no exime de esta revisión. La recomendación no se limita a niños menores de 5 años. Tampoco afecta solo a residentes permanentes, aunque para estancias largas puedan exigirse certificados de vacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ffd") }, {"long_answer": "El principal objetivo terapéutico de la administración de anestésicos locales por parte de las enfermeras es eliminar el dolor durante los procedimientos diagnósticos o terapéuticos, como suturas, curas o canalizaciones, y prevenir las complicaciones asociadas al dolor y a la falta de colaboración del paciente. Los anestésicos locales no mejoran la movilidad muscular. No inducen sedación, porque actúan bloqueando la conducción nerviosa de forma localizada. Tampoco son antiinflamatorios, por lo que reducir la inflamación no es su finalidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978001") }, {"long_answer": "La revisión quirúrgica completa del paciente antes de una gran cirugía no forma parte del proceso enfermero descrito en la guía, que se centra en procedimientos menores con anestésicos locales. El proceso sí incluye la valoración previa y la anamnesis para detectar alergias, contraindicaciones y riesgos, la administración del anestésico local con la realización del procedimiento y el seguimiento posterior, con el cuidado de la herida o del punto de inserción y la educación al paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978003") }, {"long_answer": "Para que las enfermeras puedan indicar, usar y autorizar la dispensación de anestésicos locales sujetos a prescripción médica, la normativa exige la elaboración y aplicación de protocolos o guías de práctica clínica y asistencial consensuados de forma multidisciplinar y validados, que delimiten los criterios de actuación. La autorización verbal del paciente no sustituye a ese marco documental. La decisión exclusiva del enfermero sin protocolo no está permitida. Los protocolos tampoco se elaboran solo por médicos, sino de forma conjunta con enfermería."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97800c") }, {"option_1": "Solo cuando lo contemple el protocolo de actuación y dentro de lo establecido en la ficha técnica", "long_answer": "Según la guía, la enfermera solo puede modificar la pauta de un anestésico local cuando el protocolo de actuación lo contempla y siempre dentro de lo establecido en la ficha técnica del medicamento, ya que su actuación se ajusta a criterios consensuados. No puede cambiarla libremente según su experiencia personal. Tampoco puede hacerlo porque el paciente lo pida sin criterio clínico. La opción que permite al enfermero cambiar la dosis sin autorización contradice el marco normativo que regula la indicación enfermera."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97800e") }, {"long_answer": "La reducción de controles médicos en todas las patologías crónicas sin seguimiento no es una ventaja que destaque la guía, ya que la actuación enfermera con anestésicos locales se integra en el trabajo en equipo y no pretende sustituir el seguimiento médico. Sí se citan como ventajas la educación al paciente y al cuidador en el manejo del tratamiento, el seguimiento para mejorar la adherencia y la monitorización de los resultados, y facilitar el acceso a los tratamientos evitando demoras innecesarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978011") }, {"long_answer": "La guía excluye de su listado medicamentos como los parches de lidocaína porque su indicación autorizada es exclusivamente el alivio del dolor neuropático asociado a la neuralgia posherpética, una situación que requiere diagnóstico y seguimiento médico y que no corresponde a la anestesia local en procedimientos enfermeros. La exclusión no depende de su financiación por el Sistema Nacional de Salud. Los parches no se usan en cirugía mayor. Tampoco se excluyen por alergias frecuentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978013") }, {"long_answer": "El Real Decreto 954/2015 establece que la indicación, uso y autorización de dispensación de medicamentos por parte de las enfermeras debe respetar los principios de atención integral, trabajo en equipo, continuidad asistencial, seguridad del paciente y práctica basada en la evidencia científica. La rapidez y la reducción de costes no se recogen como principios básicos. La autonomía total sin protocolos es contraria a la norma. La intervención médica única y excluyente niega la colaboración interprofesional que el decreto regula."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978015") }, {"long_answer": "El Real Decreto Legislativo 1/2015, texto refundido de la Ley de garantías y uso racional de los medicamentos, regula que las enfermeras pueden indicar, usar y autorizar la dispensación de medicamentos, incluidos los sujetos a prescripción médica, dentro de un marco de atención integral y de acuerdo con protocolos y guías consensuados. No permite la dispensación libre sin control. No limita la actuación al hospital, ya que se aplica también en atención primaria. Tampoco se restringe a medicamentos no sujetos a prescripción, que la enfermera puede indicar de forma autónoma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97801b") }, {"long_answer": "Desde el punto de vista clínico y asistencial, la guía pretende reducir la variabilidad en la práctica clínica y ofrecer un protocolo actualizado según la mejor evidencia disponible, para que la administración de anestésicos locales por enfermeras sea segura, homogénea y de calidad. No busca limitar su uso a unidades hospitalarias, ya que también se aplica en atención primaria. No pretende excluir al paciente de su cuidado, sino implicarlo. Tampoco delega la prescripción solo en médicos especialistas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978025") }, {"long_answer": "La guía de indicación enfermera en infección del tracto urinario inferior no complicada excluye las situaciones de mayor riesgo, en las que es necesaria la valoración médica: embarazo, recidiva o reinfección, portadoras de sonda vesical e inmunosupresión, además de otros criterios como la fiebre o el dolor lumbar. La bacteriuria asintomática y la edad igual o superior a 14 años no son situaciones excluidas por sí mismas. La primera infección no complicada y los síntomas leves sin factores de riesgo son, precisamente, el ámbito de actuación de la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978029") }, {"long_answer": "La enfermera puede interrumpir temporalmente el tratamiento cuando aparecen efectos adversos, intolerancia o una evolución clínica no favorable, y en ese caso debe derivar a la paciente al médico para su valoración. La simple petición de la paciente sin motivo clínico no es el criterio establecido en la guía. No existe una regla de suspensión tras la tercera dosis si no hay mejoría. No es necesaria una autorización médica expresa para interrumpir el tratamiento ante un problema de seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97802b") }, {"long_answer": "La guía establece la indicación y autorización de dispensación enfermera en la infección del tracto urinario inferior no complicada en mujeres a partir de los 14 años, siempre que no presenten criterios de exclusión. Situar el límite en 18 o en 21 años no corresponde a lo recogido en la guía. Los 12 años quedan por debajo de la edad mínima establecida, ya que en menores de 14 años la valoración corresponde al pediatra o al médico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97802e") }, {"long_answer": "Para aplicar esta guía, la enfermera debe contar con la acreditación emitida por el órgano competente de su comunidad autónoma, según lo establecido en el Real Decreto 954/2015 y su modificación de 2018. No es necesario ser especialista en Medicina Familiar y Comunitaria, que es una especialidad médica. Tampoco se exige una autorización expresa del médico en cada actuación, porque la guía y los protocolos ya delimitan el marco de actuación. La formación básica por sí sola no basta sin la acreditación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978032") }, {"long_answer": "La cistitis no complicada se caracteriza por síntomas miccionales como la disuria, la polaquiuria, la urgencia miccional y el dolor suprapúbico, sin prurito ni flujo vaginal, cuya presencia orienta hacia una vaginitis. El flujo anormal con prurito intenso sugiere una infección vaginal. El dolor lumbar con fiebre alta indica pielonefritis, que es un criterio de exclusión de la guía. La hematuria aislada sin síntomas urinarios no corresponde a una cistitis y requiere estudio médico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97803a") }, {"long_answer": "Los rangos de actuación de las enfermeras en el tratamiento farmacológico de la ITU quedan delimitados por los criterios fijados en protocolos o guías de práctica clínica y asistencial específicos, elaborados y validados de forma multidisciplinar. La enfermera no actúa con autonomía ilimitada. Tampoco depende de indicaciones verbales del médico en cada caso. Los programas de educación sanitaria, aunque necesarios, no establecen por sí solos los criterios de tratamiento farmacológico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97803b") }, {"long_answer": "La guía nacional es un marco general, por lo que las Comisiones y las entidades gestoras deben desarrollar a partir de ella sus propios protocolos, adaptados a su contexto asistencial, recursos y circuitos, estableciendo criterios específicos de actuación. Los protocolos locales no reemplazan la guía nacional, sino que la concretan. Su finalidad no es limitar la participación de enfermería. Reducir la dispensación de antibióticos no es el motivo, aunque el uso racional sí forme parte de los objetivos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978044") }, {"long_answer": "El Real Decreto 1302/2018, que modifica el Real Decreto 954/2015, establece que en el ámbito de la vacunación la indicación, uso y autorización de dispensación de medicamentos sujetos a prescripción médica por enfermeras solo precisa la correspondiente orden de dispensación, salvo en los casos concretos en que el paciente requiera una valoración médica individualizada. La valoración médica no se exige en todos los casos. No se requiere supervisión médica directa durante la administración. El decreto no impone un curso específico de vacunación acreditado por la comunidad autónoma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978045") }, {"long_answer": "El Real Decreto establece que los protocolos y guías de práctica clínica y asistencial que regulan la actuación enfermera deben quedar aprobados y validados en un plazo máximo de dos años desde su entrada en vigor. No son aprobados exclusivamente por el Ministerio sin límite temporal, ya que su elaboración corresponde a la Comisión Permanente de Farmacia con participación de las profesiones implicadas. Las comunidades autónomas no deciden libremente el plazo. Tampoco se exige validación internacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978047") }, {"long_answer": "En materia de protección de datos, el Real Decreto adapta la regulación de la indicación y dispensación de medicamentos por enfermería al Reglamento General de Protección de Datos, el Reglamento (UE) 2016/679, que regula el tratamiento de los datos personales de los pacientes. La Directiva 2005/36/CE trata del reconocimiento de cualificaciones profesionales, no de los datos personales. El reglamento sobre medicamentos falsificados regula dispositivos de seguridad de los envases. No existe un reglamento europeo sobre seguridad del paciente que se adapte en este decreto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978048") }, {"long_answer": "La especialidad de Enfermería Obstétrico-Ginecológica (matrona) tiene reconocidas competencias para el diagnóstico, la supervisión y la asistencia del embarazo, el parto y el posparto normales, así como del recién nacido sano, y por eso el Real Decreto le atribuye un papel propio en la indicación de medicamentos en este ámbito. La Enfermería Pediátrica se centra en la atención a la infancia y la adolescencia. La Enfermería Geriátrica atiende a las personas mayores. La Enfermería de Salud Mental se ocupa de los trastornos mentales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97804f") }, {"long_answer": "El Real Decreto cita expresamente la Ley 44/2003, de ordenación de las profesiones sanitarias, y en particular su artículo 47 y el Foro Profesional, como cauce para el diálogo y el desarrollo regulatorio de las competencias compartidas entre profesiones sanitarias. El Real Decreto 1718/2010 regula la receta médica y la orden de dispensación, pero no las competencias compartidas. La Ley 16/2003 de cohesión y calidad organiza el SNS. La Ley 50/1997, del Gobierno, regula el procedimiento de elaboración normativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978052") }, {"long_answer": "La modificación de 2018 del Real Decreto 954/2015 incorporó un lenguaje más inclusivo, sustituyendo las referencias genéricas a enfermero y enfermeros por las expresiones enfermera y enfermero, y enfermeras y enfermeros, en reconocimiento de una profesión mayoritariamente femenina. Por tanto, no se mantuvieron los términos sin cambios. El término enfermero no se sustituyó por especialista en enfermería. Tampoco se eliminó el término enfermera, sino que se incorporó de forma explícita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e6f") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal es un conjunto de recomendaciones basadas en la evidencia que ayudan a tomar decisiones, pero no es de obligado cumplimiento ni sustituye el juicio clínico del profesional, que debe adaptar la atención a cada mujer y a sus preferencias. No obliga a todo el personal sanitario como si fuera una norma. No reemplaza las normas ni los protocolos locales, que pueden adaptarla. En ningún caso obliga a realizar cesáreas en partos normales, ya que promueve una atención lo menos intervencionista posible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e78") }, {"long_answer": "Las matronas son las profesionales de referencia en la atención al parto normal, por lo que tienen un papel clave en la aplicación de la Estrategia de Atención al Parto Normal y en la implementación de la guía, junto con obstetras, pediatras y otros profesionales del equipo. Su ámbito no son los partos quirúrgicos, que corresponden al obstetra. Es falso que no participen en el parto normal, ya que lo atienden directamente. Tampoco se limitan al recién nacido tras el parto, porque acompañan a la mujer durante todo el proceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e88") }, {"long_answer": "Llamar cannabis sintético a los cannabinoides sintéticos es un error, porque son sustancias químicas diferentes, generalmente agonistas completos y muy potentes del receptor CB1. El dossier advierte que esta etiqueta hace que se subestimen sus riesgos tóxicos, mucho mayores, al equipararlos con los del cannabis natural. No implica que los recursos se destinen solo a la prevención del cannabis natural. No es una terapia aprobada. Tampoco se considera que sean inocuos, aunque la etiqueta transmita una falsa sensación de seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e8a") }, {"long_answer": "El dossier alerta de la aparición de productos comestibles con cannabinoides sintéticos, como golosinas, gominolas o snacks, que imitan productos comerciales y han provocado intoxicaciones por ingesta inadvertida, especialmente en niños y adolescentes. No se ha descrito un aumento de la adicción exclusiva en personas mayores. Estos productos no tienen efectos terapéuticos seguros ni regulados. Su aparición no ha hecho desaparecer las intoxicaciones; al contrario, las ha favorecido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e8e") }, {"long_answer": "Según la encuesta europea ESPAD de 2019 sobre consumo de sustancias en estudiantes de 15-16 años, un 3,1% de los estudiantes europeos declaró haber consumido cannabinoides sintéticos al menos una vez en la vida. La cifra del 0,5% infraestima la prevalencia recogida. El 10% y el 15% la sobrestiman claramente y se acercan más a las cifras de consumo de cannabis natural en esa población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e91") }, {"long_answer": "Dado su elevado y poco predecible riesgo para la salud, el dossier recomienda como opción más segura no consumir cannabinoides sintéticos. Su composición y su potencia varían de un producto a otro y pueden provocar intoxicaciones graves incluso con cantidades pequeñas. Comprarlos en tiendas especializadas no garantiza su composición. Utilizar dosis bajas no evita la intoxicación por la variabilidad de concentraciones. Mezclarlos con cannabis natural no reduce los efectos adversos y puede potenciarlos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e95") }, {"long_answer": "Entre los efectos a corto plazo descritos tras consumir cannabinoides sintéticos figuran los parecidos a los del cannabis, como la relajación, el estado de ánimo elevado y la congestión conjuntival, aunque con mayor intensidad y riesgo de efectos graves como agitación, taquicardia, psicosis o convulsiones. La somnolencia profunda y la sedación prolongada no son el efecto habitual. La pérdida total de la memoria inmediata no es característica. Tampoco producen analgesia prolongada sin efecto psicoactivo, porque su acción psicoactiva es intensa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e97") }, {"long_answer": "Muchos consumidores adquieren cannabinoides sintéticos creyendo que compran cannabis natural, debido a la venta engañosa de productos adulterados, como flores de cáñamo pulverizadas con estas sustancias, y al desconocimiento sobre su composición real. El dossier no atribuye este problema al precio o a la dificultad de acceso al cannabis natural. Tampoco a una regulación que prohíba todos los productos sintéticos. La promoción de derivados del cáñamo no es la causa, aunque esos productos puedan servir para camuflar el fraude."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e98") }, {"long_answer": "Los cannabinoides sintéticos se presentan habitualmente como material vegetal triturado impregnado para fumar, líquidos para cigarrillos electrónicos y productos para infusiones o comestibles, como golosinas, lo que facilita el consumo inadvertido. No se comercializan como tabletas aprobadas por autoridades sanitarias. No son cápsulas prescritas por médicos. Tampoco existen extractos inyectables de uso clínico entre sus formatos de consumo habitual, ya que no tienen ninguna indicación terapéutica autorizada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea0") }, {"long_answer": "En el estudio de fiabilidad de las versiones españolas de las escalas de fragilidad, la FRAIL-España mostró una concordancia intraobservador excelente, con un coeficiente de correlación intraclase promedio superior a 0,90, lo que indica que un mismo profesional obtiene resultados muy similares al repetir la valoración. Un valor de 0,80 o un rango entre 0,60 y 0,80 corresponderían a una fiabilidad buena o moderada, inferior a la observada. Un CCI inferior a 0,60 indicaría una fiabilidad pobre, lo que no se corresponde con los resultados del estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea1") }, {"long_answer": "Según el estudio, el ítem de comorbilidades (enfermedades) de la FRAIL-España fue el que mostró una correlación débil con la valoración global, probablemente porque el número de enfermedades crónicas no siempre refleja la situación funcional ni el grado de fragilidad del paciente. La fatiga, la capacidad de ambulación y la pérdida de peso mostraron una mejor correlación con la valoración global de la escala."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea5") }, {"long_answer": "En la primera valoración con la FRAIL-España, el 44% de los pacientes incluidos en el estudio presentaba fatiga, lo que la convierte en uno de los componentes de fragilidad más frecuentes en esa muestra de pacientes críticos. Las cifras del 4%, el 26% y el 32% no corresponden al porcentaje de fatiga recogido en los resultados del estudio y podrían confundirse con las prevalencias de otros ítems de la escala o de otros desenlaces."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea8") }, {"long_answer": "La mediana de edad de los pacientes incluidos en el estudio de validación de la CFS-España y la FRAIL-España fue de 72 años, coherente con una población de pacientes mayores ingresados en la unidad de cuidados intensivos, en la que la fragilidad es una variable pronóstica relevante. Los valores de 60 y 65 años serían inferiores a los observados. La cifra de 80 años la sobrestima. Ninguno de esos tres valores corresponde a la mediana descrita en los resultados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eac") }, {"long_answer": "En la CFS-España, los valores del coeficiente de correlación intraclase intraobservador fueron superiores a 0,80 para todas las profesionales participantes, lo que indica una fiabilidad buena cuando una misma persona repite la valoración. No es cierto que los CCI estuvieran por debajo de 0,50, lo que indicaría una fiabilidad pobre. La concordancia elevada no se limitó a las enfermeras. Tampoco es cierto que los intensivistas carecieran de concordancia intraobservador, ya que también superaron ese umbral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ead") }, {"long_answer": "Según los resultados del estudio, el ítem de pérdida de peso de la FRAIL-España fue el que mostró menor concordancia interobservador entre profesionales, probablemente porque depende de datos referidos por el paciente o la familia que a menudo son imprecisos en la unidad de cuidados intensivos. Las enfermedades, la fatiga y la ambulación mostraron un acuerdo interobservador mayor entre los distintos profesionales que realizaron la valoración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eae") }, {"long_answer": "En el estudio, la FRAIL-España mostró una mayor fiabilidad intraobservador global que la CFS-España, con coeficientes de correlación intraclase promedio superiores a 0,90 frente a valores algo menores, aunque también buenos, de la CFS-España, superiores a 0,80. Por tanto, no se puede afirmar que la CFS-España fuera más fiable ni que ambas escalas fueran iguales en este aspecto. Sí es posible determinarlo, ya que el estudio comparó la concordancia de ambas escalas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb2") }, {"long_answer": "Para comparar medianas entre grupos, el estudio utilizó la prueba U de Mann-Whitney, una prueba no paramétrica adecuada para variables cuantitativas que no siguen una distribución normal, como las puntuaciones de las escalas de fragilidad. El ANOVA de un factor y la t de Student comparan medias y asumen normalidad. La prueba de Chi-cuadrado se emplea para comparar proporciones entre variables categóricas, no medianas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb9") }, {"long_answer": "Según los resultados del estudio, el 7% de los pacientes evaluados falleció durante su estancia en la unidad de cuidados intensivos, una mortalidad relativamente baja que se explica por las características de la muestra incluida. Los porcentajes del 16% y el 23% podrían corresponder a desenlaces con un seguimiento más largo, como la mortalidad hospitalaria o a medio plazo, pero no a la mortalidad en la UCI. El 4% infraestima la cifra observada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ebe") }, {"long_answer": "El periodo de inclusión de pacientes en el estudio de validación de las versiones españolas de las escalas de fragilidad fue de enero de 2020 a junio de 2023, un periodo amplio que permitió reunir una muestra suficiente de pacientes críticos y que abarcó la pandemia de COVID-19. Los periodos de 2018 a 2019, de junio de 2019 a diciembre de 2021 y de enero de 2022 a junio de 2024 no corresponden a las fechas de reclutamiento descritas en el estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec5") }, {"long_answer": "El sistema suizo revisado de estadificación de la hipotermia accidental se basa en la observación del nivel de consciencia, mediante la escala AVDN, y de otros signos clínicos, como la presencia de signos vitales, para estimar el riesgo de parada cardiaca cuando no se dispone de un termómetro fiable para medir la temperatura central. La presión arterial y la frecuencia cardiaca no permiten estimar la temperatura central. El lactato no se utiliza en el terreno con ese fin. La frecuencia respiratoria y la saturación tampoco sirven para ello."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec6") }, {"long_answer": "En el sistema suizo revisado, la escala AVDN (alerta, respuesta verbal, respuesta al dolor y no respuesta) es la herramienta clave para estimar, a partir de hallazgos clínicos, el riesgo de parada cardiaca del paciente hipotérmico y orientar su tratamiento y su traslado. No mide la temperatura central, aunque sustituye su estimación cuando no hay termómetro. No sirve para medir la presión arterial. Tampoco mide la saturación de oxígeno ni la frecuencia respiratoria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ecb") }, {"long_answer": "En los pacientes con hipotermia grave y alto riesgo de parada cardiaca, el sistema revisado recomienda el traslado a un centro con capacidad de soporte vital extracorpóreo, ya que el recalentamiento mediante oxigenación por membrana extracorpórea (ECMO) permite recalentar rápidamente manteniendo la circulación y la oxigenación. El recalentamiento pasivo con mantas es insuficiente en estos casos. La ropa seca y las bebidas calientes solo son adecuadas en la hipotermia leve con paciente alerta. Los masajes en extremidades están contraindicados por el riesgo de arritmias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ecc") }, {"long_answer": "La función principal del sistema suizo revisado es clasificar el riesgo de parada cardiaca de la víctima de hipotermia accidental mediante signos clínicos y orientar las decisiones de tratamiento y traslado cuando no se dispone de una medición fiable de la temperatura central. No mide la temperatura exacta, sino que la sustituye por la valoración clínica. No se limita a decidir el hospital de destino. Tampoco valora exclusivamente la necesidad de reanimación cardiopulmonar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed2") }, {"long_answer": "Según el sistema revisado, una víctima con hipotermia de grado I (leve) y alerta completa tiene un riesgo bajo de parada cardiaca, por lo que tras el aislamiento térmico y el recalentamiento activo externo puede trasladarse al hospital más cercano y adecuado. El traslado a un centro con ECMO o con UCI se reserva para los pacientes con alteración del nivel de consciencia y mayor riesgo de parada. Afirmar que no es necesario el traslado es incorrecto, porque estos pacientes deben ser valorados en un centro sanitario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed3") }, {"long_answer": "En la hipotermia grave con parada cardiaca, la supervivencia depende de mantener una reanimación cardiopulmonar de calidad, a menudo prolongada, y de trasladar al paciente a un centro donde pueda recalentarse mediante soporte vital extracorpóreo (RCP con ECMO), que logra buenas tasas de supervivencia con buen estado neurológico. Los líquidos orales están contraindicados en un paciente inconsciente o en parada. La inmovilización sin recalentamiento activo no revierte la parada. La estimulación verbal carece de utilidad terapéutica en esta situación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed5") }, {"long_answer": "En el sistema suizo revisado, el paciente hipotérmico que solo responde a estímulos verbales (V en la escala AVDN) presenta un riesgo moderado de parada cardiaca, por lo que se recomienda su traslado a un hospital con unidad de cuidados intensivos y, preferiblemente, con posibilidad de ECMO por si se produce un deterioro. Un hospital local sin UCI o un hospital rural sin recursos específicos no podrían manejar una posible parada hipotérmica. Una clínica ambulatoria no es un destino adecuado para un paciente con hipotermia moderada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed6") }, {"long_answer": "Un paciente hipotérmico inconsciente, que solo responde al dolor o no responde, pero que conserva signos vitales, se clasifica en el grado III del sistema suizo revisado, con un riesgo alto de parada cardiaca. El grado I corresponde al paciente alerta. El grado II corresponde al que presenta un nivel de consciencia alterado pero responde a estímulos verbales. El grado IV corresponde a la ausencia de signos vitales, es decir, a la parada cardiaca hipotérmica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977edf") }, {"long_answer": "En el trastorno de ansiedad generalizada, la ansiedad y la preocupación son excesivas, persistentes y difíciles de controlar, se refieren a múltiples temas de la vida diaria y están presentes la mayor parte de los días durante al menos 6 meses, acompañadas de síntomas físicos. Que sea episódica y limitada a situaciones concretas describe mejor las fobias o el trastorno de pánico. Los miedos sociales o específicos corresponden a la fobia social y a las fobias específicas. El TAG sí produce malestar significativo y deterioro funcional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee1") }, {"long_answer": "La pérdida de peso significativa no es un síntoma somático característico del trastorno de ansiedad generalizada y, si aparece, obliga a descartar otras causas, como una depresión, un hipertiroidismo o una enfermedad orgánica. Sí son típicos del TAG los síntomas autonómicos, como la taquicardia y la sudoración, los síntomas digestivos, como las náuseas y la diarrea, y la tensión y los dolores musculares, junto con la inquietud, la fatiga y los problemas de sueño."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee4") }, {"long_answer": "Según la guía, la terapia cognitivo-conductual en el trastorno de ansiedad generalizada puede aplicarse en distintas modalidades (individual, grupal, presencial o a distancia, incluida la autoayuda guiada), y la elección debe consensuarse con el paciente en función de sus valores, sus preferencias y los recursos disponibles. Por eso no tiene que ser siempre individual y presencial. Tampoco siempre grupal. Su aplicación exclusivamente telefónica no es la recomendación general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee5") }, {"long_answer": "La guía recomienda iniciar la terapia cognitivo-conductual en el trastorno de ansiedad generalizada con unas 10-12 sesiones de periodicidad semanal, lo que permite trabajar de forma estructurada las técnicas cognitivas y conductuales y practicarlas entre sesiones. Veinte sesiones mensuales alargarían en exceso el tratamiento y dificultarían la continuidad. Cinco sesiones diarias no dejan tiempo para consolidar lo aprendido. Una única sesión de 8 horas no se corresponde con el formato de la TCC."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eeb") }, {"long_answer": "En el trastorno de ansiedad generalizada, las benzodiacepinas solo se recomiendan a corto plazo, durante un máximo de unas 4 semanas, en situaciones de crisis o cuando se necesita un control rápido de los síntomas, generalmente mientras empiezan a actuar otros tratamientos. Su uso prolongado favorece la tolerancia, la dependencia, el deterioro cognitivo y las caídas. No se prohíben en todos los casos. Su uso no es exclusivo de ancianos; de hecho, en las personas mayores se deben usar con especial precaución."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eec") }, {"long_answer": "Si se utilizan benzodiacepinas en el trastorno de ansiedad generalizada, se sugiere preferir las de vida media larga, porque mantienen niveles más estables, producen menos ansiedad de rebote entre dosis y menos síntomas de retirada y tienen un menor potencial de dependencia que las de vida media corta. La rapidez de acción de estas últimas favorece el refuerzo y el abuso. Buscar efectos sedantes intensos aumenta el riesgo de caídas y de deterioro psicomotor. La guía sí establece una preferencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef1") }, {"long_answer": "La guía no recomienda el uso de opipramol en el trastorno de ansiedad generalizada en atención primaria, por la escasa evidencia disponible sobre su eficacia y porque no está comercializado en España. Por eso no puede considerarse primera opción farmacológica, papel que corresponde a fármacos como los ISRS o los IRSN. Tampoco se recomienda en la ansiedad moderada. No se ha establecido como alternativa segura en ancianos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef2") }, {"long_answer": "La guía sugiere considerar la camomila (manzanilla) como complemento del tratamiento psicológico y farmacológico en el trastorno de ansiedad generalizada, dada su buena tolerancia y los datos que apuntan a una reducción de los síntomas, aunque con evidencia limitada. No se contraindica por riesgo de interacciones relevantes. No se recomienda como tratamiento único, porque no sustituye a la psicoterapia ni a los fármacos con eficacia demostrada. Sí existe una recomendación al respecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef3") }, {"long_answer": "Respecto a la pasiflora, la guía no puede emitir una recomendación a favor ni en contra en el trastorno de ansiedad generalizada, porque la confianza en la evidencia disponible es baja. Por eso no puede considerarse un tratamiento de primera línea. Tampoco se recomienda para el manejo crónico sin otras terapias. No es obligatoria en combinación con los ISRS, ya que no existe ninguna indicación que la haga necesaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef9") }, {"long_answer": "El diagnóstico del trastorno de ansiedad generalizada en atención primaria se basa en la entrevista clínica, que valora los criterios diagnósticos, la duración y el impacto funcional, apoyada en escalas validadas como la GAD-7 para el cribado y la evaluación de la gravedad. Un síntoma aislado no permite el diagnóstico. No existen pruebas de laboratorio diagnósticas, aunque algunas pueden solicitarse para descartar causas orgánicas. El diagnóstico visual sin entrevista ni cuestionarios carece de fiabilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977efb") }, {"long_answer": "En la toma de decisiones compartida sobre el tratamiento del trastorno de ansiedad generalizada deben considerarse la gravedad de los síntomas, la experiencia previa con otros tratamientos, las preferencias del paciente, la accesibilidad a las distintas intervenciones, su coste y su tolerabilidad, junto con la eficacia. Centrarse solo en la eficacia, solo en el coste o solo en la disponibilidad del profesional supone una visión parcial que no respeta el modelo de decisión compartida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977efc") }, {"long_answer": "En la campaña 2025-2026, la vacuna adaptada frente a COVID-19 se administra para potenciar la respuesta inmune frente a las variantes que circulan actualmente y reducir la morbilidad grave y la mortalidad, sobre todo en las personas mayores y en los grupos de riesgo. Su objetivo no es reducir la transmisión en personas jóvenes, ya que la protección frente a la infección es limitada y transitoria. Vacunar junto con la gripe es una estrategia operativa, no el objetivo. La eliminación del SARS-CoV-2 no es un objetivo alcanzable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eff") }, {"long_answer": "Las personas menores de 6 meses sin factores de riesgo no están incluidas en los grupos con indicación de vacunación frente a COVID-19, porque las vacunas no están autorizadas por debajo de esa edad. Sí están indicadas las personas con inmunosupresión, incluida la debida a la infección por VIH. También las embarazadas en cualquier trimestre, por su mayor riesgo de enfermedad grave. El personal sanitario que atiende a pacientes de riesgo se vacuna para protegerse y proteger a los pacientes vulnerables."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f00") }, {"long_answer": "Las recomendaciones para la temporada 2025-2026 establecen que debe respetarse un intervalo mínimo de 3 meses desde la última dosis de vacuna o desde la última infección por SARS-CoV-2 antes de administrar una nueva dosis, para optimizar la respuesta inmunitaria. Un mes o dos semanas son plazos demasiado cortos para obtener un beneficio adicional. Seis meses es un intervalo orientativo de otras recomendaciones previas, pero no el mínimo establecido en esta campaña."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f0b") }, {"long_answer": "En las personas que van a iniciar o intensificar un tratamiento inmunosupresor, se recomienda administrar la vacuna frente a COVID-19 con antelación suficiente, al menos unas semanas antes del inicio del tratamiento (3 semanas según el documento), para que el sistema inmune pueda generar una respuesta adecuada antes de quedar deprimido. Esperar 3 meses retrasaría innecesariamente el tratamiento. No vacunar sería un error, porque son pacientes de alto riesgo. La administración simultánea al inicio del tratamiento reduce mucho la respuesta vacunal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f0e") }, {"long_answer": "La vacuna frente a COVID-19 puede administrarse de forma conjunta con otras vacunas respiratorias, como la de la gripe, el neumococo o el VRS, y se recomienda aprovechar el mismo acto vacunal en las personas que tienen indicación de ambas, ya que no se reduce la eficacia ni aumenta de forma relevante la reactogenicidad. Por tanto, no es cierto que reduzca la eficacia. Tampoco es necesario separarlas en meses distintos, y no está prohibida por interacciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f12") }, {"long_answer": "Retrasar un tratamiento inmunosupresor para mejorar la respuesta a la vacuna frente a COVID-19 solo se plantea si el riesgo de exacerbación de la enfermedad de base lo permite, por lo que ese es el criterio principal y la decisión debe individualizarse con el especialista. La edad mayor de 70 años no determina el retraso del tratamiento. El tiempo transcurrido desde la última vacunación influye en el momento de vacunar, no en retrasar la inmunosupresión. La variante circulante no es un criterio para esta decisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f15") }, {"long_answer": "Según los datos de vigilancia recogidos en el documento, la incidencia máxima de hospitalizaciones por COVID-19 se alcanzó en la semana 26 de 2024, coincidiendo con la ola de verano, con unas 5,0 hospitalizaciones por 100.000 habitantes. Los valores de 0,2 y 1,4 por 100.000 infraestiman ese pico y corresponden a niveles de circulación más bajos. Diez hospitalizaciones por 100.000 habitantes sobrestiman la cifra observada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f16") }, {"long_answer": "Los datos de vigilancia de la temporada 2024-2025 muestran que aproximadamente el 85% de los fallecimientos por COVID-19 se produjo en personas mayores de 70 años, lo que justifica que la edad avanzada sea el principal criterio de priorización de la vacunación. Los porcentajes del 67% y el 74% infraestiman la concentración de la mortalidad en este grupo. El 50% la subestima todavía más."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f17") }, {"long_answer": "Según el documento, las personas de 50 años o más concentran aproximadamente el 50% de la carga de enfermedad por COVID-19 atendida en atención primaria, mientras que la carga hospitalaria y la mortalidad se concentran aún más en las edades avanzadas. Los menores de 1 año, el grupo de 30 a 40 años y el de 70 a 79 años representan, cada uno por separado, una proporción menor de la carga asistencial en atención primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f1b") }, {"long_answer": "El principal objetivo de la vacunación antigripal en la temporada 2025-2026 es reforzar la protección de las personas más vulnerables, como los mayores y las personas con condiciones de riesgo, para reducir la morbilidad grave y la mortalidad por gripe, además de proteger a quienes las cuidan. No se pretende reducir los contagios en toda la población. La gripe no puede eliminarse por su variabilidad antigénica. La vacunación conjunta con COVID-19 es una estrategia práctica, no el objetivo de la campaña."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f1c") }, {"long_answer": "Según el documento, la epidemia de gripe de la temporada 2024-2025 tuvo una intensidad baja y una duración epidémica más larga que la temporada anterior, con un periodo prolongado de circulación del virus. No fue de mayor intensidad ni más corta. No se registraron más hospitalizaciones con menos casos. Tampoco circuló exclusivamente el virus de la gripe A, ya que también se detectó circulación de gripe B."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f1e") }, {"long_answer": "En la temporada 2024-2025, aproximadamente el 76-77% de las hospitalizaciones por gripe correspondió a personas de 60 años o más, lo que refleja la carga de enfermedad grave en las edades avanzadas y justifica que este grupo sea prioritario en la vacunación. Menos del 20% o el 50% infraestiman claramente esta proporción. El 94% la sobrestima, ya que una parte de las hospitalizaciones se produce en niños y adultos más jóvenes con factores de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f1f") }, {"long_answer": "Entre las personas de 5 a 59 años, forman parte de la población diana de la vacunación antigripal quienes tienen condiciones de riesgo, como las enfermedades respiratorias crónicas, incluido el asma, además de otras enfermedades crónicas, la inmunosupresión o la obesidad mórbida. La obesidad leve no es un criterio. No se limita a personas institucionalizadas en hospitales de día. La exposición laboral sí es una indicación en ciertos colectivos, pero no es un criterio genérico para personas sin comorbilidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f31") }, {"long_answer": "Para la temporada 2025-2026 se recomienda aprovechar el contacto con el sistema sanitario para coadministrar las vacunas indicadas, especialmente las frente a infecciones respiratorias, como la de la gripe, la de la COVID-19, la antineumocócica o la del VRS, ya que la administración simultánea es segura y mejora las coberturas. No coadministrar o vacunar solo frente a la gripe supone perder oportunidades de vacunación. No es necesario esperar un mes entre vacunas inactivadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f42") }, {"long_answer": "Para proteger al recién nacido frente a la tosferina, se recomienda administrar una dosis de dTpa en cada embarazo a partir de la semana 27 y, preferentemente, entre las semanas 27 y 28, pudiendo administrarse hasta la semana 36, en el tercer trimestre. Así se garantiza el paso transplacentario de anticuerpos maternos antes del parto. En el primer trimestre los anticuerpos disminuirían antes del nacimiento. En el momento del parto o tras el puerperio no da tiempo a que lleguen anticuerpos al feto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f44") }, {"long_answer": "La vacunación antigripal durante el embarazo protege a la madre, que tiene mayor riesgo de complicaciones, y también al recién nacido mediante el paso transplacentario de anticuerpos. El documento destaca una reducción de alrededor del 20% de las neumonías graves en los hijos de madres vacunadas. No protege solo a la madre. Es falso que no aporte beneficio al neonato. Puede administrarse en cualquier trimestre y no se relaciona con malformaciones, por lo que no se limita al primer trimestre."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f47") }, {"long_answer": "La vacuna dTpa, que protege frente a difteria, tétanos y tosferina acelular, debe administrarse en cada embarazo, aunque la mujer esté vacunada previamente o tenga embarazos muy seguidos, porque los anticuerpos frente a la tosferina disminuyen rápidamente y hay que garantizar su paso transplacentario al recién nacido. La triple vírica y la vacuna de la varicela son vacunas vivas contraindicadas en el embarazo. La vacuna antigripal se recomienda en la gestación, pero no protege frente a la tosferina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f48") }, {"long_answer": "La vacuna de la fiebre amarilla es de virus vivos atenuados, por lo que en principio se evita durante el embarazo y solo debe administrarse si el viaje a una zona endémica es inevitable y el riesgo de infección es alto, ya que en ese caso el beneficio supera el riesgo teórico. No es una vacuna rutinaria en la gestación. No está indicada en cualquier viaje internacional, sino solo a zonas de riesgo. No existe una vacuna inactivada frente a la fiebre amarilla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f4f") }, {"long_answer": "Durante la lactancia pueden administrarse con seguridad las vacunas inactivadas, como las de la gripe, el tétanos, la tosferina o la hepatitis B, ya que no suponen ningún riesgo para el lactante. La fiebre amarilla es una vacuna viva que debe evitarse durante la lactancia, sobre todo en lactantes pequeños, por el riesgo de transmisión del virus vacunal. La BCG no forma parte de la vacunación habitual en la lactancia. La vacuna antigripal intranasal es atenuada y no es la indicada en el adulto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f50") }, {"long_answer": "La vacuna de la fiebre amarilla debe evitarse durante la lactancia, especialmente en lactantes menores de 6 meses, porque se han descrito casos de enfermedad neurológica en lactantes por transmisión del virus vacunal a través de la leche materna. Solo se administra si el viaje a una zona de riesgo es inevitable. La vacuna inactivada de la gripe y la de la hepatitis A son seguras en la lactancia. La triple vírica, aunque es una vacuna viva, puede administrarse durante la lactancia, ya que no se ha demostrado riesgo para el lactante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f56") }, {"long_answer": "En embarazadas con evidencia documentada de haber recibido al menos una dosis de vacuna frente a la rubeola, no se aconseja realizar el cribado serológico prenatal, porque la efectividad vacunal es muy alta y las pruebas serológicas tienen una sensibilidad limitada, lo que genera resultados falsamente negativos y revacunaciones innecesarias. No debe realizarse siempre. No tiene sentido repetirlo cada trimestre. Sustituirlo por seguimiento clínico no es la recomendación, ya que la documentación vacunal basta para considerar a la mujer protegida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f5c") }, {"long_answer": "En el documento de consenso, la cohorte de invitación del programa de cribado de cáncer de cérvix está formada por las mujeres con invitación válida en el año índice a las que se realiza la prueba primaria de cribado en ese año o hasta el 31 de diciembre del año siguiente. No incluye mujeres sin invitación válida. Las mujeres con exclusión temporal no forman parte de la cohorte. El cribado oportunista queda fuera de los indicadores del programa poblacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f60") }, {"long_answer": "La tasa de participación en el cribado de cáncer de cérvix se calcula dividiendo el número de mujeres a las que se ha realizado la prueba de cribado tras la invitación entre el número de mujeres con invitación válida, y multiplicando por 100. Las dos primeras fórmulas relacionan las invitaciones con la cohorte, pero no miden quién participa. Dividir entre la población diana corresponde a la cobertura de examen, no a la tasa de participación, que se refiere solo a las mujeres invitadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f61") }, {"long_answer": "En el cribado de cáncer de cérvix, se considera falso positivo a la mujer con una prueba primaria de cribado positiva que, tras la colposcopia y los estudios de confirmación, no recibe un diagnóstico de cáncer invasivo ni de lesión de riesgo. Una prueba primaria negativa sin diagnóstico corresponde a un verdadero negativo. Las mujeres con lesión de alto grado confirmada son verdaderos positivos. Las mujeres sin indicación de colposcopia no se incluyen en el numerador de este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f64") }, {"long_answer": "En el programa de cribado de cáncer de mama, el diagnóstico previo de cáncer de mama es un criterio de exclusión permanente, porque estas mujeres siguen controles específicos de seguimiento oncológico y no un cribado poblacional. Haber tenido una mamografía negativa en los últimos dos años no excluye, sino que forma parte del intervalo normal de cribado. La inmovilidad temporal sería, en todo caso, una exclusión temporal. Los síntomas mamarios benignos requieren valoración clínica, pero no constituyen una exclusión permanente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f69") }, {"long_answer": "Según el consenso, no se consideran cánceres de intervalo los diagnosticados en mujeres que estaban pendientes de un control intermedio o de una consulta de seguimiento hospitalario derivada del propio cribado, ya que no habían recibido un resultado negativo definitivo. El cáncer de intervalo es, precisamente, el diagnosticado tras una mamografía con resultado negativo y dentro de la ventana de intervalo establecida, antes de la siguiente cita. El cáncer detectado en la mamografía de cribado rutinaria es un cáncer detectado por cribado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978053") }, {"long_answer": "Para los medicamentos sujetos a prescripción médica, las enfermeras pueden indicar y autorizar su dispensación mediante la correspondiente orden de dispensación, conforme a lo regulado en el Real Decreto 1718/2010 sobre receta médica y órdenes de dispensación, en el marco de protocolos validados. No se emite una receta médica tradicional, que corresponde al médico. No se exige supervisión permanente de un farmacéutico. Tampoco es necesario justificar una urgencia sanitaria para la dispensación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f70") }, {"long_answer": "En los programas de cribado, la tasa de retención es el porcentaje de mujeres o personas que, habiendo participado en una ronda, vuelven a participar en la ronda siguiente, por lo que mide la adherencia al programa a lo largo del tiempo. No mide la finalización del tratamiento tras el diagnóstico. Tampoco las hospitalizaciones por complicaciones. Las exclusiones permanentes forman parte de otros indicadores de la población elegible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f77") }, {"long_answer": "En el cribado de cáncer colorrectal, el documento de consenso fija un estándar mínimo aceptable del 45% para la cobertura de examen en el año índice, y un valor deseable del 65%, en línea con las guías europeas de calidad. El 55% está entre ambos estándares, pero no es el mínimo establecido. El 65% corresponde al nivel deseable, no al mínimo. El 75% supera los estándares propuestos para este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f7a") }, {"long_answer": "La cobertura de invitación no puede alcanzar el 100% de la población diana porque existen diferencias entre los criterios de exclusión de los programas y porque una parte de la población no es elegible para el cribado, por ejemplo por un diagnóstico previo de cáncer, por estar en seguimiento específico o por otras exclusiones. Los fallos de comunicación no son la explicación estructural de este indicador. La falta de presupuesto tampoco lo es. La baja aceptación de la población afecta a la participación, no a la cobertura de invitación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f7d") }, {"long_answer": "En menores con inmunodepresión grave incluidos en los grupos de riesgo para enfermedad meningocócica, el calendario recomienda la vacuna MenACWY con una pauta de 2 dosis y una dosis de recuerdo a los 5 años mientras se mantenga el riesgo. La vacuna MenB no se administra con recuerdos anuales. Al ser vacunas inactivadas, la vacunación no está contraindicada en la inmunodepresión, sino especialmente indicada. Una dosis única de MenACWY sin refuerzos no garantiza una protección duradera en personas con respuesta inmune disminuida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f7e") }, {"long_answer": "En menores con condiciones de riesgo, la recomendación frente a tétanos, difteria y tosferina (DTPa, dTpa o Td, según la edad) es verificar el estado de vacunación y completar la pauta del calendario si está incompleta, sin necesidad de dosis adicionales específicas por la condición de riesgo. No se administra una dosis extra independientemente del estado previo, porque podría aumentar las reacciones locales. Estas vacunas son inactivadas y no están contraindicadas en inmunodeprimidos. La elección de Td depende de la edad y de la pauta, no solo de tener más de 10 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f82") }, {"long_answer": "En menores con asplenia anatómica o disfunción esplénica grave, el calendario recomienda vacunar frente a enfermedad meningocócica con ambas vacunas: MenACWY y MenB, con sus dosis de recuerdo, porque la falta de función esplénica favorece infecciones fulminantes por bacterias encapsuladas. Administrar solo MenB o solo MenACWY sin refuerzos dejaría una protección incompleta. Son vacunas inactivadas, por lo que la vacunación no está contraindicada, sino que es una de las indicaciones prioritarias del calendario de grupos de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f87") }, {"long_answer": "En menores de 5 años con condiciones de riesgo que no han pasado la COVID-19 ni han sido vacunados previamente, el calendario recoge una pauta de 3 dosis en la temporada, con la formulación pediátrica adaptada, ya que a esa edad hacen falta varias dosis para generar una respuesta adecuada. La dosis única estacional se reserva para quienes ya tienen inmunidad previa por vacunación o infección. Sí está indicada la vacunación en menores de 5 años con condiciones de riesgo, a partir de los 6 meses, y la pauta de 2 dosis separadas 4 semanas no corresponde a este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f8d") }, {"long_answer": "Los menores con fístula de líquido cefalorraquídeo o con implante coclear tienen un riesgo elevado de meningitis bacteriana, sobre todo neumocócica, por lo que el calendario de grupos de riesgo recomienda vacunarlos frente a neumococo y frente a Haemophilus influenzae tipo b. La vacuna antipoliomielítica inactivada forma parte del calendario sistemático, pero no responde a este riesgo específico. La vacuna antigripal sola no previene la meningitis bacteriana. Estas situaciones no contraindican ninguna vacuna."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f99") }, {"long_answer": "Los menores en tratamiento prolongado con ácido acetilsalicílico deben vacunarse anualmente frente a la gripe por el riesgo de síndrome de Reye si se infectan, y el calendario de grupos de riesgo lo recoge a partir de los 5 años, ya que por debajo de esa edad la vacunación antigripal es sistemática para todos los niños desde los 6 meses. La vacuna atenuada intranasal está contraindicada en tratamientos con salicilatos por ese mismo riesgo. No vacunar sería un error, y no existe una pauta bianual de dos dosis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f9e") }, {"long_answer": "Tras un trasplante de progenitores hematopoyéticos se pierde la memoria inmunológica adquirida con las vacunas previas, por lo que hay que revacunar como si la persona no estuviera vacunada. Por eso el calendario de grupos de riesgo recoge una pauta completa de varias dosis frente a difteria, tétanos y tosferina (4 dosis), iniciada a partir de los 6-12 meses del trasplante. Una o dos dosis serían insuficientes para restablecer la protección. La vacunación sí se recomienda, porque se trata de vacunas inactivadas que pueden administrarse con seguridad en estos pacientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa9") }, {"long_answer": "En los adultos con condiciones de riesgo que reciben la vacuna frente al meningococo B (asplenia, déficit de complemento, tratamiento con eculizumab, trasplante de progenitores hematopoyéticos o antecedente de enfermedad meningocócica), se recomienda una dosis de recuerdo 1 año después de completar la primovacunación y, posteriormente, cada 5 años mientras persista el riesgo. Tres meses es un plazo demasiado corto para un recuerdo. Afirmar que no se administran recuerdos es incorrecto, y esperar 5 años al primer recuerdo dejaría un periodo de protección decreciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fad") }, {"option_1": "Embarazo, inmunodepresión e infección por VIH con CD4 < 200/μl", "option_4": "Solo la reacción alérgica grave (anafilaxia) a una dosis previa o a algún componente de la vacuna", "answer": 4, "long_answer": "La vacuna frente a la hepatitis B es recombinante e inactivada, por lo que la única contraindicación es haber presentado una reacción alérgica grave (anafilaxia) a una dosis previa o a alguno de sus componentes. No está contraindicada en el embarazo, en personas inmunodeprimidas ni en personas con infección por VIH, que de hecho son grupos en los que está recomendada, a veces con pautas reforzadas. Tampoco lo está en mayores de 65 años ni en personas con enfermedad hepática crónica, en quienes está especialmente indicada para evitar descompensaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb0") }, {"long_answer": "La protección frente a Haemophilus influenzae tipo b en adultos con condiciones de riesgo, como la asplenia, el déficit de complemento o el trasplante de progenitores hematopoyéticos, se consigue con la vacuna Hib conjugada específica. La dTpa protege frente a difteria, tétanos y tosferina. La MenACWY protege frente a cuatro serogrupos de meningococo. La vacuna antineumocócica previene la enfermedad por Streptococcus pneumoniae. Aunque estas vacunas suelen indicarse a los mismos grupos de riesgo, ninguna de ellas cubre Haemophilus influenzae tipo b."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb2") }, {"long_answer": "La vacuna MenB está indicada en adultos con asplenia, déficit de complemento, tratamiento con eculizumab o ravulizumab, antecedente de enfermedad meningocócica invasora y trasplante de progenitores hematopoyéticos. En estos grupos se recomienda un recuerdo al año de completar la primovacunación y, después, cada 5 años mientras persista el riesgo. La enfermedad hepática crónica no es indicación de MenB. La infección por VIH con CD4 bajos es indicación de MenACWY, no de MenB con recuerdos. El personal sanitario sin exposición no forma parte de los grupos diana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb8") }, {"long_answer": "Antes de iniciar o completar la pauta de Td en adultos hay que revisar el estado vacunal previo documentado, para contabilizar las dosis ya recibidas sin reiniciar la pauta, y valorar el riesgo individual de tétanos, por ejemplo ante una herida tetanígena. No es necesario determinar anticuerpos antimeningococo, que no guardan relación con esta vacuna. Tampoco se exige una serología positiva frente a difteria. Los antecedentes de varicela son irrelevantes para la vacunación frente a tétanos y difteria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb9") }, {"long_answer": "En mujeres con lesión intraepitelial de alto grado (CIN2+), el calendario recomienda la vacunación frente al VPH con pauta de 3 dosis, independientemente de la edad, preferentemente antes del tratamiento escisional de la lesión o lo antes posible después de finalizarlo, porque reduce el riesgo de recurrencia. La pauta de 1 dosis al año del tratamiento no es la recomendada en este grupo. Decir que no está recomendada es incorrecto, y la indicación no se limita a menores de 25 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fbc") }, {"long_answer": "Se denomina calendario acelerado o de rescate a la vacunación de personas que no tienen documentadas las vacunas recomendadas para su edad, de modo que se completan las dosis necesarias en el menor tiempo posible, respetando las edades mínimas y los intervalos mínimos entre dosis. No consiste en administrar el calendario habitual en sus plazos, que es la vacunación sistemática. No es exclusivo de mayores de 65 años, ya que se aplica sobre todo a menores y personas migrantes. Nunca implica reducir la dosis de las vacunas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fbe") }, {"long_answer": "En personas procedentes de países que utilizan vacuna oral bivalente (VPOb), que solo contiene los serotipos 1 y 3, se considera vacunación completa documentada un esquema que incluya dosis de vacuna inactivada (VPI), en concreto dos dosis de VPI junto con tres dosis de VPOb, ya que la VPI aporta la protección frente al serotipo 2. Una sola dosis de VPI o la combinación de una VPI y una VPOb no completan el esquema. Exigir solo VPI sin tener en cuenta la vacuna oral ignoraría dosis válidas ya administradas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc8") }, {"long_answer": "Infanrix-IPV tiene autorizado en España su uso solo como dosis de recuerdo, por lo que no tiene indicación aprobada en primovacunación. Sin embargo, el documento considera que podría usarse fuera de ficha técnica en las mismas condiciones que Tetraxim, dada su composición y su perfil de seguridad similares y su autorización en primovacunación en otros países europeos. Es falso que Tetraxim no pueda usarse en primovacunación, porque está autorizada desde los 2 meses. Ninguna de las dos se limita a recuerdos después de los 5 años, e Infanrix-IPV no está prohibida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fcb") }, {"long_answer": "Según el documento, Infanrix-IPV puede contener ácido paraaminobenzoico, procedente del medio de cultivo, mientras que Tetraxim no, y este excipiente puede causar reacciones alérgicas en personas sensibilizadas. El glutaraldehído y la estreptomicina pueden encontrarse como trazas del proceso de fabricación de Tetraxim. El fenoxietanol forma parte de los excipientes de Tetraxim. Por tanto, ninguno de estos tres es el excipiente que diferencia a Infanrix-IPV de Tetraxim en el sentido que plantea la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd1") }, {"long_answer": "Tanto Infanrix-IPV como Tetraxim se presentan como suspensión inyectable en jeringa precargada de 0,5 ml y se administran por vía intramuscular, en el vasto externo del muslo en lactantes o en el deltoides en niños mayores. No existen formas orales de estas vacunas. La vía subcutánea en ampollas de 1 ml no corresponde a su presentación. Tampoco hay formulaciones intranasales de vacunas DTPa-VPI. La vía intramuscular reduce las reacciones locales asociadas al adyuvante de aluminio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd3") }, {"long_answer": "Según el documento, Infanrix-IPV contiene al menos 30 UI de toxoide diftérico por dosis, mientras que la ficha técnica de Tetraxim indica al menos 20 UI, aunque su valor medio real ronda también las 30 UI. Por eso, en la práctica, ambas aportan una cantidad similar de toxoide diftérico de alta carga antigénica, propia de las vacunas infantiles. No es cierto que ambas tengan exactamente 20 UI, ni que Tetraxim contenga más toxoide que Infanrix-IPV. Ambas vacunas contienen toxoide diftérico, ya que protegen frente a la difteria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd5") }, {"long_answer": "Las vacunas hexavalentes como Infanrix Hexa reúnen en una sola inyección seis antígenos (difteria, tétanos, tosferina acelular, poliomielitis inactivada, Haemophilus influenzae tipo b y hepatitis B), lo que reduce el número de pinchazos y facilita completar en menos visitas la vacunación acelerada de menores de 7 años con pauta incompleta. No contiene solo dos antígenos. Está indicada precisamente en menores de 7 años. Puede administrarse junto con otras vacunas del calendario en la misma sesión, en lugares anatómicos distintos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd7") }, {"long_answer": "En la vacunación acelerada, las dosis administradas antes de la edad mínima o con un intervalo inferior al mínimo recomendado no se consideran válidas, porque la respuesta inmune puede ser insuficiente, y deben repetirse respetando el intervalo mínimo desde la dosis no válida. Solo se admite un margen de tolerancia de pocos días. No se aceptan todas las dosis como válidas sin importar el intervalo. Tampoco se valida solo la primera dosis ni se anulan las posteriores: se evalúa cada dosis individualmente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fdc") }, {"long_answer": "La principal ventaja de la vacuna inactivada (VPI), utilizada en exclusiva en España, es que no contiene virus vivos y por tanto elimina el riesgo de poliomielitis paralítica asociada a la vacuna (PPAV) y la aparición de poliovirus derivados de vacuna. Por el contrario, es la VPO la que genera una inmunidad intestinal más potente, por lo que esa opción describe una ventaja de la vacuna oral. La VPI no requiere menos dosis. Tampoco se administra por vía oral, sino por vía intramuscular, habitualmente en vacunas combinadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe1") }, {"long_answer": "El plan de erradicación fija como objetivo mínimo alcanzar a nivel nacional una cobertura de al menos el 95% con 3 dosis de vacuna frente a la poliomielitis, nivel necesario para mantener la inmunidad de grupo y evitar la reintroducción y circulación del virus. Coberturas del 80%, el 70% o el 50% dejarían bolsas de población susceptible suficientes para permitir la transmisión en caso de importación de un poliovirus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe4") }, {"long_answer": "Para descartar la infección por poliovirus en casos sospechosos, como una parálisis flácida aguda, se recomienda analizar prioritariamente muestras de heces, idealmente dos muestras separadas 24-48 horas y recogidas en los primeros 14 días tras el inicio de la parálisis, ya que el virus se excreta por vía intestinal de forma prolongada y en mayor cantidad. La viremia es breve, por lo que la sangre tiene poca rentabilidad. Las muestras respiratorias pueden ser útiles al inicio, pero no de forma exclusiva. La piel no tiene utilidad diagnóstica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe7") }, {"long_answer": "Según el plan, el laboratorio debe comunicar el resultado definitivo del estudio de una muestra sospechosa de poliovirus en un plazo de 14 días desde su recepción, de acuerdo con los indicadores de calidad de la red de laboratorios de la OMS, que incluyen el aislamiento en cultivo celular y la diferenciación intratípica. Siete días o 24 horas son plazos que no permiten completar el aislamiento en cultivo. Treinta días supera el tiempo considerado aceptable para la vigilancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe8") }, {"long_answer": "Además del objetivo nacional del 95% con tres dosis, el plan establece que la cobertura de vacunación frente a la poliomielitis no debe ser inferior al 90% en ningún área de salud o unidad territorial equivalente, para evitar bolsas de población susceptible donde un virus importado pudiera circular. El 95% es el objetivo nacional, no el mínimo por área. Coberturas del 85% o del 75% se consideran insuficientes y obligarían a intensificar las actuaciones en esa zona."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe9") }, {"long_answer": "Ante la detección confirmada de poliovirus vacunal tipo 1 o 3 en una persona sin parálisis, el plan prevé activar un grupo de apoyo técnico que evalúe la situación, defina el área de riesgo y establezca las medidas de respuesta proporcionadas, como el estudio de contactos, la revisión de coberturas o la vacunación complementaria. Aunque se trate de una cepa vacunal, no se puede ignorar, porque podría indicar transmisión. Las muestras nunca se destruyen. Una cuarentena estricta de todo un barrio no es una medida contemplada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fee") }, {"long_answer": "Una persona sin parálisis que excreta poliovirus, por ejemplo un inmunodeficiente o un contacto asintomático, puede eliminar el virus por las heces durante semanas o meses y suponer un riesgo de diseminación en la comunidad. Por eso requiere estudio, seguimiento y medidas de control hasta que deje de excretarlo. No es una persona sin riesgo de transmisión. No se descarta para la vigilancia activa por no tener síntomas. La excreción no implica que tenga una inmunidad natural completa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff2") }, {"long_answer": "El plan de acción ante la detección de poliovirus no utiliza un único escenario general para todas las situaciones, por lo que esa es la opción que no se ajusta al plan. Contempla una fase de prealerta y tres escenarios de alerta con acciones específicas, diferenciados según el tipo de poliovirus detectado (salvaje, derivado de vacuna o similar a Sabin) y según el tipo de muestra, distinguiendo entre la vigilancia en humanos y la vigilancia ambiental en aguas residuales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff5") }, {"long_answer": "Se considera evento importado la detección de poliovirus en una persona con antecedente de viaje o contacto con zonas donde circula el virus, sin evidencia de transmisión local en España. La circulación sostenida en la comunidad define un brote o una transmisión autóctona, no un evento importado. Un caso autóctono no es importado por definición. La pérdida de inmunidad poblacional es un factor de riesgo para la transmisión, no un tipo de evento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977066") }, {"long_answer": "La Estrategia de Atención al Parto Normal del SNS señala que en España la posición más habitual durante el periodo expulsivo sigue siendo el decúbito dorsal o litotomía, una postura que facilita la visualización y las maniobras del profesional pero no la fisiología del parto. Por ello la Estrategia recomienda revisar esta práctica y favorecer que la mujer elija la postura. La posición semirrecostada, la de cuclillas y la sentada son posturas alternativas que se promueven por sus ventajas, pero no constituyen la práctica habitual descrita en nuestro medio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977067") }, {"long_answer": "La evidencia recogida en la Estrategia de Atención al Parto Normal muestra que adoptar una posición vertical o lateral, frente al decúbito dorsal o la litotomía, se asocia a una reducción de la duración del periodo expulsivo, además de menos partos asistidos (instrumentales) y menos episiotomías. El aumento de desgarros perineales de segundo grado es un efecto descrito con estas posturas, por lo que no puede considerarse un beneficio. El aumento de partos asistidos y la mayor práctica de episiotomías son, precisamente, lo contrario de lo que se observa con las posiciones verticales o laterales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977070") }, {"long_answer": "Según la evidencia recogida en la Estrategia de Atención al Parto Normal, cualquier posición vertical o lateral durante el expulsivo, comparada con la supina o la litotomía, se asocia a una menor práctica de episiotomías, junto con una reducción de la duración del expulsivo y de los partos asistidos. La mayor pérdida de sangre es un posible efecto no deseado descrito con algunas posturas verticales, no un beneficio. La mayor duración del parto y el aumento de partos asistidos son contrarios a lo observado con estas posiciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977075") }, {"long_answer": "La Estrategia de Atención al Parto Normal recomienda animar a las mujeres a adoptar la posición que les resulte más cómoda durante el periodo expulsivo, de modo que puedan decidir libremente qué postura adoptar, informadas por los profesionales. Este criterio se basa en los beneficios de las posturas verticales o laterales y en el respeto a la autonomía de la mujer. Permitir solo la posición supina, restringir la elección o impedir que la gestante decida contradicen directamente esta recomendación y reproducen un modelo de atención intervencionista que la Estrategia pretende superar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977076") }, {"option_1": "Realizar episiotomía sistemática en todas las primíparas", "option_2": "Practicar la episiotomía de forma restrictiva, solo cuando esté indicada", "long_answer": "La Estrategia de Atención al Parto Normal recomienda una práctica restrictiva de la episiotomía, reservándola para situaciones con indicación clínica, porque su uso rutinario no reduce el traumatismo perineal grave y sí aumenta el dolor, la necesidad de sutura y otras complicaciones. Realizarla de forma sistemática en primíparas o de forma rutinaria en todos los partos carece de respaldo en la evidencia. Tampoco se recomienda prohibirla en todos los casos, ya que existen situaciones, como el compromiso fetal o la necesidad de un parto instrumental, en las que puede estar justificada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97707b") }, {"long_answer": "Entre los indicadores que propone la Estrategia de Atención al Parto Normal para evaluar la participación activa de las mujeres en la toma de decisiones figura el número de maternidades que incluyen en su protocolo las recomendaciones de participación de las mujeres en el parto, como la información y el plan de parto. Este indicador refleja si los centros han incorporado formalmente ese enfoque. Los buenos resultados obstétricos, el personal formado en lactancia o la tasa de cesáreas son indicadores de calidad o de resultado, pero no miden la participación de las mujeres en las decisiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97707e") }, {"long_answer": "La Estrategia de Atención al Parto Normal insiste en que la información debe adaptarse a las necesidades de cada mujer, y en el caso de usuarias con discapacidad debe ajustarse a sus capacidades, utilizando formatos y canales accesibles (lengua de signos, braille, lectura fácil, apoyos visuales). Solo así se garantiza que puedan participar en las decisiones en igualdad de condiciones. Ocultar información por la discapacidad o no atender a sus necesidades vulnera su derecho a la información, y ofrecer una información general idéntica para todas no asegura la comprensión ni la accesibilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97707f") }, {"long_answer": "La participación activa de las mujeres en la toma de decisiones implica que, tras recibir información adecuada y basada en la evidencia, evalúen las distintas opciones junto a los profesionales y decidan de forma compartida lo que mejor se ajusta a sus valores y preferencias. Decidir sin conocer las alternativas no es una decisión informada. Depender exclusivamente del criterio profesional corresponde al modelo paternalista que la Estrategia de Atención al Parto Normal pretende superar, y no participar en las decisiones es justo lo opuesto a la participación activa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977082") }, {"long_answer": "La Estrategia de Atención al Parto Normal plantea que la participación de las mujeres en la toma de decisiones persigue adoptar un nuevo modelo de relación entre profesionales y usuarias, basado en la información, el respeto a la autonomía y la decisión compartida, que sustituya al modelo paternalista tradicional. Mantener el modelo paternalista, excluir a las mujeres de las decisiones o no modificar la relación clínica contradicen el propósito de esta línea estratégica, que busca una atención centrada en la mujer y una experiencia de parto más satisfactoria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977085") }, {"long_answer": "La Estrategia de Atención al Parto Normal señala que compartir con las usuarias información veraz sobre la efectividad de las prácticas, incluidas sus limitaciones, favorece expectativas realistas y decisiones informadas, lo que contribuye a reducir las reclamaciones ante resultados adversos. Cuando la mujer conoce de antemano los beneficios, riesgos e incertidumbres de cada intervención, es menos probable que perciba un resultado desfavorable como una mala praxis. No es esperable que aumenten las reclamaciones ni que el efecto sea nulo, y no informar sobre las limitaciones iría contra el derecho a la información."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977088") }, {"long_answer": "La toma de decisiones conjunta exige que, además de la mejor evidencia disponible, se incorporen las preferencias, valores y expectativas de las usuarias, de modo que la decisión final sea compartida entre la mujer y el equipo profesional. Proporcionar información sin evidencias documentadas no permite una decisión informada. No considerar las preferencias de las usuarias corresponde al modelo paternalista, y dificultar la comunicación entre usuarias y profesionales impide cualquier proceso de decisión compartida, por lo que ninguna de esas opciones cumple los requisitos que plantea la Estrategia."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97708f") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977095") }, {"long_answer": "La Estrategia de Atención al Parto Normal recomienda evitar el rasurado perineal sistemático o rutinario, porque la evidencia no muestra beneficios en la reducción de infecciones ni en la facilidad de la sutura, y sí produce molestias, irritación y microlesiones cutáneas. Realizarlo a todas las parturientas carece de justificación. La opción de no realizarlo en ningún caso es demasiado categórica, ya que puede plantearse un recorte o rasurado del vello si la mujer lo prefiere o si es necesario para una sutura. Supeditarlo solo a la petición de la mujer no es la recomendación formulada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977098") }, {"long_answer": "La Estrategia de Atención al Parto Normal, siguiendo a la OMS, recomienda registrar la evolución del trabajo de parto mediante el partograma, ya que es una herramienta sencilla que permite visualizar de forma gráfica la dilatación, el descenso de la presentación, el bienestar fetal y materno, y detectar a tiempo desviaciones de la normalidad. No utilizarlo nunca o no registrar la evolución contradice esta recomendación. Limitarlo a los embarazos de alto riesgo tampoco es correcto, puesto que su utilidad se extiende también a la vigilancia del parto de bajo riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97709c") }, {"long_answer": "La Estrategia en Salud Cardiovascular del SNS (ESCAV) tiene como objetivo principal promover la salud cardiovascular de la ciudadanía y mejorar el nivel de salud cardiovascular de la población, con un enfoque que abarca desde la promoción y la prevención hasta la atención y la rehabilitación. Mejorar la calidad de vida de las personas con ECV crónica, impulsar medidas efectivas y sostenibles y potenciar la atención integral en la fase aguda son objetivos específicos o líneas de actuación que se derivan de ese objetivo general, pero no constituyen su finalidad principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97709d") }, {"option_1": "Primacía de la rentabilidad económica sobre la equidad", "option_3": "Centralización de toda la atención en el hospital", "option_4": "Atención fragmentada por niveles asistenciales", "long_answer": "La seguridad del paciente es uno de los valores que la ESCAV considera que deben estar presentes de forma transversal en todos sus planteamientos, junto con otros como la equidad, la perspectiva de género o la continuidad asistencial. Implica reducir al mínimo los riesgos y los daños evitables en toda la atención cardiovascular. Anteponer la rentabilidad económica a la equidad, centralizar toda la atención en el hospital o fragmentarla por niveles asistenciales son planteamientos contrarios a los principios de la Estrategia, que apuesta por la equidad, la coordinación y la atención integrada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a5") }, {"question": "¿Cuál es la principal causa evitable de morbimortalidad cardiovascular según el documento?", "long_answer": "La ESCAV identifica el tabaquismo como la principal causa evitable de morbimortalidad cardiovascular, ya que su eliminación tiene un impacto directo y rápido sobre el riesgo de cardiopatía isquémica, ictus y enfermedad arterial periférica, y es el factor sobre el que la intervención preventiva resulta más rentable. La hipertensión arterial, la hipercolesterolemia y la diabetes son factores de riesgo cardiovascular de gran relevancia y elevada prevalencia, pero en la Estrategia no se señalan como la principal causa evitable, sino como factores que requieren detección precoz y control mantenido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a7") }, {"long_answer": "La ESCAV, en su enfoque de equidad y género, recoge que las dificultades de conciliación familiar y laboral someten a muchas mujeres a una mayor presión y estrés en ambos ámbitos, por la doble jornada y la carga de cuidados. Este estrés psicosocial mantenido actúa como factor de riesgo cardiovascular y dificulta además la adopción de hábitos saludables. Los accidentes laborales y la exposición a tóxicos no son la dificultad descrita en relación con la conciliación, y un mejor equilibrio entre trabajo y familia sería precisamente lo contrario del problema planteado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a9") }, {"long_answer": "La ESCAV señala, dentro del análisis de las desigualdades de género, que el estigma social del sobrepeso es uno de los factores que dificultan el acceso de las mujeres al sistema sanitario, ya que el temor a ser juzgadas por su peso puede retrasar las consultas y el seguimiento. La falta de seguro médico no es una barrera relevante en un sistema de cobertura universal como el español. La escasez de instalaciones en el medio rural o la falta de educación sanitaria son barreras generales, no las específicas de las mujeres que destaca el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770af") }, {"long_answer": "La ESCAV identifica el estrés laboral como uno de los estresores crónicos que deterioran la salud cardiovascular de las mujeres, sumado a menudo a la carga de cuidados y a la dificultad de conciliación. El estrés crónico activa mecanismos neurohormonales que favorecen la hipertensión, la inflamación y la adopción de conductas de riesgo. El sedentarismo, el consumo de tabaco y la mala alimentación son factores de riesgo cardiovascular conductuales, relacionados con el estilo de vida, pero no se consideran estresores psicosociales crónicos como el que plantea la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d8") }, {"long_answer": "La ESCAV recoge que las personas con enfermedad cardiovascular presentaron durante la pandemia de COVID-19 una mayor susceptibilidad a una evolución grave de la infección, con más ingresos, complicaciones y mortalidad, además de verse afectadas por el retraso en la atención de sus procesos. No se observó una reducción de la letalidad en personas mayores, sino lo contrario. El aumento de incidencia de ECV no se señala como el impacto principal, y tampoco hubo una mejora en la calidad de vida de estos pacientes, que sufrieron interrupciones en su seguimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d9") }, {"long_answer": "Las estrategias de salud del SNS, entre ellas la ESCAV, tienen su marco normativo en la Ley 16/2003, de Cohesión y Calidad del Sistema Nacional de Salud, que contempla la elaboración de planes integrales y estrategias de salud para las enfermedades más prevalentes, aprobados por el Consejo Interterritorial. La Ley General de Educación no tiene relación con este marco, por lo que la primera opción es incorrecta aunque la Ley General de Sanidad sí forme parte del contexto normativo general. El supuesto Real Decreto de Sanidad Pública no existe y la protección de la salud pública no es el origen de la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770da") }, {"question": "¿Cuál de los siguientes es uno de los ámbitos de actuación identificados como prioritarios en la ESCAV?", "option_2": "Control de las infecciones asociadas a la asistencia sanitaria", "option_3": "Gestión de las listas de espera quirúrgicas", "option_4": "Atención a la salud mental perinatal", "long_answer": "La promoción de la salud y la prevención de la enfermedad cardiovascular es uno de los ámbitos de actuación prioritarios de la ESCAV, ya que una gran parte de la carga de ECV es evitable actuando sobre los estilos de vida y los factores de riesgo. Junto a él, la Estrategia aborda la atención integral a la persona con ECV aguda y crónica y una serie de ejes transversales. El control de las infecciones asociadas a la asistencia, la gestión de listas de espera quirúrgicas y la salud mental perinatal corresponden a otros planes y estrategias del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e1") }, {"long_answer": "La ESCAV explica que la socialización diferencial de género en la infancia influye en la salud cardiovascular de las mujeres, ya que las niñas tienden a realizar menos actividad física y a adoptar hábitos sedentarios desde edades tempranas, patrón que suele mantenerse en la vida adulta y aumenta el riesgo cardiovascular. La exposición a tóxicos o la falta de acceso a alimentos saludables no son aspectos ligados a la socialización de género. La presión sobre la imagen corporal existe, pero no es el aspecto que el documento relaciona específicamente con el riesgo cardiovascular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e8") }, {"long_answer": "La ESCAV señala la edad como el factor de riesgo más relevante en el desarrollo de enfermedades cardiovasculares: la incidencia y la prevalencia de ECV aumentan de forma marcada con los años, y el envejecimiento de la población explica buena parte del incremento de la carga de enfermedad. Es un factor no modificable, por lo que las intervenciones se dirigen al resto. El tabaquismo, el sedentarismo y el consumo de alcohol son factores de riesgo modificables muy importantes y prioritarios para la prevención, pero no alcanzan el peso de la edad en el riesgo cardiovascular global."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ed") }, {"long_answer": "La ESCAV recoge que la supervivencia de la parada cardiaca extrahospitalaria en España es baja, cercana al 10 %, debido sobre todo al escaso número de testigos que inician la reanimación cardiopulmonar y a la limitada disponibilidad y uso de desfibriladores en el entorno comunitario. Por ello la Estrategia plantea como punto crítico mejorar el acceso a la RCP y la desfibrilación precoz. Las cifras del 20 %, 30 % o 40 % sobrestiman claramente la supervivencia real de este evento en nuestro medio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ef") }, {"long_answer": "En el ámbito de las arritmias, la ESCAV establece como punto crítico promover el diagnóstico precoz de la fibrilación auricular, la arritmia más prevalente, porque su detección temprana permite iniciar la anticoagulación y prevenir ictus cardioembólicos. La continuidad asistencial es un elemento transversal de la Estrategia, no un punto crítico específico de arritmias. La detección precoz de la insuficiencia cardiaca corresponde al área de insuficiencia cardiaca, y el acceso a la reanimación cardiopulmonar se vincula con la parada cardiaca extrahospitalaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f8") }, {"long_answer": "La cuarta edición del Código Europeo contra el Cáncer, con sus 12 recomendaciones, fue elaborada en un proyecto coordinado por la Agencia Internacional de Investigación sobre el Cáncer (IARC), organismo especializado de la OMS, con cofinanciación de la Comisión Europea. La Comisión Europea financió el proyecto, pero no lo coordinó. La OMS es la organización de la que depende la IARC, aunque la coordinación técnica correspondió a esta agencia. La llamada Agencia Europea para la Investigación del Cáncer no es el organismo responsable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770fb") }, {"long_answer": "Según las estimaciones de la Red Española de Registros de Cáncer (REDECAN) recogidas en la Estrategia en Cáncer del SNS, en España se preveía diagnosticar en 2020 más de 270.000 nuevos casos de cáncer (en torno a 277.000), con predominio en hombres. La cifra de 250.000 queda por debajo de lo estimado, mientras que 300.000 y 350.000 sobrestiman la incidencia prevista para ese año. Estas estimaciones se basan en las tasas de los registros poblacionales y en las proyecciones de población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770fd") }, {"long_answer": "La Estrategia en Cáncer del SNS recoge que, en hombres, la tasa de incidencia de cáncer ajustada por edad estimada para 2020 descendería alrededor de un 6 % respecto a la del quinquenio 2008-2012. Este descenso se relaciona con la disminución del tabaquismo masculino y su efecto en tumores como el de pulmón o vejiga. Aunque el número absoluto de casos sigue aumentando por el envejecimiento poblacional, la tasa ajustada elimina ese efecto. Por ello no es correcto hablar de aumento del 6 % o del 12 %, ni de estabilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ff") }, {"long_answer": "Según los datos recogidos en la Estrategia en Cáncer del SNS, la tasa de incidencia de cáncer de vejiga urinaria en hombres disminuyó aproximadamente un 17 % entre 2012 y 2020. Esta reducción se atribuye fundamentalmente al descenso del consumo de tabaco, principal factor de riesgo de este tumor, y a la menor exposición laboral a determinadas aminas aromáticas. No se produjo un aumento del 5 % ni del 11 %, ni la tasa se mantuvo estable, lo que convierte a la vejiga en uno de los tumores con mayor descenso en varones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977101") }, {"long_answer": "La Estrategia en Cáncer del SNS, al comparar las estimaciones de 2020 con la media de la UE-27, recoge que la incidencia de cáncer de mama en España experimentó un aumento de en torno al 6 %. Este incremento se relaciona con factores reproductivos (retraso de la maternidad, menor número de hijos), el sobrepeso, el consumo de alcohol y la mayor detección por los programas de cribado. Las opciones de descenso del 5 %, estabilidad o aumento del 10 % no se corresponden con los datos aportados por el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977103") }, {"long_answer": "La Estrategia en Cáncer del SNS muestra que, al comparar las tasas de incidencia de 2020, el cáncer de pulmón presentaba en España una tasa casi igual a la de la media de la UE-27. En cambio, en otros tumores como los de vejiga urinaria se observan diferencias apreciables con Europa, y los de riñón o hígado tampoco son los señalados como equiparables. Esta comparación sirve para valorar el peso relativo de factores de riesgo compartidos, como el tabaquismo, y orientar las prioridades de prevención."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977105") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97710a") }, {"long_answer": "Según los datos de supervivencia de los registros españoles recogidos en la Estrategia en Cáncer del SNS, la supervivencia neta a 5 años del conjunto de cánceres, excepto piel no melanoma, en mujeres diagnosticadas en el periodo 2008-2013 del grupo de 65 a 74 años fue del 59,5 %. La supervivencia neta estima la probabilidad de sobrevivir eliminando las muertes por otras causas, y desciende progresivamente con la edad al diagnóstico. Las cifras del 64,4 %, 57,6 % y 62,1 % no se corresponden con el valor publicado para ese grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977110") }, {"long_answer": "La Estrategia en Cáncer del SNS recoge que el cáncer de mama femenina es el tumor más prevalente en España, es decir, el que acumula más personas vivas diagnosticadas en los años previos, debido a su elevada incidencia y a su alta supervivencia gracias al cribado y a los avances terapéuticos. El cáncer de próstata y el colorrectal también presentan una prevalencia elevada, pero inferior a la de mama. El cáncer de vejiga urinaria tiene una prevalencia menor y no ocupa el primer lugar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97711a") }, {"long_answer": "La infección crónica por Helicobacter pylori es el principal factor de riesgo del cáncer gástrico, especialmente del adenocarcinoma no cardial, y está clasificada por la IARC como carcinógeno del grupo 1, ya que provoca gastritis crónica, atrofia y metaplasia intestinal. El tabaco aumenta el riesgo de cáncer de estómago, pero en menor medida. La exposición laboral al asbesto se asocia sobre todo a mesotelioma y cáncer de pulmón, y el consumo de frutas y verduras se considera un factor protector, no de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97711b") }, {"option_3": "Terapia hormonal sustitutiva con estrógenos sin progestágenos", "long_answer": "El cáncer de cuerpo uterino (endometrio) es un tumor hormonodependiente, y el principal factor de riesgo hormonal es la exposición prolongada a estrógenos sin oposición de progestágenos, como ocurre con la terapia hormonal sustitutiva solo con estrógenos, la obesidad o el tamoxifeno. El síndrome de Lynch es un factor de riesgo genético, no hormonal. La pancreatitis no guarda relación con este tumor, y el alcohol se asocia a otros cánceres como el de mama o el hepático. Los anticonceptivos orales combinados, por el contrario, tienen efecto protector frente al cáncer de endometrio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97711e") }, {"long_answer": "Según las estimaciones de incidencia para 2020 recogidas en la Estrategia en Cáncer del SNS, los linfomas no hodgkinianos ocuparon la octava posición entre los tumores más frecuentes en hombres y la séptima en mujeres. Es un grupo heterogéneo de neoplasias linfoides con incidencia relativamente similar en ambos sexos, pero que en mujeres ocupa un lugar más alto en la clasificación porque el resto de tumores femeninos son menos numerosos. Las demás combinaciones de posiciones no se corresponden con los datos aportados por el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977120") }, {"long_answer": "Entre los factores que influyen en el riesgo de linfoma no hodgkiniano se encuentra la exposición laboral a determinados productos químicos, como pesticidas, herbicidas y disolventes orgánicos, además de la inmunodepresión (VIH, trasplantes), algunas infecciones (virus de Epstein-Barr, Helicobacter pylori) y las enfermedades autoinmunes. El consumo de tabaco no se considera un factor de riesgo relevante para estos linfomas. El uso de dispositivos electrónicos y la práctica de deportes extremos no tienen relación demostrada con su aparición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977123") }, {"long_answer": "La exposición ocupacional al benceno es un factor de riesgo bien establecido para las leucemias, especialmente la leucemia mieloide aguda, y está clasificado por la IARC como carcinógeno del grupo 1; también aumentan el riesgo la radiación ionizante, el tabaco y la quimioterapia previa. El consumo de frutas y verduras y la práctica regular de ejercicio son hábitos saludables considerados protectores frente al cáncer en general. Abstenerse de consumir alcohol tampoco es un factor de riesgo, sino una recomendación del Código Europeo contra el Cáncer."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977124") }, {"long_answer": "Según los datos de supervivencia de los registros españoles recogidos en la Estrategia en Cáncer del SNS, la supervivencia relativa a 5 años estandarizada por edad de la leucemia mieloide aguda en pacientes diagnosticados entre 2000 y 2007 fue del 17,5 % en hombres y del 21,4 % en mujeres. Son cifras bajas que reflejan el mal pronóstico de esta neoplasia, especialmente en personas mayores. Los valores del 30 % y 27 %, 10 % y 15 % o 40 % y 45 % no se corresponden con los datos publicados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977125") }, {"long_answer": "Las leucemias son el grupo de cáncer más frecuente en la infancia en España, y representan alrededor de un tercio de los tumores diagnosticados entre 0 y 14 años, seguidas de los tumores del sistema nervioso central y los linfomas. En la infancia predominan las neoplasias embrionarias y hematológicas. Los carcinomas, característicos de los adultos, son excepcionales en niños. Los melanomas son muy poco frecuentes en edad pediátrica, y los sarcomas, aunque presentes, tienen una frecuencia claramente menor que las leucemias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977128") }, {"long_answer": "Según el Registro Español de Tumores Infantiles (RETI-SEHOP), recogido en la Estrategia en Cáncer del SNS, desde 1980 se han registrado para el conjunto de España 28.564 casos nuevos en el grupo de 0 a 14 años y 1.554 en el de 15 a 19 años. La menor cifra en adolescentes refleja que su registro sistemático se incorporó más tarde. Las demás opciones presentan cifras que no se corresponden con las publicadas por el registro y recogidas en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97712a") }, {"long_answer": "La actualización de la Estrategia en Cáncer del SNS se alinea con los objetivos de la Estrategia de Promoción de la Salud y Prevención en el SNS, ya que buena parte de los cánceres son prevenibles actuando sobre factores como el tabaco, el alcohol, la alimentación, la actividad física o el exceso de peso. Esta alineación permite abordar de forma integrada los determinantes de la salud compartidos con otras enfermedades crónicas. Las estrategias de vacunación, nutrición o atención primaria citadas no son el marco de alineación que señala el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97712c") }, {"long_answer": "La Estrategia de Promoción de la Salud y Prevención en el SNS aborda factores determinantes de la salud vinculados a los estilos de vida, como la alimentación inadecuada, la actividad física insuficiente, el consumo de tabaco y el consumo de riesgo de alcohol, además del bienestar emocional y los entornos seguros. Una alimentación poco saludable se relaciona con obesidad, enfermedades cardiovasculares, diabetes y varios tipos de cáncer. El uso excesivo de tecnología, la falta de sueño y la falta de actividades de ocio no figuran entre los determinantes priorizados por esa Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977130") }, {"question": "¿Qué porcentaje de los escolares de 14 a 18 años ha fumado tabaco en los últimos 12 meses, según la Encuesta Estatal sobre Uso de Drogas en Enseñanzas Secundarias de 2018/2019 (ESTUDES)?", "long_answer": "Según la encuesta ESTUDES 2018/2019, el 35,0 % de los escolares de 14 a 18 años había fumado tabaco en los últimos 12 meses, mientras que la prevalencia de consumo alguna vez en la vida superaba el 40 % y la de los últimos 30 días se situaba en torno al 27 %. Estas cifras muestran que el inicio en el tabaquismo se produce en la adolescencia, lo que justifica las acciones preventivas en el ámbito escolar. Los valores del 20,5 % y 15,9 % infraestiman el consumo anual, y el 40,2 % se aproxima más al consumo alguna vez en la vida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977139") }, {"long_answer": "La Estrategia en Cáncer del SNS, citando a la Agencia Europea para la Seguridad y la Salud en el Trabajo, recoge que aproximadamente 1 de cada 5 trabajadores de la Unión Europea está expuesto a agentes cancerígenos en su lugar de trabajo, lo que explica que el cáncer sea la primera causa de muerte relacionada con el trabajo en la UE. Las proporciones de 1 de cada 10, 1 de cada 20 o 1 de cada 50 infraestiman la magnitud de esta exposición, por lo que no se corresponden con el dato del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977140") }, {"long_answer": "La terapia hormonal, especialmente la terapia hormonal sustitutiva en la menopausia, incrementa según la evidencia científica el riesgo de cáncer de mama, endometrio (cuando se usan estrógenos sin progestágenos) y ovario, por la estimulación hormonal de estos tejidos; por ello el Código Europeo contra el Cáncer recomienda limitar su uso. El tabaquismo es un factor de riesgo de muchos cánceres, pero no se asocia de forma característica a estos tres. El ejercicio regular y la dieta equilibrada son factores protectores, no de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97714f") }, {"long_answer": "La Estrategia en Cáncer del SNS señala que reforzar los programas de salud del niño sano en atención primaria podría mejorar el diagnóstico en etapas iniciales de las enfermedades oncológicas pediátricas, ya que los controles periódicos permiten detectar signos de alarma (masas, palidez, cefaleas persistentes, leucocoria) y derivar con rapidez. Las enfermedades infecciosas, congénitas y crónicas también se benefician de estos programas, pero la pregunta se refiere al contexto de la Estrategia en Cáncer, donde se plantea esta medida para reducir el retraso diagnóstico del cáncer infantil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977152") }, {"long_answer": "La medicina de precisión tiene como objetivo seleccionar a los pacientes que realmente se pueden beneficiar de un tratamiento, a partir de las características moleculares y genéticas del tumor y del propio paciente, lo que aumenta la eficacia y evita toxicidades y costes innecesarios en quienes no responderían. Administrar el mismo tratamiento a todos los pacientes o aplicar la misma terapia a todos los tipos de tumores es justo lo contrario de este enfoque personalizado. Ignorar los datos de los análisis genéticos o moleculares anularía su fundamento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977156") }, {"option_1": "Tratamiento activo dirigido exclusivamente a prolongar la supervivencia en la fase terminal", "option_2": "Enfoque que mejora la calidad de vida de pacientes y familias que afrontan enfermedades amenazantes para la vida, mediante la prevención y el alivio del sufrimiento, con identificación temprana, evaluación y tratamiento del dolor y otros problemas físicos, psicosociales y espirituales", "option_3": "Atención limitada a los últimos días de vida, centrada en la sedación", "option_4": "Cuidados dirigidos únicamente al control del dolor oncológico", "long_answer": "La OMS (2002) define los cuidados paliativos como un enfoque que mejora la calidad de vida de pacientes y familias que se enfrentan a los problemas asociados a enfermedades amenazantes para la vida, a través de la prevención y el alivio del sufrimiento mediante la identificación temprana, la evaluación y el tratamiento del dolor y de otros problemas físicos, psicosociales y espirituales. No buscan prolongar la supervivencia a toda costa, no se limitan a los últimos días ni a la sedación, y tampoco se reducen al control del dolor oncológico, sino que abordan a la persona de forma integral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977157") }, {"option_2": "Aplicar a los niños los mismos protocolos terapéuticos que a los adultos", "option_3": "Suprimir el seguimiento a largo plazo de los supervivientes", "option_4": "Atender a los adolescentes exclusivamente en unidades de adultos", "long_answer": "La Estrategia en Cáncer del SNS identifica como reto específico de la asistencia al cáncer infantil y adolescente generalizar el diagnóstico molecular en todos los casos pediátricos, ya que permite clasificar mejor los tumores, ajustar el tratamiento e incluir a los pacientes en ensayos clínicos. Aplicar a los niños los protocolos de adultos ignora la biología propia de los tumores infantiles. Suprimir el seguimiento a largo plazo contradice la necesidad de vigilar efectos tardíos y segundas neoplasias, y atender a los adolescentes solo en unidades de adultos va contra la recomendación de unidades adaptadas a su edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977159") }, {"long_answer": "Los supervivientes de cáncer infantil tienen un riesgo aumentado de segundas neoplasias por los tratamientos recibidos (radioterapia, alquilantes) o por predisposición genética. Introducir sistemas de cribado en su seguimiento permite la detección precoz de esas segundas neoplasias, cuando el tratamiento es más eficaz. El cribado no reduce el riesgo de desarrollarlas, ya que no actúa sobre su causa, y tampoco previene el cáncer, sino que lo detecta en fases iniciales. La mejora de la calidad de vida puede ser una consecuencia indirecta, pero no es el beneficio específico del cribado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977167") }, {"long_answer": "En la Estrategia en Cáncer del SNS, el objetivo 30 se orienta a la atención de las necesidades sociales y laborales de las personas con cáncer, y entre sus acciones figura realizar un estudio del impacto laboral, psicológico y social de la enfermedad en los pacientes. Este conocimiento permite diseñar medidas de apoyo y reincorporación. Mejorar el diagnóstico anatomopatológico en el marco de la oncología de precisión se vincula a otro objetivo, al igual que definir un plan individualizado de seguimiento o los cursos de formación para profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97716b") }, {"long_answer": "En la Estrategia en Cáncer del SNS, el objetivo 34 se refiere al cáncer infantil y de la adolescencia, y una de sus acciones es implementar y evaluar el acuerdo sobre la organización asistencial de estos tumores, que establece la atención en unidades con experiencia suficiente y trabajo en red. Mejorar el diagnóstico anatomopatológico, poner en marcha cursos de formación para profesionales y proporcionar atención social a pacientes y familiares son acciones que corresponden a otros objetivos de la Estrategia, no al específico de la atención pediátrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977171") }, {"long_answer": "El documento técnico del Ministerio de Sanidad sobre transmisión de SARS-CoV-2 por aerosoles establece varias premisas para demostrar esta vía. La primera es que se generen aerosoles con virus durante la respiración, el habla o la tos; la segunda, que los virus contenidos en los aerosoles mantengan su viabilidad y capacidad de generar infección; y la tercera, que los tejidos diana sean accesibles. La relación de la viabilidad con la humedad y la temperatura, la cantidad de virus emitida y la dependencia de los aerosoles de la actividad son factores moduladores, no la segunda condición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977173") }, {"question": "¿Cuál es la tercera premisa necesaria para demostrar que la infección por SARS-CoV-2 puede producirse mediante aerosoles inhalados?", "long_answer": "Según el documento técnico del Ministerio de Sanidad sobre transmisión de SARS-CoV-2 por aerosoles, para demostrar esta vía de infección deben cumplirse tres premisas: que se generen aerosoles con virus, que esos aerosoles contengan virus viables con capacidad infectiva y, en tercer lugar, que los tejidos diana del virus sean accesibles a los aerosoles inhalados, es decir, que las partículas lleguen a las zonas del tracto respiratorio con receptores ACE2. La relación de la viabilidad con la humedad y la temperatura es un factor modulador, y las opciones sobre virus viables o capacidad infectiva corresponden a la segunda premisa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977175") }, {"option_1": "La temperatura corporal de la persona infectada", "long_answer": "El documento técnico sobre transmisión de SARS-CoV-2 por aerosoles señala que la cantidad de virus emitida depende de la carga viral presente en las secreciones respiratorias de la persona infectada, que es máxima en el periodo de máxima transmisibilidad, en torno al inicio de los síntomas. Por eso es la condición determinante en esa fase. La temperatura corporal no condiciona la emisión de virus. La concentración y el tamaño de los aerosoles dependen de la actividad (hablar, cantar, gritar), y la probabilidad de que una gota contenga virus depende a su vez de la carga viral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977178") }, {"question": "¿En qué tipo de espacio se considera superior el riesgo de transmisión de SARS-CoV-2 por aerosoles?", "option_3": "Exteriores con viento moderado", "option_4": "Espacios al aire libre con baja ocupación", "long_answer": "El riesgo de transmisión de SARS-CoV-2 por aerosoles es superior en interiores, sobre todo si están mal ventilados, concurridos y la exposición es prolongada, porque los aerosoles se acumulan y su concentración aumenta con el tiempo. En exteriores los aerosoles se diluyen y dispersan rápidamente, de modo que el riesgo es mucho menor, y aún más con viento o con baja ocupación. Por ello las recomendaciones priorizan la ventilación, la reducción de aforos y el uso de mascarilla en espacios interiores compartidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977179") }, {"long_answer": "El documento técnico sobre transmisión de SARS-CoV-2 por aerosoles recomienda mantener en interiores una humedad relativa entre el 40 % y el 60 %, ya que en ese rango se reduce la supervivencia del virus y se preserva la función de defensa de la mucosa respiratoria (aclaramiento mucociliar). Una humedad muy baja, como el 15-25 %, reseca las mucosas y favorece la permanencia de aerosoles en suspensión. Los rangos del 60-70 % y 75-90 % son excesivos, generan disconfort y favorecen el crecimiento de hongos y ácaros."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97717b") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97717c") }, {"long_answer": "En los modelos de riesgo de transmisión por aerosoles recogidos en el documento técnico del Ministerio de Sanidad se asume que la dosis mínima capaz de generar un caso de infección por SARS-CoV-2 se sitúa entre 130 y 210 copias de ARN viral inhaladas. Este valor permite estimar el riesgo según la concentración de virus en el aire y el tiempo de exposición. La cifra de 10⁵ copias es muy superior a la asumida, y los 150 minutos o los 20 cm son medidas de tiempo y distancia, no una dosis infectiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97717d") }, {"long_answer": "En locales bien ventilados la concentración de bioaerosoles disminuye a medida que aumenta la distancia al emisor, porque la renovación del aire diluye y elimina las partículas, de modo que la distancia física sí aporta protección. En locales mal ventilados, en cambio, los aerosoles se acumulan y se distribuyen por todo el espacio, por lo que la concentración puede ser elevada incluso lejos de la persona infectada. El uso de mascarillas reduce la emisión, pero no es un tipo de local, y los exteriores no son locales cerrados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977186") }, {"option_3": "Usarla en interiores compartidos, priorizando su uso frente al de exteriores", "long_answer": "La recomendación del documento técnico sobre transmisión de SARS-CoV-2 por aerosoles es priorizar el uso de mascarilla en interiores compartidos, donde se acumulan los aerosoles y el riesgo de contagio es mayor, por encima de su uso en exteriores. Limitarla a ambientes muy concurridos deja sin protección otras situaciones de riesgo en interiores, como la exposición prolongada o la mala ventilación. Afirmar que no es necesaria en ningún caso es incorrecto, y reservarla solo para cuando se está enfermo ignora la transmisión desde personas asintomáticas y presintomáticas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977188") }, {"long_answer": "Según la evidencia recogida en el documento técnico sobre transmisión de SARS-CoV-2 por aerosoles, mantener una distancia interpersonal de 1 metro, sin mascarilla, reduce la transmisión del virus en torno a un 70 % respecto a distancias menores, y la protección aumenta a medida que la distancia se incrementa. La distancia reduce sobre todo la exposición a las emisiones de mayor tamaño y a la nube de aerosoles más concentrada cerca del emisor. Las cifras del 60 %, 50 % y 40 % no se corresponden con la reducción descrita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97718e") }, {"long_answer": "En ambientes interiores en los que no puede garantizarse una ventilación ni una filtración adecuadas, el documento técnico sobre aerosoles contempla el empleo de radiación ultravioleta C (UV-C) como tecnología complementaria de desinfección del aire, siempre instalada por profesionales y sin exponer directamente a las personas. Los filtros de baja eficacia no retienen las partículas que contienen virus, ya que se recomiendan los de mayor eficacia posible. La generación de ozono en presencia de personas está desaconsejada por su toxicidad, y renunciar a cualquier tecnología no es la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977191") }, {"question": "¿Cuál es una medida efectiva para reducir el riesgo de contagio por las emisiones respiratorias de gran tamaño (gotas)?", "option_2": "Aumentar la distancia física interpersonal", "long_answer": "Las emisiones respiratorias de gran tamaño (gotas) tienen un comportamiento balístico y caen al suelo a poca distancia del emisor, por lo que aumentar la distancia física interpersonal es una medida efectiva para reducir el riesgo de contagio por esta vía. Aumentar la concentración de aerosoles o el tiempo de contacto incrementaría el riesgo, en lugar de reducirlo. La opción de ninguna de las anteriores no es válida, porque el distanciamiento sí es una medida eficaz recogida en las recomendaciones del Ministerio de Sanidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977195") }, {"long_answer": "Ante signos de flebitis (dolor, eritema, calor, induración o cordón venoso palpable), el proyecto Flebitis Zero recomienda retirar el catéter venoso periférico y, si sigue siendo necesario un acceso, canalizar uno nuevo en otra localización, preferentemente en el otro brazo. Mantener el catéter favorece la progresión de la inflamación y el riesgo de infección. Cambiar la solución a infundir no resuelve la causa, la higiene bucal no guarda relación con este problema y administrar un antitérmico solo trataría un síntoma sin actuar sobre el origen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977197") }, {"long_answer": "El proyecto Flebitis Zero recomienda cambiar todos los sistemas de infusión, conexiones y alargaderas cada vez que se retire un catéter venoso periférico y se inserte uno nuevo, para no trasladar al nuevo acceso una posible contaminación del sistema anterior. Limitar el cambio a cuando el catéter esté dañado o a cuando existan signos de infección es insuficiente desde el punto de vista preventivo. El cambio cada 48 horas no es el intervalo recomendado, ya que los sistemas de infusión continua pueden mantenerse hasta 96 horas si no hay otra indicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97719a") }, {"long_answer": "La flebitis química se produce por la irritación del endotelio venoso causada por los fármacos o soluciones infundidas (pH extremos, osmolaridad elevada, sustancias vesicantes) y por el material del catéter, ya que algunos materiales son más trombogénicos e irritantes; los de poliuretano se asocian a menor riesgo. La frecuencia de cambio del apósito se relaciona con la flebitis infecciosa. El tiempo de permanencia y las características del paciente influyen en el riesgo general de flebitis, pero no son los factores propios del mecanismo químico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97719b") }, {"question": "¿Qué factor predispone específicamente al riesgo de flebitis infecciosa?", "option_1": "pH ácido del fármaco infundido", "option_3": "Calibre del catéter grande en relación con la vena", "option_4": "Osmolaridad elevada de la solución infundida", "long_answer": "La flebitis infecciosa se debe a la entrada de microorganismos a través del punto de inserción o de las conexiones del catéter, y uno de sus principales factores predisponentes es la pobre higiene de manos de los profesionales, junto con una técnica aséptica deficiente durante la inserción y el mantenimiento. Por eso el proyecto Flebitis Zero insiste en la higiene de manos en los cinco momentos. El pH ácido y la osmolaridad elevada de lo infundido son factores de flebitis química, y un calibre de catéter grande respecto a la vena favorece la flebitis mecánica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97719e") }, {"long_answer": "La OMS insiste en que el uso de guantes, incluidos los estériles, no sustituye en ningún caso la higiene de manos, que debe realizarse siempre que esté indicada, antes de ponerse los guantes y después de retirarlos, ya que pueden tener microperforaciones y las manos se contaminan al quitarlos. Afirmar que los guantes reemplazan el lavado o que la higiene de manos es opcional con guantes estériles es incorrecto. Tampoco se deben lavar las manos con los guantes puestos: hay que retirarlos y después higienizar las manos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771a4") }, {"long_answer": "El Conjunto Mínimo Básico de Datos (CMBD) es un registro poblacional que recoge información clínica y administrativa sobre la patología atendida en los centros sanitarios, a partir de cada episodio asistencial, y en el contexto de las úlceras por presión permite conocer su presencia como diagnóstico codificado en los episodios. No es un protocolo de tratamiento ni una guía de prevención de úlceras por presión. Tampoco es simplemente un sistema de información electrónica hospitalaria, sino un conjunto normalizado de datos con fines epidemiológicos y de gestión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771a7") }, {"long_answer": "El CMBD recoge datos sobre la actividad asistencial de los hospitales de agudos y, progresivamente, de otros recursos, incluidos los sociosanitarios, mediante un conjunto normalizado de variables clínicas y administrativas de cada episodio, lo que permite analizar, entre otros diagnósticos, la presencia de úlceras por presión. No recoge datos específicos sobre la efectividad de los tratamientos para estas lesiones ni sobre la formación de los profesionales de enfermería. Tampoco es un estudio de prevalencia de úlceras por presión, que requiere metodologías y cortes específicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ab") }, {"long_answer": "Ante cualquier duda sobre la medicación prescrita, lo adecuado es preguntar a los profesionales sanitarios (médico, enfermera o farmacéutico), que conocen el tratamiento y la situación clínica del paciente y pueden aclarar la dosis, la forma de administración, las interacciones o los efectos esperables. Investigar por cuenta propia puede llevar a información errónea o no adaptada al caso. Las opiniones de amigos y familiares no son una fuente fiable, e ignorar las dudas aumenta el riesgo de errores de medicación y de falta de adherencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771b2") }, {"long_answer": "Comunicar al profesional sanitario los efectos secundarios observados permite que valore su gravedad y su relación con el fármaco y ayude al paciente a manejarlos, ajustando la dosis, cambiando el medicamento o añadiendo medidas de control, lo que mejora la seguridad y la adherencia al tratamiento. Además, contribuye a la farmacovigilancia. El objetivo no es molestar al profesional ni conseguir que se prescriban más medicamentos, y no comunicarlos es un error, porque puede retrasar la detección de reacciones adversas importantes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771b4") }, {"long_answer": "El Plan de Acción sobre el Ictus en Europa 2018-2030 establece como objetivo de prevención secundaria asegurar que al menos el 90 % de las personas que sufren un ictus sean atendidas por un especialista y tengan acceso al tratamiento de prevención secundaria, incluido el estudio etiológico. Garantizar las terapias de recanalización al 95 % de los candidatos corresponde al área de tratamiento agudo. Proporcionar el alta precoz con apoyo al 20 % se vincula a la rehabilitación, y el apoyo a las personas tras el ictus forma parte del ámbito de la vida después del ictus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771be") }, {"long_answer": "Los datos toxicológicos de los conductores fallecidos en siniestros viales en España, recogidos en los documentos del Ministerio de Sanidad sobre alcohol, muestran que aproximadamente 1 de cada 3 había consumido alcohol por encima de los límites legales establecidos. Esto convierte al alcohol en uno de los factores más relevantes de la siniestralidad vial mortal y justifica las medidas preventivas y de control. Las proporciones de 1 de cada 2, 1 de cada 5 o 1 de cada 10 no se corresponden con los datos publicados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771c3") }, {"long_answer": "En las inundaciones, el principal riesgo de aparición de casos de tétanos se debe a la exposición a aguas, lodos y objetos contaminados durante la fase aguda y las tareas de limpieza, que favorece heridas potencialmente tetanígenas por las que pueden penetrar las esporas de Clostridium tetani. El riesgo no es nulo, ya que la limpieza es precisamente una situación de exposición. Tampoco se limita a la población infantil ni a las personas inmunodeprimidas, sino que afecta a cualquier persona con vacunación incompleta, especialmente adultos mayores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771c6") }, {"long_answer": "Ante un desastre natural, las recomendaciones del Ministerio de Sanidad incluyen realizar adquisiciones extraordinarias de vacunas frente a las enfermedades con mayor riesgo de aparición en las zonas afectadas, como el tétanos o la hepatitis A, para asegurar una respuesta rápida. Afirmar que no es necesario garantizar su disponibilidad es incorrecto, igual que reducir el número de vacunas por temor a un sobreabastecimiento. También se recomienda establecer sinergias entre los distintos actores implicados en la vacunación, por lo que la última opción contradice el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771c8") }, {"long_answer": "En situaciones de desastre natural como las inundaciones, ante la dificultad para conocer el estado vacunal y valorar adecuadamente las heridas, las recomendaciones del Ministerio de Sanidad indican valorar la administración de una dosis de inmunoglobulina antitetánica en todas las heridas potencialmente tetanígenas, además de la vacuna según corresponda. Afirmar que no es necesaria ninguna profilaxis adicional o que no debe realizarse ninguna profilaxis es incorrecto, dado el riesgo aumentado. Limitar la vacuna solo a las heridas graves también es insuficiente, porque heridas menores pueden ser tetanígenas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771c9") }, {"long_answer": "Las recomendaciones del Ministerio de Sanidad ante inundaciones incluyen garantizar la disponibilidad de las vacunas que hayan podido verse afectadas por el desastre o por incidencias en la cadena de frío, reponiendo las dosis dañadas para que no se interrumpan la vacunación sistemática ni la profilaxis. No realizar ningún aseguramiento de su disponibilidad o reducir la cantidad de vacunas son actuaciones contrarias a estas recomendaciones. Tampoco se aconseja renunciar a adquisiciones extraordinarias, que se contemplan precisamente frente a las enfermedades con mayor riesgo en la zona afectada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771cc") }, {"long_answer": "El Real Decreto 579/2017 regula la fabricación, presentación y comercialización de los productos del tabaco y relacionados, y entre los aspectos que establece figuran las exigencias de etiquetado, como las advertencias sanitarias, extendidas a los productos de tabaco calentado. La prohibición de consumo en espacios públicos corresponde a la Ley 28/2005 de medidas sanitarias frente al tabaquismo. Promover nuevos sabores o aumentar la publicidad de productos del tabaco son medidas contrarias al objetivo de la normativa, que restringe los aromas característicos y la promoción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b3") }, {"option_4": "Sustituir la angioplastia primaria por fibrinólisis en todos los casos", "long_answer": "Las redes asistenciales regionales para el infarto agudo de miocardio, conocidas como Código Infarto, tienen como objetivo reducir la mortalidad de los pacientes al garantizar una reperfusión precoz, preferentemente mediante angioplastia primaria, y la coordinación entre servicios de emergencias y hospitales con hemodinámica. Estas redes no buscan reducir la incidencia de cardiopatía isquémica, que depende de la prevención, ni incrementar su prevalencia. Sustituir sistemáticamente la angioplastia primaria por fibrinólisis contradice su propósito, que es facilitar el acceso a la angioplastia como tratamiento de elección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b8") }, {"option_3": "Miocardiopatía hipertrófica", "long_answer": "La ESCAV recoge que la fibrilación auricular afecta a un 1-2 % de la población general en España, y que su prevalencia aumenta de forma marcada con la edad, superando el 4 % en mayores de 40 años y llegando a más del 10 % en mayores de 80. La parada cardiaca extrahospitalaria se expresa como incidencia anual por habitantes, no como prevalencia. La miocardiopatía hipertrófica es una enfermedad mucho menos frecuente, y la valvulopatía no reumática no se describe en el documento con esa prevalencia en la población general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b9") }, {"long_answer": "La ESCAV estima que la prevalencia de fibrilación auricular se incrementará notablemente en los próximos 50 años, sobre todo por el envejecimiento de la población, ya que la edad es el principal factor asociado a esta arritmia, sumado a la mayor supervivencia de personas con cardiopatías e hipertensión. La mejora de la detección precoz aumenta los casos diagnosticados, pero no es el determinante principal. El aumento de la mortalidad reduciría la prevalencia, y el desarrollo de nuevos tratamientos no es la causa del aumento previsto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770bb") }, {"option_1": "Mejorar la detección y el diagnóstico precoz de la insuficiencia cardiaca", "option_4": "Promover el diagnóstico precoz de la fibrilación auricular", "long_answer": "En el área de promoción, prevención y capacitación ciudadana, la ESCAV establece como punto crítico impulsar la promoción de la salud y la prevención de la enfermedad cardiovascular en la población residente en España, actuando sobre estilos de vida y factores de riesgo desde edades tempranas. Mejorar la detección precoz de la insuficiencia cardiaca y promover el diagnóstico precoz de la fibrilación auricular son puntos críticos de las áreas de insuficiencia cardiaca y de arritmias. Formar a los profesionales sobre la ECV en la mujer corresponde al eje de equidad y género."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c0") }, {"long_answer": "En el área de valvulopatías, la ESCAV plantea como punto crítico impulsar el diagnóstico precoz de las valvulopatías prevalentes, como la estenosis aórtica degenerativa, cuya frecuencia aumenta con el envejecimiento y cuyo pronóstico mejora con una intervención en el momento adecuado. Fomentar la capacitación de la ciudadanía en estilos de vida saludables pertenece al área de promoción y prevención. Promocionar el autocuidado en la mujer corresponde al eje de equidad y género, y organizar la asistencia en unidades de insuficiencia cardiaca es un punto crítico del área de insuficiencia cardiaca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c8") }, {"long_answer": "El mapa estratégico de la ESCAV organiza sus objetivos en distintos niveles y contempla 11 áreas de obtención de resultados intermedios, que recogen los cambios en procesos y servicios necesarios para alcanzar los resultados finales en salud, equidad y sostenibilidad. Estas áreas sirven de base para el seguimiento y la evaluación de la Estrategia mediante indicadores. Las cifras de 10, 12 y 13 no se corresponden con la estructura del mapa estratégico descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c9") }, {"long_answer": "En el mapa estratégico de la ESCAV, el objetivo estratégico de mejora de los resultados en salud, la equidad y la sostenibilidad del SNS se asocia a 6 áreas de obtención de resultados finales, que reflejan el impacto último que la Estrategia pretende alcanzar en la población, como la reducción de la morbimortalidad cardiovascular o la mejora de la calidad de vida. Las demás cifras (5, 7 y 8) no se corresponden con la estructura recogida en el documento, que distingue estas áreas finales de las de resultados intermedios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ca") }, {"long_answer": "En el mapa estratégico de la ESCAV, el objetivo estratégico de disponibilidad de formación, recursos, investigación, innovación y gestión del conocimiento se desarrolla en 5 líneas de actuación, que constituyen la base sobre la que se apoyan el resto de objetivos, ya que sin profesionales formados, recursos adecuados e investigación no es posible mejorar la atención cardiovascular. Las cifras de 4, 6 y 7 líneas no se corresponden con la estructura del mapa estratégico descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770cc") }, {"long_answer": "En el mapa estratégico de la ESCAV, el objetivo estratégico de mayor autonomía y capacitación de los agentes implicados se articula en 3 líneas de actuación, dirigidas a reforzar la capacitación de la ciudadanía, los pacientes y sus personas cuidadoras, así como de los profesionales, para que puedan participar activamente en el cuidado de la salud cardiovascular. Las cifras de 4, 5 y 6 líneas de actuación no se corresponden con la estructura del mapa estratégico descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ce") }, {"long_answer": "Además del mapa estratégico general, la ESCAV incluye 7 mapas estratégicos individuales relativos a los ejes transversales y a las áreas de actuación específica, que permiten concretar objetivos y líneas para cada ámbito, como la promoción y prevención, la cardiopatía isquémica, la insuficiencia cardiaca, las arritmias o las valvulopatías. Esta organización facilita el seguimiento diferenciado de cada área. Las cifras de 6, 8 y 9 mapas no se corresponden con la estructura descrita en el documento."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d0") });
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d1") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d3") }, {"long_answer": "La Estrategia en Salud Cardiovascular del SNS tiene como objetivo principal mejorar el nivel de salud cardiovascular de la población española, abarcando la promoción, la prevención, la atención en fase aguda y crónica y la rehabilitación, con criterios de equidad y sostenibilidad. Promover la salud de los pacientes con ECV aguda es solo una parte de ese objetivo general. Impulsar medidas ineficaces o reducir la calidad de vida de los pacientes con ECV crónica son afirmaciones contrarias a cualquier finalidad de una estrategia de salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d5") }, {"long_answer": "La ESCAV destaca que las enfermedades cardiovasculares tienen un importante impacto en el ámbito laboral, con un incremento en el número de bajas laborales, incapacidades y pérdida de años de vida productiva, lo que se suma a su elevado coste sanitario. Por ello no producen un aumento de la productividad laboral, sino una pérdida. Tampoco reducen la carga económica del sistema de salud, que es uno de los mayores costes asociados a estas enfermedades, ni mejoran la calidad de vida de los trabajadores afectados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d7") }, {"long_answer": "La ESCAV explica que resultaba necesario replantear la orientación de la anterior Estrategia en Cardiopatía Isquémica debido, entre otros motivos, a la mayor longevidad y supervivencia de las personas con ECV crónicas, lo que aumenta la prevalencia y exige un enfoque más amplio que abarque todo el proceso y todas las enfermedades cardiovasculares. Enfocarse únicamente en la cardiopatía isquémica era precisamente la limitación que se pretendía superar. Reducir la supervivencia no tiene sentido como objetivo, y el contexto político no es el motivo señalado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770dd") }, {"long_answer": "En el contexto de las desigualdades en salud cardiovascular, la ESCAV define el género como un sistema de valores, normas, roles y estereotipos construidos socialmente que asignan comportamientos y expectativas diferentes a mujeres y hombres e influyen en su exposición a factores de riesgo, en el acceso a la atención y en el diagnóstico y tratamiento. No es un concepto biológico, ya que esa dimensión corresponde al sexo. Tampoco es una característica genética ni una condición médica, por lo que esas opciones confunden género con factores biológicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e3") }, {"long_answer": "La ESCAV recoge que el conocimiento de los signos y síntomas del infarto entre las mujeres se sitúa en torno al 40 %, inferior al de los hombres, y que muchas mujeres no perciben la enfermedad cardiovascular como un riesgo propio. Este menor conocimiento, unido a la presentación más atípica de los síntomas en ellas, contribuye a retrasos en la solicitud de ayuda y en el diagnóstico. Las cifras de más del 50 %, más del 60 % o menos del 30 % no se corresponden con el dato del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e9") }, {"long_answer": "Según los datos recogidos en la ESCAV, la incidencia de cardiopatía isquémica en España en 2019 fue de 361,4 nuevos casos por cada 100.000 habitantes, con cifras más elevadas en hombres que en mujeres y un aumento marcado con la edad. Este dato refleja la magnitud de la enfermedad y justifica las actuaciones de prevención y de organización asistencial, como las redes de atención al infarto. Las cifras de 463,4, 263,6 y 485,5 casos por 100.000 habitantes no se corresponden con las del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f2") }, {"question": "¿Qué punto crítico de la ESCAV se relaciona con la formación de los profesionales sanitarios en investigación e innovación para mejorar los resultados en salud cardiovascular?", "long_answer": "La ESCAV incluye como punto crítico orientar la formación de los profesionales sanitarios a la investigación e innovación en la mejora de resultados en salud cardiovascular y en su medida, a lo largo de todo su ciclo formativo, desde el grado hasta la formación continuada. Desarrollar la capacitación en promoción y prevención se refiere a otra área de formación, e impulsar la promoción de la salud en la población es un punto crítico de promoción y prevención. Promover el diagnóstico precoz de la fibrilación auricular corresponde al área de arritmias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f4") }, {"long_answer": "El Código Europeo contra el Cáncer recomienda una alimentación saludable basada en abundantes cereales integrales, legumbres, frutas y verduras, por su contenido en fibra y compuestos protectores y por su papel en el mantenimiento de un peso adecuado. Además, aconseja limitar los alimentos ricos en azúcar o grasa, evitar las bebidas azucaradas, la carne procesada y el exceso de sal, y reducir o evitar el consumo de alcohol. Por tanto, el resto de opciones describen alimentos y bebidas que conviene limitar o evitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f5") }, {"option_2": "Utilizar ropa protectora y gafas de sol", "option_4": "Buscar la sombra en las horas centrales del día", "long_answer": "El Código Europeo contra el Cáncer recomienda evitar el uso de cabinas de rayos UVA, ya que la radiación ultravioleta artificial está clasificada como cancerígena y aumenta el riesgo de melanoma y otros cánceres de piel, especialmente si se utilizan antes de los 30 años. Además, aconseja evitar la exposición excesiva al sol, sobre todo en los niños. Utilizar protección solar, usar ropa protectora y gafas de sol, y buscar la sombra en las horas centrales del día son medidas recomendadas para reducir el riesgo, no conductas que se deban evitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f9") }, {"question": "¿Cuántos nuevos casos de cáncer se diagnosticaron aproximadamente en todo el mundo en 2018?", "long_answer": "Según las estimaciones de GLOBOCAN recogidas en la Estrategia en Cáncer del SNS, en 2018 se diagnosticaron en todo el mundo unos 18 millones de nuevos casos de cáncer (18,1 millones), cifra que se sitúa en torno a 17 millones si se excluyen los tumores de piel no melanoma. Esto confirma que el cáncer es uno de los principales problemas de salud a escala mundial. Las cifras de 16, 20 y 22 millones no se corresponden con las estimaciones de ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770fa") }, {"question": "¿Cuántas muertes por cáncer se produjeron aproximadamente en todo el mundo en 2018?", "long_answer": "Según las estimaciones de GLOBOCAN recogidas en la Estrategia en Cáncer del SNS, en 2018 se produjeron en todo el mundo más de 9 millones de muertes por cáncer (unos 9,6 millones), lo que lo sitúa entre las principales causas de mortalidad a nivel mundial. La opción de más de 8 millones infraestima la cifra, mientras que más de 10 y más de 11 millones superan las estimaciones de ese año, aunque la tendencia es creciente por el envejecimiento y el crecimiento de la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770fc") }, {"long_answer": "Según las estimaciones de REDECAN recogidas en la Estrategia en Cáncer del SNS, el cáncer colorrectal fue el tumor más frecuente en España en 2020 considerando ambos sexos conjuntamente, con más de 40.000 casos. Por sexos, en hombres predomina el de próstata y en mujeres el de mama, pero ninguno de ellos supera al colorrectal en el total de la población, ya que este afecta de forma importante a ambos sexos. El cáncer de pulmón ocupa también uno de los primeros puestos, pero por detrás del colorrectal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977106") }, {"long_answer": "La Estrategia en Cáncer del SNS recoge que la incidencia de cáncer colorrectal en España estimada para 2020 presentaba una disminución de alrededor del 4 % en la tasa ajustada respecto al periodo de comparación, un cambio que puede relacionarse con la implantación progresiva de los programas de cribado, que permiten detectar y extirpar lesiones precursoras. Las opciones de aumento del 4 % o del 2 % y de estabilidad no se corresponden con la tendencia descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977107") }, {"long_answer": "Según los datos de la Estrategia en Cáncer del SNS, la tasa de incidencia de linfomas no hodgkinianos en mujeres disminuyó aproximadamente un 3 % entre 2012 y 2020, una variación modesta que indica una tendencia ligeramente descendente. Las opciones de aumento del 7 % o del 5 % y de estabilidad no se corresponden con los datos aportados en el documento. Conviene recordar que en los linfomas influyen factores como la inmunodepresión, algunas infecciones y la exposición a determinados productos químicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97710c") }, {"long_answer": "Según los datos de supervivencia de los registros españoles recogidos en la Estrategia en Cáncer del SNS, la supervivencia neta a 5 años del cáncer de mama en mujeres diagnosticadas en el periodo 2002-2007 fue del 83,2 %, una de las más altas entre los tumores frecuentes, gracias al cribado y a los avances terapéuticos, y que ha seguido mejorando en periodos posteriores. Las cifras del 88,6 %, 85,5 % y 77,9 % no se corresponden con el valor publicado para ese periodo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97710d") }, {"long_answer": "Comparar la supervivencia de los pacientes con cáncer de España con la de otros países europeos, como se hace con los estudios EUROCARE, tiene como finalidad determinar las diferencias en la supervivencia por país, lo que permite situar los resultados del sistema sanitario español y detectar áreas de mejora en diagnóstico y tratamiento. El impacto de la edad se analiza dentro de cada población, no mediante la comparación entre países. La incidencia por sexo es otro indicador distinto, y la efectividad de tratamientos concretos se evalúa con ensayos clínicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977115") }, {"long_answer": "La Estrategia en Cáncer del SNS recoge que en 2018 la tasa de mortalidad por cáncer ajustada por edad en España fue casi igual a la de las enfermedades del aparato circulatorio, de modo que ambos grupos se sitúan como las principales causas de muerte. El ajuste por edad elimina el efecto del envejecimiento, que concentra las muertes circulatorias en edades avanzadas. No se describe que el cáncer supere claramente a las enfermedades circulatorias ni que quede por debajo. Compararlo con las enfermedades respiratorias no es la relación destacada por el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977117") }, {"question": "¿Cuál fue la primera causa de defunción en mujeres en España en 2018?", "long_answer": "En 2018, según los datos de defunciones por causa de muerte recogidos en la Estrategia en Cáncer del SNS, la primera causa de defunción en mujeres en España fueron las enfermedades del aparato circulatorio, seguidas de los tumores, mientras que en los hombres los tumores ocupan el primer lugar. El cáncer de mama es la primera causa de muerte por cáncer en mujeres, pero no supera al conjunto de enfermedades circulatorias. El cáncer colorrectal y el de páncreas son causas relevantes de mortalidad por cáncer, pero no la primera causa global."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977126") }, {"question": "¿Cuántos casos por cada millón (10⁶) de niños de 0-14 años son diagnosticados de cáncer al año en España?", "long_answer": "Según el Registro Español de Tumores Infantiles recogido en la Estrategia en Cáncer del SNS, en España se diagnostican cada año unos 158 casos de cáncer por cada millón de niños de 0 a 14 años, una incidencia similar a la de otros países europeos. Aunque el cáncer infantil es poco frecuente, sigue siendo una causa importante de mortalidad por enfermedad en la infancia. Las cifras de 58, 108 y 208 casos por millón no se corresponden con los datos publicados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977132") }, {"question": "¿Qué tipos de cáncer se asocian con el exceso de grasa corporal según el documento?", "option_1": "Cáncer de laringe y cáncer de cavidad oral", "option_2": "Cáncer de pulmón y cáncer de cuello uterino", "option_4": "Melanoma y cáncer de testículo", "long_answer": "La Estrategia en Cáncer del SNS recoge que el exceso de grasa corporal se asocia a un mayor riesgo de varios tipos de cáncer, entre ellos el de colon y el de mama en la posmenopausia, además de endometrio, riñón, esófago (adenocarcinoma), páncreas o hígado, por mecanismos hormonales, inflamatorios y relacionados con la insulina. Los cánceres de laringe y cavidad oral se vinculan sobre todo con el tabaco y el alcohol. El de pulmón se relaciona con el tabaco y el de cuello uterino con el VPH, y el melanoma y el cáncer de testículo no se asocian característicamente a la obesidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977135") }, {"long_answer": "La Estrategia para la Nutrición, Actividad Física y Prevención de la Obesidad (NAOS) fue elaborada por el Ministerio de Sanidad en 2005, con el objetivo de invertir la tendencia creciente de la obesidad, especialmente la infantil, mediante el fomento de una alimentación saludable y la práctica de actividad física, implicando a administraciones, industria, ámbito escolar y sanitario. Los años 1998, 2010 y 2015 no corresponden a su elaboración, aunque la Estrategia ha sido revisada y reforzada posteriormente con otras iniciativas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977137") }, {"long_answer": "La Comisión Europea señaló que en 2015 el cáncer fue la primera causa de mortalidad relacionada con el trabajo en la Unión Europea, por delante de las enfermedades circulatorias y respiratorias y de los accidentes laborales, debido a la exposición a agentes cancerígenos como el amianto, la sílice cristalina, el humo diésel o el benceno. Por ello la Estrategia en Cáncer del SNS incluye actuaciones para prevenir el cáncer laboral. Los accidentes de tráfico, las enfermedades cardiovasculares y los accidentes laborales causan menos muertes relacionadas con el trabajo."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97713e") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977141") }, {"long_answer": "Según la Encuesta Nacional de Salud de España (ENSE) 2017, el 73,9 % de los lactantes recibía lactancia materna exclusiva en las 6 primeras semanas de vida, porcentaje que desciende al 63,9 % a los 3 meses y al 39,0 % a los 6 meses, lo que muestra un abandono progresivo de la lactancia exclusiva. Por tanto, el 63,9 % y el 39,0 % corresponden a los 3 y 6 meses, respectivamente, y el 52,5 % no se corresponde con ninguno de los datos de la encuesta para esos periodos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977143") }, {"long_answer": "La prueba de cribado tiene como función principal identificar, dentro de una población aparentemente sana, a las personas con mayor probabilidad o riesgo de padecer la enfermedad, para derivarlas a pruebas diagnósticas de confirmación. No confirma la enfermedad, ya que esa es la función de las pruebas diagnósticas posteriores. Tampoco previene la enfermedad por sí misma, aunque puede contribuir a ello al detectar lesiones precursoras, y no tiene como objetivo administrar tratamiento, que corresponde a la fase asistencial tras el diagnóstico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977145") }, {"long_answer": "Los programas de cribado de cáncer tienen como objetivo prevenir el cáncer, mediante la detección y el tratamiento de lesiones precursoras, como en el cribado de cérvix o colorrectal, y reducir sus secuelas y la mortalidad que ocasiona, detectando los tumores en estadios iniciales, cuando el tratamiento es menos agresivo y más eficaz. Diagnosticar o tratar el cáncer en estadios avanzados es precisamente lo que el cribado pretende evitar. Ofrecer tratamiento a todos los pacientes con independencia del estadio no es una función del cribado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977146") }, {"long_answer": "La Recomendación del Consejo de la UE sobre cribado de cáncer, recogida en la Estrategia en Cáncer del SNS, establece para el cáncer de mama la realización de mamografía cada dos años en mujeres de 50 a 69 años, que es el esquema de los programas poblacionales españoles. La mamografía anual entre los 40 y 65 años no es el esquema recomendado. La ecografía y la resonancia magnética mamarias no se utilizan como pruebas de cribado poblacional, sino como complemento diagnóstico o en grupos de alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97714c") }, {"long_answer": "Para afrontar el reto de la coordinación entre especialistas a lo largo del proceso diagnóstico y terapéutico, la Estrategia en Cáncer del SNS propone un modelo de atención multidisciplinaria, basado en comités de tumores y equipos en los que participan oncología, cirugía, radioterapia, anatomía patológica, radiología y enfermería, entre otros, para tomar decisiones conjuntas. La atención primaria individualizada es fundamental en otras fases, pero no resuelve la coordinación entre especialistas. Un enfoque hospitalario exclusivo o la atención ambulatoria general no garantizan esa coordinación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977151") }, {"question": "¿Qué tipo de evaluación requiere la medicina de precisión para analizar biomarcadores de pronóstico y de predicción de la respuesta terapéutica?", "long_answer": "La Estrategia en Cáncer del SNS señala que la medicina de precisión requiere una evaluación genómica del tumor, que permite identificar biomarcadores tanto pronósticos como predictivos de respuesta a terapias dirigidas, y seleccionar así el tratamiento más adecuado para cada paciente. La evaluación clínica y la diagnóstica son necesarias en todo proceso oncológico, pero no aportan por sí mismas esa información molecular. La evaluación patológica es la base del diagnóstico, aunque la caracterización de biomarcadores que define a la medicina de precisión es la genómica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977153") }, {"long_answer": "Una de las principales ventajas de la protonterapia es que concentra la dosis de radiación en el tumor y reduce la radiación que reciben los tejidos sanos circundantes, gracias al pico de Bragg característico de los protones. Esto la hace especialmente útil en tumores pediátricos y en localizaciones próximas a órganos críticos, ya que disminuye la toxicidad a largo plazo. No es menos efectiva que la radioterapia convencional, no aumenta la probabilidad de efectos adversos tardíos y no tiene menor precisión, sino mayor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97715c") }, {"question": "¿Cómo se estructura el Plan Europeo de Lucha contra el Cáncer?", "option_1": "En un único programa de cribado obligatorio para todos los Estados miembros", "option_2": "En diez iniciativas emblemáticas y múltiples acciones de apoyo", "option_3": "En tres líneas centradas exclusivamente en el tratamiento oncológico", "option_4": "En un sistema de vigilancia del cáncer laboral como única acción", "long_answer": "El Plan Europeo de Lucha contra el Cáncer, presentado por la Comisión Europea en 2021, se estructura en diez iniciativas emblemáticas y múltiples acciones de apoyo, organizadas en torno a la prevención, la detección precoz, el diagnóstico y tratamiento y la calidad de vida de pacientes y supervivientes. No se limita a un único programa de cribado obligatorio, ya que el cribado es solo una de sus áreas. Tampoco se centra exclusivamente en el tratamiento ni se reduce a la vigilancia del cáncer laboral, que es una de sus muchas actuaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97715d") }, {"long_answer": "La Estrategia en Cáncer del SNS aborda, en su línea de promoción de la salud y prevención, conductas relacionadas con la salud como el consumo de alcohol, junto con el tabaco, la alimentación, la actividad física y la exposición solar, ya que el alcohol es un carcinógeno que aumenta el riesgo de cáncer de boca, faringe, laringe, esófago, hígado, colon y mama. El uso de redes sociales, la práctica de deportes extremos y el estilo de vestimenta no son conductas de riesgo de cáncer abordadas en la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977165") }, {"long_answer": "En la Estrategia en Cáncer del SNS, el objetivo 28 se refiere a la atención psicológica de las personas con cáncer, y una de sus acciones es seleccionar la herramienta o herramientas estandarizadas más adecuadas para la detección precoz del malestar emocional, de modo que pueda derivarse a atención especializada a quien lo necesite. Realizar un estudio del impacto laboral, psicológico y social corresponde a otro objetivo. Establecer circuitos de seguimiento de pacientes sin enfermedad y definir un plan individualizado de seguimiento se vinculan a la atención a los supervivientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977166") }, {"long_answer": "En la Estrategia en Cáncer del SNS, el objetivo 29 se centra en mejorar el diagnóstico anatomopatológico, y una de sus acciones es implementar un sistema de doble lectura de la prueba de anatomía patológica en tumores raros, realizada por un patólogo experto de un centro de referencia designado, para reducir errores diagnósticos en tumores poco frecuentes. Definir o acordar el modelo organizativo de la oncología de precisión corresponde a otro objetivo, y proporcionar atención social a pacientes y familiares se vincula a las necesidades sociales de las personas con cáncer."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977168") }, {"long_answer": "En la Estrategia en Cáncer del SNS, el objetivo 31 aborda la relación y la comunicación entre profesionales y pacientes, y una de sus acciones es promover el conocimiento y las habilidades de relación y comunicación de los profesionales asistenciales para la toma de decisiones compartidas. Elaborar un protocolo de derivación a atención psicológica especializada corresponde al objetivo de atención psicológica. Incluir esta formación en los planes transversales de la formación sanitaria especializada es una acción de otro objetivo, y definir un plan individualizado de seguimiento se refiere a los supervivientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97716a") }, {"long_answer": "En la Estrategia en Cáncer del SNS, el objetivo 33 se refiere a la preservación de la fertilidad, y una de sus acciones es impulsar los protocolos de derivación a las Unidades de Reproducción Humana para el asesoramiento sobre preservación de la fecundidad en pacientes en edad fértil con deseo de descendencia, antes de tratamientos potencialmente gonadotóxicos. Definir el modelo organizativo de la oncología de precisión y fomentar el control de calidad del diagnóstico anatomopatológico corresponden a otros objetivos, al igual que promover las habilidades de comunicación de los profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97716d") }, {"option_3": "Se comportan como gases y se dispersan uniformemente por la estancia", "long_answer": "El documento técnico sobre transmisión de SARS-CoV-2 por aerosoles indica que las partículas mayores de 100 μm tienen un comportamiento balístico: son proyectadas con la tos, el estornudo o el habla y pueden alcanzar a una persona susceptible que esté cerca antes de caer por gravedad, por lo que la distancia física es eficaz frente a ellas. Quedar suspendidas en el aire durante largo tiempo y alcanzar cualquier parte de las vías respiratorias son propiedades de los aerosoles de pequeño tamaño. Tampoco se comportan como gases ni se dispersan uniformemente por la estancia."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97717e") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97717f") }, {"long_answer": "El documento técnico sobre transmisión de SARS-CoV-2 señala, entre los factores que podrían condicionar una mayor probabilidad de contraer la infección, el número de receptores ACE2 en el tracto respiratorio, ya que el virus los utiliza para entrar en las células, por lo que una mayor expresión facilita la infección. La respuesta inmunitaria previa frente a coronavirus estacionales podría conferir cierta protección cruzada, no mayor susceptibilidad. La edad avanzada se asocia sobre todo a mayor gravedad, y el grupo sanguíneo no se ha establecido como factor determinante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977181") }, {"long_answer": "El documento técnico sobre transmisión de SARS-CoV-2 recoge que la inhalación de aire frío aumenta la susceptibilidad a la infección, entre otros mecanismos porque favorece la replicación del virus en la mucosa nasal, cuya temperatura desciende, además de producir vasoconstricción y reducir el aclaramiento mucociliar y la respuesta inmune local. Por ello no aumenta la respuesta inmune, sino que la reduce. Tampoco produce vasodilatación del tracto respiratorio, sino vasoconstricción, ni disminuye el riesgo de transmisión, que tiende a aumentar en los meses fríos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977182") }, {"long_answer": "Los estudios recogidos en el documento técnico sobre transmisión de SARS-CoV-2 muestran una relación inversa entre la temperatura y la humedad y el número reproductivo básico (R0): cuando aumentan la temperatura y la humedad, la transmisibilidad del virus tiende a disminuir, por menor supervivencia viral y mejor funcionamiento de las defensas respiratorias, aunque estos factores no bastan por sí solos para controlar la transmisión. No se ha descrito una relación directa ni exponencial, y afirmar que no existe relación contradice los datos disponibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977183") }, {"question": "¿Qué factor favorece la transmisión del SARS-CoV-2 durante los meses fríos?", "option_1": "Mayor radiación ultravioleta solar", "option_2": "Mayor ventilación natural de los espacios interiores", "option_4": "Mayor tiempo dedicado a actividades al aire libre", "long_answer": "Durante los meses fríos aumenta el tiempo que las personas pasan en espacios cerrados y compartidos, lo que favorece el hacinamiento y la acumulación de aerosoles respiratorios, y en consecuencia la transmisión del SARS-CoV-2. A ello se suma una menor ventilación de los interiores para conservar el calor. La mayor radiación ultravioleta solar es propia de los meses cálidos y reduce la viabilidad del virus. Una mayor ventilación natural y más actividades al aire libre disminuirían el riesgo, por lo que no explican el aumento de transmisión en invierno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97718c") }, {"option_2": "Apagar la ventilación mecánica para evitar la dispersión de aerosoles", "long_answer": "En edificios con sistemas de climatización, el documento técnico sobre aerosoles recomienda evitar la recirculación del aire y maximizar la entrada de aire exterior, ya que así se diluyen y eliminan los aerosoles que pueden contener virus. Filtrar con el filtro de categoría más baja no retiene las partículas de pequeño tamaño, porque se recomienda la mayor eficacia de filtración compatible con el sistema. Apagar la ventilación mecánica favorece la acumulación de aerosoles, y no se recomienda usar tratamientos germicidas de forma habitual como sustituto de la ventilación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977198") }, {"long_answer": "La flebitis secundaria a la inserción de un catéter vascular se define como la inflamación aguda de la capa interna de la vena (íntima o endotelio), que se manifiesta con dolor, eritema, calor, edema o cordón venoso palpable en el trayecto del vaso, y puede tener origen mecánico, químico o infeccioso. No es una reacción alérgica a los materiales del catéter. La infección bacteriana en el punto de inserción es solo una de sus posibles causas, no su definición, y la rotura del catéter dentro de la vena es una complicación distinta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97719c") }, {"option_1": "Retirar el catéter y cultivar la punta, junto con hemocultivos, si se sospecha infección", "option_2": "Cultivar de forma rutinaria la punta de todos los catéteres retirados", "option_4": "Iniciar antibiótico empírico y diferir los hemocultivos 48 horas", "long_answer": "Ante la sospecha de infección relacionada con un catéter venoso periférico, el proyecto Flebitis Zero recomienda retirar el catéter y enviar la punta a cultivo, junto con la extracción de hemocultivos antes de iniciar el tratamiento antibiótico, y cultivar el exudado del punto de inserción si lo hubiera. No está indicado cultivar de forma rutinaria todos los catéteres retirados sin sospecha clínica. Afirmar que no es necesario ningún cultivo impide el diagnóstico etiológico, e iniciar el antibiótico difiriendo los hemocultivos reduce su rentabilidad diagnóstica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771a2") }, {"option_1": "Cuando se extrae sangre de una vía venosa", "long_answer": "Según la pirámide de uso de guantes de la OMS, no están indicados (salvo precauciones de contacto) en situaciones sin riesgo de exposición a sangre o fluidos, como la manipulación de un catéter vascular sin fugas de sangre, la toma de presión arterial o temperatura o la administración de inyecciones subcutáneas o intramusculares. La extracción de sangre de una vía venosa implica posible contacto con sangre y sí requiere guantes. Vaciar el recipiente para vómitos supone exposición a fluidos, por lo que también los requiere, y afirmar que siempre deben usarse guantes contradice las recomendaciones de la OMS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771a8") }, {"long_answer": "El modelo de registro del Conjunto Mínimo Básico de Datos de úlceras por presión (CMBD-UPP) se diseñó con el objetivo de ser útil en los diferentes contextos asistenciales y sistemas de prestación de servicios, es decir, en hospitales, atención primaria y centros sociosanitarios, permitiendo recoger de forma homogénea la información sobre estas lesiones. Evaluar los sistemas de información electrónicos no es su finalidad. Proporcionar un banco exhaustivo sobre actividad y morbilidad o comparar la casuística entre hospitales son funciones del CMBD hospitalario general, no del específico de UPP."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771a9") }, {"long_answer": "Conocer los propios medicamentos (para qué sirven, dosis, horario, forma de administración y posibles efectos adversos) es importante para prevenir problemas de salud derivados de su uso, como errores de administración, interacciones, duplicidades o falta de eficacia por mala adherencia. No tiene como fin evitar acudir al médico, ya que el seguimiento profesional sigue siendo necesario. Facilitar el trabajo de los profesionales puede ser una consecuencia, pero no es el motivo principal, y no tiene relación con aumentar el coste de la medicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ac") }, {"long_answer": "Ante el olvido de una dosis, la recomendación general es tomarla en cuanto se recuerde, salvo que falte poco para la siguiente toma, en cuyo caso se omite la dosis olvidada y se continúa con la pauta habitual; ante la duda, conviene consultar al profesional sanitario o al prospecto. Nunca debe tomarse una dosis doble para compensar el olvido, por el riesgo de toxicidad. Esperar siempre a la próxima dosis o ignorar el olvido sin más puede reducir la eficacia del tratamiento cuando aún hay tiempo para tomarla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ad") }, {"long_answer": "Si se observan efectos secundarios, lo adecuado es informar al profesional sanitario, que valorará su gravedad, su relación con el medicamento y la necesidad de ajustar la dosis, cambiar de fármaco o adoptar otras medidas, además de notificar la sospecha de reacción adversa. Dejar de tomar la medicación de forma inmediata y por iniciativa propia puede ser peligroso en muchos tratamientos, como antihipertensivos, anticoagulantes o corticoides. Ignorar los efectos o consultar con un amigo no permite una valoración adecuada ni segura."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ae") }, {"long_answer": "Mantener una lista actualizada de todos los medicamentos, plantas medicinales y otros productos que se toman permite a los profesionales conocer el tratamiento completo y evitar tomar medicamentos innecesarios, así como duplicidades, interacciones y errores, especialmente en las transiciones asistenciales. No es un requisito legal. Disponer de un registro detallado es útil, pero no es un fin en sí mismo, sino un medio para mejorar la seguridad, y afirmar que no es importante contradice las recomendaciones de seguridad del paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771af") }, {"answer": 4, "long_answer": "Los medicamentos sobrantes o caducados deben devolverse a la farmacia, donde se depositan en el Punto SIGRE para su recogida y tratamiento adecuados, evitando riesgos para la salud y la contaminación del medio ambiente. Tirarlos a la basura doméstica o por el desagüe no es correcto, ya que los principios activos pueden contaminar el agua y el suelo. Tomarlos de todas formas cuando están caducados puede suponer pérdida de eficacia o riesgos, y compartirlos con otras personas es peligroso porque no han sido prescritos para ellas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771dd") }, {"question": "En el sistema de alerta precoz y respuesta rápida, ¿qué fase permite valorar el impacto potencial de un evento sobre la salud de la población española?", "option_1": "Detección y análisis de señales", "option_2": "Generación de alertas", "option_3": "Evaluación rápida del riesgo", "option_4": "Comunicación de las alertas", "long_answer": "La evaluación rápida del riesgo para España es la fase del sistema de alerta precoz y respuesta rápida en la que se valora la probabilidad de que un evento de salud pública afecte a la población española y la magnitud de su posible impacto, con el fin de proponer medidas de control proporcionadas. La detección y análisis de señales es la fase previa de identificación de eventos. La generación de alertas consiste en declarar un evento como alerta, y la comunicación se refiere a la difusión de la información, no a la valoración del riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771de") }, {"option_4": "Bucear con botella", "long_answer": "Durante el embarazo se recomienda realizar actividad física moderada y regular, y caminar es una de las actividades más aconsejadas por ser segura, accesible y beneficiosa para el control del peso, la glucemia y el bienestar emocional, junto con otras como la natación. Correr puede mantenerse en mujeres previamente entrenadas, pero no se recomienda iniciarlo de forma general durante la gestación. Levantar pesas elevadas implica esfuerzos y maniobras de Valsalva poco recomendables, y el buceo con botella está contraindicado por el riesgo de descompresión para el feto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff6") }, {"long_answer": "La vigilancia complementaria de enterovirus no polio en muestras clínicas aumenta la sensibilidad del sistema porque permite detectar circulación de poliovirus en pacientes con cuadros neurológicos o síndromes compatibles que no cumplen estrictamente la definición de parálisis flácida aguda. Al analizar enterovirus en muestras de meningitis, encefalitis u otros cuadros, cualquier poliovirus que circule puede identificarse y caracterizarse en el Laboratorio Nacional de Polio. La vigilancia serológica de sarampión no aporta información sobre poliovirus, y restringir la vigilancia a centros escolares o a población adulta reduciría la sensibilidad en lugar de aumentarla, ya que excluiría a la población infantil y a otros ámbitos donde puede circular el virus.", "option_1": "Vigilancia serológica anual de anticuerpos frente a sarampión en escolares"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ffa") }, {"long_answer": "Según el Plan de acción para la erradicación de la poliomielitis, los centros y laboratorios que destruyen muestras positivas o potencialmente infecciosas para poliovirus deben certificarlo enviando el Anexo 6 al Laboratorio Nacional de Polio. Este procedimiento forma parte del compromiso de contención de poliovirus establecido por la OMS, que exige documentar la eliminación segura de los materiales para garantizar que no quedan reservorios del virus en laboratorios. Un informe de actividades clínicas o un informe epidemiológico semanal no acreditan la destrucción del material, y el Ministerio de Ciencia no es el destinatario de esta certificación, que se centraliza en el Laboratorio Nacional de Polio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978002") }, {"long_answer": "La guía sobre anestésicos locales establece que el abordaje enfermero dentro del equipo multidisciplinar debe garantizar el control y la minimización de los efectos adversos del anestésico local, lo que implica seleccionar adecuadamente fármaco y dosis, vigilar al paciente durante y después del procedimiento y actuar precozmente ante signos de toxicidad. La finalidad de la guía no es reducir el número de médicos, sino favorecer la colaboración entre profesionales. Tampoco puede prometer la eliminación total del dolor postoperatorio, objetivo poco realista, y la anestesia general queda fuera del ámbito de la indicación enfermera, que se limita a los anestésicos locales recogidos en la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978006") }, {"long_answer": "Ante la sospecha de intoxicación o reacción adversa grave por anestésicos locales, la actuación correcta es suspender inmediatamente la administración e informar al médico responsable para que valore al paciente y se inicien las medidas oportunas. La guía insiste en la seguridad del paciente y en el trabajo colaborativo, por lo que cualquier efecto adverso relevante obliga a detener el procedimiento y comunicarlo. Continuar con dosis menores mantiene la exposición al fármaco causante, administrar un antiinflamatorio no trata la toxicidad sistémica ni una reacción grave, y cambiar de anestésico sin informar vulnera la coordinación con el equipo y puede agravar el cuadro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97800a") }, {"long_answer": "La guía para la indicación, uso y autorización de dispensación de anestésicos locales por enfermeras establece que su contenido se revisará como mínimo cada cinco años, incorporando las novedades que procedan, como nueva evidencia científica, cambios en las fichas técnicas o modificaciones normativas. Este plazo es el habitual en las guías validadas al amparo del Real Decreto 954/2015. No se fija una revisión cada dos años con revisión obligatoria anual, ni una revisión automática cada vez que se autoriza un anestésico nuevo, y tampoco depende de que la soliciten los colegios profesionales, ya que la actualización corresponde al procedimiento de elaboración y validación previsto en la norma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97800f") }, {"long_answer": "Las guías de práctica clínica para la indicación enfermera se validan mediante resolución de la Dirección General de Salud Pública, que no pone fin a la vía administrativa. Por ello puede interponerse recurso de alzada ante la persona titular de la Secretaría de Estado de Sanidad en el plazo de un mes contado desde el día siguiente a su publicación en el Boletín Oficial del Estado, conforme a la Ley 39/2015 del Procedimiento Administrativo Común. El plazo de quince días naturales y el de tres meses desde la emisión de la guía no son los previstos, y afirmar que no es recurrible es incorrecto porque toda resolución administrativa admite recurso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978012") }, {"long_answer": "Conforme al Real Decreto 954/2015, modificado por el Real Decreto 1302/2018, los protocolos y guías de práctica clínica y asistencial para la indicación enfermera de medicamentos sujetos a prescripción médica se elaboran en el seno de la Comisión Permanente de Farmacia y se validan por la Dirección General de Salud Pública del Ministerio de Sanidad, actualmente Dirección General de Salud Pública y Equidad en Salud, publicándose en el BOE. El Consejo General de Enfermería participa en la elaboración pero no valida las guías. El Ministerio de Defensa interviene solo en lo relativo a las Fuerzas Armadas y la farmacia hospitalaria local carece de esa competencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978017") }, {"long_answer": "Entre las competencias enfermeras que recoge la guía de anestésicos locales figura asesorar y educar al paciente para favorecer su independencia en los autocuidados, informándole sobre el procedimiento, los efectos esperados, los signos de alarma y los cuidados posteriores. Esta labor educativa es uno de los objetivos centrales de la indicación enfermera. Realizar diagnósticos médicos complejos corresponde al ámbito médico, indicar anestesia general queda fuera de lo que regula la guía, que se limita a anestésicos locales, y ejecutar procedimientos sin consentimiento vulnera la Ley 41/2002 de autonomía del paciente, por lo que ninguna de estas opciones es una competencia enfermera."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978018") }, {"long_answer": "La administración intravenosa inadvertida de un anestésico local es una de las principales causas de toxicidad sistémica, con riesgo de manifestaciones neurológicas y cardiovasculares graves. Ante su sospecha, la actuación correcta es suspender la administración, avisar al médico y valorar de forma inmediata la aparición de signos de intoxicación, como sabor metálico, parestesias peribucales, mareo, convulsiones, arritmias o hipotensión. Aumentar la dosis incrementaría la toxicidad, continuar administrando solo vigilando constantes mantiene la exposición al fármaco y aplicar un tratamiento por iniciativa propia sin avisar al equipo rompe la coordinación asistencial que exige la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978019") }, {"long_answer": "La guía para la indicación, uso y autorización de dispensación de medicamentos sujetos a prescripción médica por parte de las enfermeras en el ámbito de los anestésicos locales tiene asignado el código de identificación 202401-GENFANESTÉSICOSLOCALES. Este código, que combina el año y mes de la versión con una abreviatura del contenido, permite identificar la guía en la orden de dispensación enfermera, donde debe constar el protocolo o guía que fundamenta la indicación. Los demás códigos no corresponden a esta guía y presentan formatos o abreviaturas que no se ajustan a la denominación oficial publicada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97801c") }, {"long_answer": "El Real Decreto 1718/2010, sobre receta médica y órdenes de dispensación, es la norma que regula expresamente la orden de dispensación, definida como el documento sanitario normalizado y obligatorio mediante el cual las enfermeras acreditadas indican o autorizan la dispensación de medicamentos y productos sanitarios. El Real Decreto 954/2015 desarrolla después las condiciones de la indicación enfermera remitiéndose a ese documento. El Real Decreto 1030/2006 establece la cartera de servicios comunes del SNS, la Ley General de Sanidad de 1986 es la norma marco del sistema sanitario y el Real Decreto Legislativo 1/2015 es el texto refundido de la Ley de garantías del medicamento, sin regular el formato de la orden enfermera.", "option_2": "Real Decreto 1030/2006"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978021") }, {"long_answer": "El Real Decreto 954/2015, modificado por el Real Decreto 1302/2018, reconoce a las enfermeras acreditadas la facultad de indicar, usar y autorizar la dispensación de medicamentos sujetos a prescripción médica conforme a protocolos o guías validados, como la guía de infección del tracto urinario inferior no complicada. No se trata de una prescripción ilimitada de antimicrobianos, ya que la actuación está acotada a los fármacos, la población y las situaciones que recoge la guía. Tampoco se limita a derivar a la paciente al médico ni a administrar medicamentos prescritos por otro profesional, puesto que la norma otorga a la enfermera un papel activo en la indicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97803c") }, {"long_answer": "El Real Decreto 954/2015, en su redacción dada por el Real Decreto 1302/2018, exige como requisito indispensable que la enfermera sea titular de la acreditación emitida por el órgano competente de su comunidad autónoma para poder indicar, usar y autorizar la dispensación de medicamentos sujetos a prescripción médica. Para obtenerla se requiere el título y experiencia profesional mínima de un año o la superación de un curso de adaptación, no tres años. No es necesario trabajar en un centro hospitalario público concreto, y el curso de adaptación es una vía alternativa para acreditarse, no un requisito general impuesto por el Ministerio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97803e") }, {"long_answer": "La orden de dispensación emitida por una enfermera acreditada debe incluir, entre otros datos, su número de colegiación o, en el caso de las Fuerzas Armadas, el código de identificación asignado, así como la especialidad acreditada cuando proceda. Estos datos permiten identificar al profesional y comprobar que está facultado para la indicación. Limitarse al nombre del paciente y del medicamento sería insuficiente, porque la orden exige también datos del profesional, del tratamiento y del protocolo aplicado. La dosis por sí sola no completa los requisitos y el certificado de formación no se adjunta a cada orden, ya que la acreditación consta en los registros correspondientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978040") }, {"long_answer": "Para obtener la acreditación en el ámbito de los cuidados generales, el Real Decreto 954/2015 modificado exige estar en posesión del título de Grado, Diplomado o ATS en Enfermería y acreditar una experiencia profesional mínima de un año, es decir, doce meses, o bien superar un curso de adaptación ofrecido de forma gratuita por la Administración. Seis o tres meses de experiencia no alcanzan el mínimo establecido y no se contempla ningún requisito de prácticas supervisadas. Cinco años de ejercicio continuo exceden lo exigido por la norma, que pretende facilitar el acceso a la acreditación de las enfermeras con experiencia básica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978041") }, {"long_answer": "Corresponde al órgano competente de cada comunidad autónoma otorgar la acreditación a las enfermeras para indicar, usar y autorizar la dispensación de medicamentos, ya que son las comunidades autónomas las que gestionan los servicios sanitarios y el procedimiento de acreditación dentro de su territorio, salvo en el ámbito de las Fuerzas Armadas, donde la competencia es del Ministerio de Defensa. El Ministerio de Sanidad establece el marco normativo básico pero no acredita individualmente, el Consejo General de Enfermería no tiene atribuida esta función y la Comisión Permanente de Farmacia se ocupa de la elaboración de protocolos y guías, no de las acreditaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978042") }, {"long_answer": "El Real Decreto contempla una vía excepcional para los profesionales de enfermería que, sin disponer del título de Graduado, Diplomado o Ayudante Técnico Sanitario, venían desarrollando las funciones reguladas antes de su entrada en vigor: pueden acceder a la acreditación presentando un certificado de competencias junto con una experiencia profesional mínima de tres meses. Con ello se reconoce la práctica previa sin exigir nuevos estudios. No pueden seguir ejerciendo estas funciones sin acreditación, porque la acreditación es requisito imprescindible, tampoco se les obliga a reiniciar un grado universitario y no quedan excluidos de forma absoluta de la indicación y dispensación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978046") }, {"long_answer": "La Comisión Permanente de Farmacia del Consejo Interterritorial del SNS es el órgano en cuyo seno se elaboran y aprueban, atendiendo a criterios técnicos y adoptando acuerdos por consenso, los protocolos y guías de práctica clínica y asistencial para la indicación enfermera, que posteriormente valida la Dirección General de Salud Pública y se publican en el BOE. La Comisión no emite ni ejecuta órdenes de dispensación, que corresponden a cada enfermera acreditada, no forma a las enfermeras para la acreditación, función que asumen las administraciones mediante cursos de adaptación, y no evalúa casos individuales tras la indicación, ya que su función es normativa y técnica de carácter general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97804d") }, {"long_answer": "La modificación del Real Decreto incorpora al Registro Estatal de Profesionales Sanitarios la información relativa a la acreditación para la indicación, uso y autorización de dispensación, incluyendo la fecha de la resolución de acreditación tanto en el ámbito de los cuidados generales como en el de los cuidados especializados. Así se puede verificar de forma centralizada qué enfermeras están facultadas. No se suprime el registro de especialidades, que sigue siendo relevante para la acreditación en cuidados especializados, no se exigen datos personales sensibles adicionales y las enfermeras no se categorizan como profesionales médicos, sino que conservan su condición propia de profesión sanitaria regulada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97804e") }, {"long_answer": "El Real Decreto se dicta al amparo del artículo 149.1.16ª de la Constitución Española, que atribuye al Estado la competencia exclusiva sobre las bases y coordinación general de la sanidad y sobre la legislación de productos farmacéuticos. Este título competencial justifica que la regulación de la indicación enfermera sea común en todo el territorio. El artículo 129 de la Ley 39/2015 recoge los principios de buena regulación, no un título competencial. La Ley 44/2003 de ordenación de las profesiones sanitarias es una norma con rango de ley, no un precepto constitucional, y el Reglamento General de Protección de Datos regula el tratamiento de datos personales, no el reparto de competencias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978050") }, {"long_answer": "El Real Decreto parte de que la indicación y dispensación de medicamentos por enfermeras se enmarca en una actuación colaborativa con el personal médico, cuyo objetivo es garantizar la seguridad del paciente y la continuidad asistencial. Por eso los protocolos establecen criterios comunes, situaciones de derivación y mecanismos de comunicación entre profesionales. La reducción de costes puede ser una consecuencia, pero no es el fin que proclama la norma. La rapidez sin valoración previa contradice la exigencia de una valoración enfermera adecuada, y el cumplimiento estricto de la receta médica no describe la indicación enfermera, que se basa en protocolos y guías validados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978056") }, {"long_answer": "Cuando la orden de dispensación se refiere a un medicamento sujeto a prescripción médica, debe recoger la información del protocolo o guía de práctica clínica y asistencial que fundamenta la indicación enfermera, ya que esa indicación solo es válida si se ajusta a un protocolo validado. Esta referencia permite al farmacéutico y a otros profesionales comprobar el marco en el que actúa la enfermera. La orden no exige el nombre ni el número de colegiado de un médico prescriptor, porque la emite la propia enfermera. El horario de administración no es un dato obligatorio específico y el certificado de experiencia no se incluye en la orden."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978059") }, {"long_answer": "Las enfermeras acreditadas pueden indicar, usar y autorizar la dispensación de medicamentos y productos sanitarios de uso humano sujetos a prescripción médica, siempre conforme a protocolos o guías de práctica clínica y asistencial validados. Los medicamentos no sujetos a prescripción y los productos sanitarios de uso común también pueden indicarlos de forma autónoma, pero la acreditación y los protocolos son necesarios precisamente para los sujetos a prescripción médica, por lo que limitar la facultad a los de venta libre es incorrecto. Tampoco se restringe a productos estériles hospitalarios ni a medicamentos sin seguimiento médico, ya que la guía define el seguimiento necesario en cada caso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e70") }, {"long_answer": "En la Guía de Práctica Clínica sobre la atención al parto normal, las asociaciones de mujeres participaron como miembros de pleno derecho en el grupo elaborador, con el objetivo de incorporar la perspectiva de las usuarias y fomentar unos cuidados adecuados y respetuosos con sus preferencias. Su implicación fue activa en todo el proceso, desde la formulación de preguntas hasta las recomendaciones. Por tanto, no es cierto que no participaran, ni que su papel se limitara a aportar datos estadísticos o a colaborar únicamente en la difusión de la guía una vez terminada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e71") }, {"long_answer": "La Guía de atención al parto normal fue elaborada por un grupo amplio de profesionales que representaban a distintas disciplinas implicadas en la atención al parto, como matronas, obstetras, pediatras, anestesiólogos y enfermeras, y a diferentes Comunidades Autónomas, para que las recomendaciones fueran aplicables en todo el SNS. El trabajo fue colaborativo y no individual. Su ámbito de aplicación es estatal, no restringido a una comunidad, y las recomendaciones no se dirigen solo a obstetras, sino a todos los profesionales que atienden a la mujer durante el parto normal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e72") }, {"long_answer": "El Plan de Calidad para el Sistema Nacional de Salud impulsó la elaboración y difusión de guías de práctica clínica con el fin de incrementar la cohesión y la calidad de la atención sanitaria en todo el territorio, reduciendo la variabilidad injustificada en la práctica clínica. La guía de atención al parto normal forma parte de esa estrategia. Su objetivo no es reducir el número de profesionales implicados ni establecer una duración uniforme del parto, que varía de forma fisiológica entre mujeres, y menos aún eliminar el acompañamiento, que la guía recomienda expresamente durante todo el proceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e76") }, {"long_answer": "La Guía de atención al parto normal se concibe como una herramienta de apoyo para la toma de decisiones de los profesionales, acompañada de materiales que facilitan su implementación, como versiones resumidas e información para pacientes. Sus recomendaciones se basan en la evidencia, pero deben aplicarse teniendo en cuenta la situación clínica concreta y las preferencias de cada mujer, por lo que no son reglas rígidas. Va dirigida a todos los profesionales implicados en la atención al parto, tanto matronas como médicos, y no exclusivamente a especialistas en ginecología o a matronas sin participación del resto del equipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e7f") }, {"long_answer": "Los cannabinoides sintéticos actúan como agonistas de los receptores cannabinoides CB1 y CB2, los mismos sobre los que actúa el THC del cannabis, aunque muchos de ellos lo hacen como agonistas completos y con mucha mayor potencia. Esto explica la mayor intensidad de sus efectos y su toxicidad, con cuadros de agitación, psicosis, convulsiones o complicaciones cardiovasculares. No ejercen su acción principal sobre receptores dopaminérgicos D1 y D2, opioides mu y kappa ni serotoninérgicos 5-HT1A, aunque la activación de CB1 pueda modular indirectamente otros sistemas de neurotransmisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e82") }, {"long_answer": "El dossier sobre cannabinoides sintéticos describe como forma frecuente de adulteración la impregnación de cáñamo industrial con bajo contenido en THC con cannabinoides sintéticos, de modo que el producto aparenta ser cannabis convencional pero contiene sustancias mucho más potentes y peligrosas, sin que el consumidor lo sepa. Mezclar cannabis con CBD puro no constituye la adulteración descrita y no aumenta los efectos psicoactivos. Añadir extractos vegetales sin efecto psicoactivo o diluir con tabaco no son las prácticas señaladas, ya que el objetivo de la adulteración es precisamente simular o potenciar los efectos del cannabis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e84") }, {"long_answer": "En los últimos años la vigilancia europea ha registrado un incremento notable de notificaciones de productos adulterados con cannabinoides sintéticos, como cannabis, resinas o productos comestibles, y la Agencia de la Unión Europea sobre Drogas (EUDA) realiza un seguimiento continuado mediante el sistema de alerta temprana. No se ha observado una disminución del consumo ni la desaparición de nuevos compuestos; al contrario, siguen apareciendo sustancias nuevas. La vigilancia no se limita a cannabinoides naturales y no se ha abandonado, porque estos productos se asocian a intoxicaciones graves e incluso muertes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e9b") }, {"long_answer": "Para la Agencia de la Unión Europea sobre Drogas (EUDA), los cannabinoides sintéticos son nuevas sustancias psicoactivas sujetas al sistema de alerta temprana y, cuando existe evidencia de daño, a evaluación de riesgos que puede conducir a medidas de control en toda la Unión Europea. No se consideran sustancias legales sin restricciones, aunque algunas puedan escapar temporalmente a la fiscalización por su novedad química. No quedan excluidas del sistema de alerta, ya que precisamente se vigilan por su elevada toxicidad, y no se clasifican como suplementos alimentarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea6") }, {"long_answer": "En el estudio de fiabilidad de la Clinical Frailty Scale y la FRAIL en su versión española, las diferencias en gravedad y comorbilidades entre pacientes frágiles y no frágiles se consideraron estadísticamente significativas con un valor de p menor de 0,05, el umbral convencional en investigación clínica, que indica una probabilidad inferior al 5 % de que la diferencia observada se deba al azar. Un valor de p mayor de 0,10 o igual a 0,1 no alcanza la significación estadística habitual, y afirmar que no se consideraron significativas contradice los resultados descritos en el estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eaa") }, {"long_answer": "En el diseño del estudio de concordancia, la valoración de la Enfermera 1 (E1) se tomó como referencia para comparar las puntuaciones del resto de enfermeras evaluadoras, de forma análoga a como se tomó un evaluador médico de referencia para el grupo médico. Fijar un evaluador de referencia permite estimar la concordancia de cada observador frente a un patrón común. La Enfermera 2 y la Enfermera 3 actuaron como evaluadoras comparadas, y el Médico 2 pertenecía al grupo de evaluadores médicos, por lo que no era la referencia de las valoraciones enfermeras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eab") }, {"long_answer": "La consistencia interna de la FRAIL-España se evaluó mediante la fórmula 20 de Kuder-Richardson, que es el estadístico indicado cuando los ítems de una escala son dicotómicos, como ocurre en la FRAIL, cuyos cinco ítems se responden sí o no. Equivale al alfa de Cronbach adaptado a respuestas binarias. El alfa de Cronbach se usa para ítems con respuestas ordinales o continuas, el test de Shapiro-Wilk sirve para comprobar la normalidad de una distribución y el coeficiente de Pearson mide correlación lineal entre variables cuantitativas, no consistencia interna."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb4") }, {"long_answer": "En la población estudiada para validar la CFS-España y la FRAIL-España en pacientes críticos, las mujeres representaban aproximadamente el 40 % de la muestra, de modo que predominaban los varones, algo habitual en las unidades de cuidados intensivos, donde los hombres ingresan con mayor frecuencia. Los porcentajes del 23 %, 53 % y 64 % no corresponden a la distribución por sexo descrita en el estudio: el 23 % infraestimaría la proporción de mujeres, mientras que el 53 % y el 64 % supondrían un predominio femenino que no se observó en la muestra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb6") }, {"long_answer": "En el estudio, los pacientes considerados frágiles presentaron una mediana de SAPS3 de 68, con rango intercuartílico de 60 a 77, mayor que la de los no frágiles. El SAPS3 es una escala pronóstica de gravedad al ingreso en UCI, y su valor más elevado en los frágiles concuerda con la asociación entre fragilidad, mayor gravedad y peor pronóstico. Las cifras de 60 [50-69] y 55 [45-62] son demasiado bajas para el grupo frágil descrito, y 72 [64-80] no corresponde al valor publicado, por lo que la opción que refleja los resultados es 68 [60-77]."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ebc") }, {"long_answer": "Para evaluar la concordancia interobservador entre tres evaluadores en una variable categórica se utilizó el índice kappa de Fleiss, que generaliza el kappa de Cohen a más de dos observadores y corrige el acuerdo esperado por azar. El test de Shapiro-Wilk sirve para comprobar si una variable sigue una distribución normal, el ANOVA de un factor compara medias entre varios grupos y el coeficiente de Spearman mide la correlación entre dos variables ordinales; ninguno de ellos cuantifica el grado de acuerdo entre varios observadores que clasifican a los mismos pacientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec7") }, {"long_answer": "El sistema suizo revisado clasifica el riesgo de parada cardiaca en la hipotermia accidental según el nivel de conciencia, y considera de bajo riesgo al paciente alerta, que se corresponde con una puntuación de 15 en la escala de coma de Glasgow. A medida que disminuye el nivel de conciencia aumenta el riesgo: una puntuación de 14 a 9, equivalente a respuesta verbal, implica riesgo moderado; una puntuación inferior a 9, con respuesta solo al dolor, supone riesgo alto, y una puntuación de 3, paciente que no responde, se asocia al riesgo máximo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed7") }, {"long_answer": "Según el sistema suizo revisado, el paciente hipotérmico alerta, con una puntuación de 15 en la escala de coma de Glasgow, es el que presenta riesgo bajo de parada cardiaca, porque la conservación completa del nivel de conciencia indica una hipotermia menos profunda. La respuesta verbal con puntuación de 14 se asocia a riesgo moderado, la respuesta solo al dolor con puntuación inferior a 9 indica riesgo alto, y el paciente que no responde, con puntuación de 3, tiene el riesgo más elevado, por lo que requiere monitorización estrecha y traslado a un centro con capacidad de soporte circulatorio extracorpóreo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977edc") }, {"long_answer": "La presión arterial elevada sin síntomas no altera el nivel de conciencia y, por tanto, no provoca sobreestimación del riesgo de parada cardiaca al aplicar el sistema suizo revisado. Este sistema se basa en el nivel de conciencia, por lo que cualquier causa distinta de la hipotermia que lo disminuya puede hacer que se clasifique al paciente en una categoría de riesgo mayor que la real. Es el caso de la intoxicación por alcohol o drogas, del edema cerebral de la altitud y del traumatismo grave, especialmente el craneoencefálico, situaciones que el profesional debe tener en cuenta al interpretar la clasificación.", "question": "¿Cuál de los siguientes factores NO se considera una causa de sobreestimación del riesgo de paro cardiaco al aplicar el sistema suizo revisado (SSR)?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ede") }, {"long_answer": "Según la guía de práctica clínica sobre el trastorno de ansiedad generalizada, el inicio temprano del trastorno se ha asociado al sexo femenino y a mayores niveles educativos, entre otros factores descritos en los estudios epidemiológicos. Las mujeres presentan además una prevalencia del TAG aproximadamente dos veces superior a la de los hombres. El sexo masculino con bajo nivel educativo no es el perfil asociado al inicio precoz, el nivel socioeconómico alto no se señala como factor de inicio temprano y el consumo temprano de sustancias es una comorbilidad frecuente, pero no se identifica como el principal factor asociado a la edad de inicio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee0") }, {"long_answer": "La guía de práctica clínica sobre el trastorno de ansiedad generalizada recoge una prevalencia estimada a lo largo de la vida del 5,7 % según estudios prospectivos, cifra que refleja que el TAG es uno de los trastornos de ansiedad más frecuentes y con mayor impacto en atención primaria. Los valores del 2,8 % y del 4,3 % corresponden a estimaciones menores, como las de prevalencia anual o de estudios transversales con distinta metodología, mientras que el 11,7 % sobreestima claramente la frecuencia del trastorno en la población general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee2") }, {"long_answer": "Ante una persona con sospecha de trastorno de ansiedad generalizada en atención primaria, la guía sugiere como primer paso una evaluación integral mediante entrevista clínica, apoyada en escalas validadas como la GAD-7, para confirmar el diagnóstico, valorar la gravedad y detectar comorbilidades. Solo después se decide el tratamiento por pasos. Iniciar de inmediato un fármaco o una terapia cognitivo-conductual sin evaluar al paciente omite el diagnóstico y la estratificación de la gravedad, y la derivación directa a salud mental se reserva para casos graves, refractarios o con riesgo, no como paso inicial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee3") }, {"long_answer": "La evaluación integral del paciente con TAG en atención primaria debe incluir los factores precipitantes, las comorbilidades físicas y psiquiátricas, la presencia de ideación suicida, el contexto social y familiar y la respuesta a tratamientos previos, además de la duración y gravedad de los síntomas. Este enfoque global permite ajustar el plan terapéutico y detectar situaciones de riesgo. Limitarse a la duración y gravedad de los síntomas, a una evaluación física y analítica o únicamente a los antecedentes familiares psiquiátricos dejaría fuera aspectos esenciales para el manejo del trastorno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee9") }, {"long_answer": "La guía sugiere iniciar los inhibidores selectivos de la recaptación de serotonina en el TAG con una dosis baja y aumentarla de forma gradual según la tolerabilidad, porque al inicio pueden aparecer efectos como aumento transitorio de la ansiedad, náuseas o inquietud, que favorecen el abandono. Por ello es incorrecto afirmar que no se recomienda empezar con dosis bajas o que es preferible comenzar con dosis altas. Además, la guía insiste en informar al paciente sobre los posibles efectos adversos y la latencia de respuesta, de modo que la opción que niega la necesidad de informar también es falsa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eed") }, {"long_answer": "Según la guía, la pregabalina se sugiere como tratamiento de segunda línea en pacientes con TAG que no toleran los ISRS ni los IRSN, y puede resultar especialmente útil cuando coexiste dolor neuropático, ya que también está indicada en esta situación. No es cierto que no se recomiende en ningún caso, puesto que tiene indicación autorizada en el TAG. Tampoco debe prescribirse sin restricciones, dado su potencial de abuso y dependencia, y no se asocia a una alta tasa de efectos adversos graves, aunque son frecuentes el mareo y la somnolencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eee") }, {"long_answer": "Al prescribir pregabalina en el TAG se debe evitar su uso en personas con riesgo o antecedentes de abuso de sustancias, ya que se han descrito casos de mal uso, abuso y dependencia, sobre todo en consumidores de opioides. No está especialmente indicada en ancianos con deterioro cognitivo, en quienes el mareo, la somnolencia y la confusión aumentan el riesgo de caídas. Las dosis deben ajustarse de forma progresiva sin buscar dosis muy altas y, como cualquier psicofármaco, requiere seguimiento de la eficacia, los efectos adversos y los signos de uso indebido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef0") }, {"long_answer": "La guía sugiere que, si se utiliza quetiapina en el TAG desde atención primaria, se haga a dosis bajas, con una dosis máxima de 50 mg al día, dado que a dosis mayores aumentan los efectos adversos metabólicos, la sedación y el aumento de peso sin una ganancia clara de eficacia en este ámbito. Las dosis de 100, 150 o 300 mg diarios superan el límite propuesto para su manejo en atención primaria, y su uso en esos rangos requeriría la valoración por atención especializada en salud mental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef8") }, {"long_answer": "La guía sugiere recomendar la práctica supervisada de ejercicio físico como complemento terapéutico en el trastorno de ansiedad generalizada, ya que contribuye a reducir los síntomas ansiosos y mejora el bienestar general. Por tanto, no es cierto que no se recomiende ningún tipo de ejercicio. Tampoco sustituye a las intervenciones psicológicas ni al tratamiento farmacológico cuando están indicados, sino que se suma a ellos, y su utilidad no se limita a los casos leves, pudiendo beneficiar a pacientes con distintos grados de gravedad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977efe") }, {"long_answer": "Según el documento de recomendaciones de vacunación frente a COVID-19, en la temporada 2024-2025 entre el 67 % y el 74 % de las hospitalizaciones por COVID-19 correspondieron a personas de 70 años o más, lo que confirma que la edad avanzada es el principal factor de riesgo de enfermedad grave y justifica la prioridad de este grupo en la campaña. Los rangos del 30-40 % y del 50-55 % infraestiman el peso de este grupo en las hospitalizaciones, mientras que el 85-90 % lo sobreestima respecto a los datos de vigilancia de la temporada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f01") }, {"long_answer": "En la población infantil de 6 meses a 4 años perteneciente a grupos de riesgo y sin antecedentes de vacunación ni de infección previa, las recomendaciones establecen una primovacunación de tres dosis con pauta 0-3-8 semanas, es decir, la segunda dosis tres semanas después de la primera y la tercera ocho semanas después de la segunda, con la formulación pediátrica correspondiente. A partir de los 5 años se administra una sola dosis independientemente de los antecedentes. Una dosis única o dos dosis separadas tres semanas no completan la pauta en este grupo de edad, y cuatro dosis exceden lo recomendado.", "question": "Según las recomendaciones de vacunación frente a COVID-19 para la temporada 2025-2026, ¿cuántas dosis se administran a un niño de entre 6 meses y 4 años sin antecedentes de vacunación ni infección previa?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f04") }, {"long_answer": "Para la temporada 2025-2026, las vacunas frente a COVID-19 se han adaptado a la variante LP.8.1, perteneciente al linaje JN.1 de ómicron, siguiendo las recomendaciones de la Agencia Europea de Medicamentos y de la OMS sobre la composición antigénica, con el objetivo de ajustarse a las variantes que circulan actualmente. La variante Delta dejó de circular hace años, la ómicron BA.5 se utilizó en vacunas bivalentes de temporadas anteriores y la KP.2 fue una de las opciones empleadas en la temporada 2024-2025, pero no es la incluida en la composición de 2025-2026."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f06") }, {"long_answer": "En las personas con inmunosupresión extrema, como receptores de trasplante o pacientes en tratamiento con determinados inmunosupresores, se puede administrar una dosis adicional de vacuna frente a COVID-19 siempre que hayan transcurrido al menos tres meses desde la última dosis o desde la última infección, ya que la respuesta inmunitaria es menor y menos duradera. No es necesario esperar un año desde la última vacunación, la recomendación no excluye la dosis adicional en este grupo y su administración no depende de la aparición de síntomas graves, sino que es una medida preventiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f07") }, {"long_answer": "En la campaña 2025-2026 la vacunación frente a COVID-19 se recomienda en grupos de riesgo a partir de los 6 meses de edad, que es la edad mínima para la que existen vacunas autorizadas. En los niños de 6 meses a 4 años se emplea la formulación pediátrica correspondiente. Fijar la edad mínima en 1 año, 12 años o 18 años dejaría sin protección a lactantes y niños con condiciones de riesgo, como inmunodepresión o enfermedades crónicas graves, que tienen mayor probabilidad de enfermedad grave."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f08") }, {"long_answer": "Entre los grupos de riesgo por patología crónica en la campaña 2025-2026 se incluyen las personas con enfermedades cardiovasculares con afectación cardiaca, como insuficiencia cardiaca o cardiopatía isquémica, por su mayor riesgo de complicaciones y hospitalización si se infectan. Las recomendaciones se dirigen a enfermedades crónicas con repercusión clínica significativa. Una enfermedad pulmonar leve asintomática, una anemia leve sin complicaciones o las alergias estacionales no constituyen condiciones de riesgo que justifiquen la indicación de vacunación frente a COVID-19 por sí mismas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f0f") }, {"long_answer": "El trasplante de progenitores hematopoyéticos es uno de los criterios que definen la inmunosupresión extrema en las recomendaciones de vacunación frente a COVID-19, junto con el trasplante de órgano sólido, la inmunodeficiencia primaria grave o determinados tratamientos inmunosupresores. Estos pacientes tienen una respuesta vacunal reducida y mayor riesgo de enfermedad grave. La diabetes descompensada, la hipertensión arterial leve o la EPOC moderada pueden ser condiciones de riesgo, pero sin tratamiento inmunosupresor no cumplen el criterio de inmunosupresión extrema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f19") }, {"long_answer": "Las recomendaciones indican aprovechar cada contacto con el sistema sanitario para revisar el estado de vacunación y completar el calendario según la edad, los antecedentes y las condiciones de riesgo de cada persona, incluida la coadministración con otras vacunas como la de la gripe. Administrar solo la vacuna frente a COVID-19 desaprovecha la oportunidad de completar otras vacunaciones pendientes. Retrasar la vacunación a la espera de vacunas nuevas deja a la persona sin protección durante la temporada, y ofrecer solo la vacuna antigripal ignora la indicación frente a COVID-19 en los grupos de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f21") }, {"long_answer": "Las recomendaciones de vacunación antigripal incluyen al personal de los centros sanitarios y sociosanitarios, así como a los estudiantes en prácticas en estos centros, entre los grupos que deben vacunarse para reducir la transmisión de la gripe a las personas con riesgo de complicaciones. Su contacto estrecho con pacientes vulnerables convierte su vacunación en una medida de protección colectiva. Las personas de 30 a 50 años sin riesgo no son un grupo prioritario, la recomendación no se limita al personal con experiencia, ya que alcanza también a los estudiantes, y la exposición únicamente familiar no se corresponde con este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f24") }, {"long_answer": "La campaña de vacunación antigripal de la temporada 2025-2026 se inicia a partir de la última semana de septiembre y se desarrolla principalmente durante el mes de octubre, con el fin de alcanzar coberturas elevadas antes de que comience la circulación del virus, que suele producirse a finales de otoño e invierno. Iniciarla en julio o principios de agosto sería prematuro, ya que las vacunas no están disponibles y la protección podría disminuir antes del pico epidémico. Esperar a noviembre retrasaría la protección y aumentaría el riesgo de que la epidemia comience antes de alcanzar coberturas adecuadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f26") }, {"long_answer": "Las personas con alergia al huevo pueden recibir la vacuna antigripal inactivada sin precauciones especiales, ya que el contenido de ovoalbúmina de las vacunas actuales es mínimo; únicamente en los antecedentes de reacción alérgica grave o anafilaxia al huevo se recomienda vacunar en un entorno con capacidad de respuesta y mantener un periodo de observación. No deben evitar todas las vacunas antigripales, porque la alergia al huevo no contraindica la vacunación. No se limita su uso a la vacuna atenuada intranasal y no es necesario vacunar a todas en el ámbito hospitalario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f28") }, {"long_answer": "Las personas de 20 a 49 años sanas, sin patologías de base ni exposición laboral de riesgo, no figuran entre los grupos priorizados en las recomendaciones de vacunación antigripal 2025-2026, ya que tienen bajo riesgo de complicaciones y no suponen un riesgo especial de transmisión a personas vulnerables. En cambio, sí se incluyen expresamente las personas residentes en centros de discapacidad, las embarazadas en cualquier trimestre de la gestación, por el riesgo de complicaciones en la madre y el recién nacido, y el personal sanitario y sociosanitario, por su papel en la transmisión a pacientes de riesgo.", "option_3": "Personas de 20 a 49 años sin patologías ni exposición laboral de riesgo"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f29") }, {"long_answer": "En los receptores de trasplante de progenitores hematopoyéticos, la respuesta a la vacuna antigripal es reducida en los primeros meses tras el trasplante. Por ello, si la vacuna se administra antes de que hayan transcurrido seis meses desde el trasplante, como puede ocurrir durante la temporada epidémica, se recomienda administrar una segunda dosis a las cuatro semanas para mejorar la respuesta inmunitaria. No aplicar ninguna dosis adicional dejaría al paciente con una protección insuficiente, no se contempla una tercera dosis a los seis meses y esperar al año siguiente lo dejaría desprotegido durante toda la temporada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f2c") }, {"long_answer": "Las recomendaciones indican aprovechar las visitas a los centros sanitarios durante la campaña para revisar y completar el estado de vacunación de cada persona según los calendarios vigentes, incluyendo vacunas como la del neumococo, la dTpa, el herpes zóster o la COVID-19 cuando estén indicadas. La coadministración es segura y mejora las coberturas. Limitar la vacunación a visitas específicas de campaña o a la primera visita del año reduce las oportunidades de vacunar, y evitar la coadministración no está justificado, ya que no aumenta de forma relevante los efectos adversos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f2d") }, {"long_answer": "Las personas de 5 a 18 años que reciben tratamiento prolongado con ácido acetilsalicílico deben vacunarse frente a la gripe porque la infección gripal en estas circunstancias se asocia al síndrome de Reye, una encefalopatía aguda con afectación hepática potencialmente mortal. La vacunación reduce el riesgo de padecer gripe y, con ello, esta complicación. No vacunarlas aumentaría precisamente el riesgo que se quiere evitar, la indicación no depende de la presencia de otras patologías y no existe una formulación especial de vacuna antigripal relacionada con el ácido acetilsalicílico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f2e") }, {"long_answer": "Para las personas mayores, las recomendaciones de la temporada 2025-2026 contemplan, además de las vacunas inactivadas convencionales, las vacunas de alta carga antigénica y las adyuvadas, que inducen una mejor respuesta inmunitaria en este grupo, en el que la inmunosenescencia reduce la eficacia de las vacunas estándar. Limitarse solo a las vacunas convencionales ignora estas formulaciones mejoradas. La vacuna atenuada intranasal está autorizada en población infantil y adolescente, no en mayores, y en ningún caso se recomiendan vacunas experimentales sin autorización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f2f") }, {"long_answer": "Dentro de la categoría de otros grupos en los que se recomienda la vacunación antigripal se incluye al personal de guarderías y de centros de educación infantil hasta los 6 años, por su contacto estrecho con niños pequeños, que tienen las tasas de incidencia de gripe más altas y actúan como transmisores. La recomendación no se limita a trabajadores sanitarios rurales ni a viajeros frecuentes. Las personas con enfermedades autoinmunes en tratamiento inmunosupresor se incluyen entre los grupos con riesgo de complicaciones por su condición clínica, no en la categoría de otros grupos de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f30") }, {"long_answer": "La Organización Mundial de la Salud publica cada año la composición recomendada de la vacuna antigripal para cada hemisferio a partir de los datos de su red mundial de vigilancia; para el hemisferio norte la recomendación se emite en febrero, lo que permite fabricar las vacunas antes del inicio de la temporada. La Organización Panamericana de la Salud adopta estas recomendaciones para su región pero no las elabora, y el Ministerio de Sanidad y el Centro Nacional de Epidemiología aplican y vigilan en España, sin fijar la composición antigénica de la vacuna."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f32") }, {"long_answer": "Para alcanzar los objetivos de cobertura de la temporada 2025-2026, las recomendaciones insisten en reforzar la captación activa de las personas de 80 años o más, de los residentes en centros de mayores y de discapacidad, del personal sanitario y sociosanitario y de las embarazadas, grupos en los que las coberturas siguen siendo mejorables y el beneficio es mayor. La población menor de 18 años sin factores de riesgo no es una prioridad, centrarse únicamente en los niños de 6 a 59 meses dejaría fuera a los grupos más vulnerables y desincentivar la vacunación contradice los objetivos de la campaña."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f33") }, {"long_answer": "Las recomendaciones de vacunación frente a la gripe se amparan en la Ley 33/2011, General de Salud Pública, que atribuye a las administraciones sanitarias la planificación de las políticas de vacunación y establece que el calendario y las recomendaciones se acuerdan en el Consejo Interterritorial del SNS. La normativa de Seguridad Social regula prestaciones económicas, no la política de vacunación. Una recomendación comunitaria europea no tiene carácter vinculante como fundamento de las recomendaciones nacionales, y el Código Penal no regula la vacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f35") }, {"long_answer": "Durante la temporada 2024-2025 se produjo una circulación conjunta de virus de la gripe A, con los subtipos A(H1N1)pdm09 y A(H3N2), y de virus B, que aumentó en la fase final de la temporada. Esta cocirculación se asoció a un impacto de gravedad menor que en temporadas dominadas casi exclusivamente por A(H3N2), subtipo que suele afectar más a las personas mayores. La circulación no fue exclusiva de la gripe A ni de la gripe B, y el virus del resfriado común no forma parte de la vigilancia de la gripe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f36") }, {"long_answer": "En las últimas temporadas analizadas, la mayor tasa de incidencia de gripe en atención primaria se registró en la población infantil menor de 15 años, y especialmente en los menores de 5 años, que se infectan con mayor frecuencia y contribuyen de forma importante a la transmisión en la comunidad. Por ello se recomienda la vacunación de los niños de 6 a 59 meses. Las personas mayores de 70 años presentan mayor gravedad y hospitalización, pero no la mayor incidencia en atención primaria, y los adultos de 30 a 69 años muestran tasas de incidencia inferiores a las infantiles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f37") }, {"long_answer": "Las personas con antecedentes de alergia grave al huevo, como la anafilaxia, pueden vacunarse frente a la gripe con vacunas inactivadas, pero se recomienda hacerlo en un centro con capacidad para atender reacciones alérgicas y mantener a la persona en observación durante 30 minutos bajo supervisión adecuada. Afirmar que no requiere ninguna vigilancia especial ignora el antecedente de reacción grave. Doce horas de observación en un centro sanitario son innecesarias, ya que las reacciones anafilácticas aparecen casi siempre en los primeros minutos, y la observación domiciliaria no permite una respuesta inmediata."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f3a") }, {"long_answer": "A las mujeres en edad fértil susceptibles y no embarazadas se les recomienda la vacuna triple vírica y la vacuna de la varicela, ya que la rubeola y la varicela adquiridas durante el embarazo pueden causar síndrome de rubeola congénita o varicela congénita. Al tratarse de vacunas atenuadas contraindicadas en la gestación, deben administrarse antes, evitando el embarazo durante el mes siguiente. Las vacunas antigripal y de hepatitis B pueden administrarse también durante el embarazo, la gripe intranasal no está indicada en adultas y la vacunación frente a tétanos y hepatitis A no responde al objetivo de prevenir la embriopatía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f3b") }, {"long_answer": "Se recomiendan dos dosis de triple vírica a las personas nacidas en España a partir de 1970 sin vacunación documentada porque los casos y brotes de sarampión afectan principalmente a estas cohortes, que no tuvieron contacto con el virus salvaje en la infancia y pueden no haber recibido la vacuna completa. Las personas nacidas antes de 1970 se consideran inmunes por haber pasado la enfermedad. Las dosis no confieren inmunidad inmediata ni protegen frente a la varicela o la hepatitis B, ya que la triple vírica previene sarampión, rubeola y parotiditis, y su efectividad frente a la rubeola es elevada, no baja."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f3e") }, {"long_answer": "En las mujeres en edad fértil sin antecedentes de varicela ni vacunación previa se recomiendan dos dosis de vacuna frente a la varicela separadas por un intervalo mínimo de cuatro semanas, con lo que se consigue una protección adecuada. Al tratarse de una vacuna atenuada, debe evitarse el embarazo durante el mes posterior a cada dosis. Una sola dosis no completa la pauta en adultos, tres dosis con dos semanas de separación no corresponden a ninguna pauta autorizada y la administración durante el embarazo está contraindicada por el riesgo teórico para el feto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f40") }, {"long_answer": "Las vacunas de virus vivos atenuados, como la triple vírica, la de la varicela o la de la fiebre amarilla, están contraindicadas durante el embarazo por el riesgo teórico de transmisión del virus vacunal al feto, aunque no se hayan demostrado malformaciones tras su administración inadvertida. Por eso se recomienda vacunar antes de la gestación o en el puerperio. Las vacunas inactivadas, las toxoides, como el tétanos o la dTpa, y las conjugadas no contienen microorganismos capaces de replicarse y pueden administrarse durante el embarazo cuando están indicadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f43") }, {"long_answer": "En una mujer embarazada sin constancia de vacunación previa frente a tétanos y difteria se recomienda iniciar la primovacunación con tres dosis según el esquema 0, 1 y 6 meses, sustituyendo una de ellas por dTpa, que se administrará preferentemente entre las semanas 27 y 36 de gestación para proteger al recién nacido frente a la tosferina. La pauta se completa después del parto si es necesario. Dos dosis separadas un mes o una dosis única no completan la primovacunación, y no vacunar durante el embarazo dejaría a la madre y al recién nacido sin protección frente al tétanos y la tosferina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f4b") }, {"long_answer": "Cuando durante la gestación se detecta que una mujer es susceptible a la rubeola o a la varicela, la vacunación debe posponerse hasta después del parto, en el puerperio, porque ambas son vacunas de virus vivos atenuados contraindicadas durante el embarazo. La lactancia materna no contraindica su administración. Vacunar inmediatamente durante el embarazo, en el primer trimestre o al inicio del segundo supondría administrar una vacuna atenuada a una mujer gestante, lo cual no está recomendado en ninguna etapa del embarazo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f4d") }, {"long_answer": "La vacuna de la fiebre amarilla es atenuada y, en general, se evita en el embarazo, pero puede administrarse a una mujer embarazada cuando el riesgo de infección es alto, por ejemplo ante un viaje inevitable a una zona endémica o epidémica, ya que la enfermedad tiene una elevada letalidad y no existe alternativa inactivada. La vacuna de la varicela y la triple vírica están contraindicadas en el embarazo sin excepción. Frente a la fiebre tifoidea sí existe una vacuna inactivada de polisacárido Vi, por lo que la oral atenuada no debe emplearse en la gestación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f57") }, {"long_answer": "Cuando se desconoce la historia vacunal frente al tétanos de una mujer embarazada, se considera no vacunada y se inicia una pauta de tres dosis de Td con esquema 0, 1 y 6 meses, sustituyendo una de ellas por dTpa entre las semanas 27 y 36 de gestación para proteger también al lactante frente a la tosferina. Una sola dosis de Td en el primer trimestre no garantiza la inmunidad. No vacunar durante el embarazo o hacerlo únicamente tras el parto dejaría a la madre y al recién nacido sin protección frente al tétanos neonatal y la tosferina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f58") }, {"long_answer": "Las mujeres embarazadas con asplenia anatómica o funcional, déficit del complemento o que han sido contactos de un caso de enfermedad meningocócica invasiva tienen indicación de vacunación meningocócica, utilizando las vacunas MenC, MenACWY o MenB según el caso, ya que el beneficio de prevenir una enfermedad grave supera los riesgos teóricos. La vacuna antigripal inactivada está recomendada en todas las embarazadas, pero no protege frente al meningococo. La triple vírica y la vacuna de la varicela son atenuadas y están contraindicadas durante el embarazo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f59") }, {"long_answer": "El Sistema de Información del programa poblacional de cribado de cáncer (SICC) tiene como objetivo principal disponer de información homogénea que permita el seguimiento y la evaluación de los programas de cribado de cáncer de mama, colorrectal y de cérvix, tanto a nivel estatal como autonómico, mediante indicadores consensuados de participación, calidad y resultados. No gestiona la asignación presupuestaria de las comunidades autónomas, no realiza las pruebas de cribado, que se llevan a cabo en los servicios asistenciales, ni tiene como objetivo desarrollar estrategias educativas dirigidas a la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f63") }, {"long_answer": "En el cribado de cáncer colorrectal, se clasifica como adenoma de riesgo medio la presencia de al menos un adenoma de entre 10 y 20 mm o de tres a cuatro adenomas de cualquier tamaño, hallazgos que se asocian a un riesgo intermedio de neoplasia avanzada y condicionan el seguimiento endoscópico posterior. Uno o dos adenomas menores de 10 mm corresponden a la categoría de bajo riesgo. Un pólipo serrado menor de 10 mm sin displasia y un pólipo hiperplásico de recto-sigma sin displasia no se consideran lesiones de riesgo medio.", "question": "En el cribado de cáncer colorrectal, ¿qué hallazgo se considera un adenoma de riesgo medio?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f68") }, {"long_answer": "En el programa de cribado de cáncer de cérvix, la citología es la prueba primaria en las mujeres de 25 a 29 años, con una periodicidad de tres años, ya que en estas edades las infecciones por VPH son muy frecuentes y transitorias y la determinación del virus generaría un exceso de resultados positivos. A partir de los 30 años y hasta los 65 la prueba primaria es la determinación de VPH de alto riesgo cada cinco años. El cribado no se inicia a los 50 años y no se mantiene de forma rutinaria más allá de los 65 años en mujeres con cribado previo adecuado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f6b") }, {"long_answer": "En el cribado de cáncer de cérvix, la reevaluación temprana es una prueba que se realiza de forma precoz, antes de la siguiente ronda de cribado, cuando la prueba primaria o la prueba de triaje muestran resultados alterados que no requieren derivación inmediata a colposcopia, siguiendo el intervalo establecido en el protocolo. No se trata de una prueba realizada al menos cinco años después, que corresponde al intervalo habitual de cribado, ni de la invitación ordinaria a la siguiente ronda, ni de la primera prueba realizada a una mujer sin cribado previo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f6d") }, {"long_answer": "El programa de cribado poblacional de cáncer colorrectal utiliza como prueba principal el test de sangre oculta en heces inmunológico cuantitativo, realizado cada dos años en personas de 50 a 69 años. Si el resultado es positivo, se realiza una colonoscopia de confirmación. La colonoscopia directa anual no es la prueba de cribado poblacional por su carácter invasivo y su coste, las pruebas genéticas se reservan para sospecha de síndromes hereditarios como la poliposis adenomatosa familiar, y las pruebas de imagen abdominal semestrales no forman parte del cribado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f72") }, {"long_answer": "En la clasificación TNM del cáncer colorrectal, la categoría T4 corresponde a tumores que atraviesan toda la pared intestinal; dentro de ella, T4b indica que el tumor invade o se adhiere directamente a otros órganos o estructuras adyacentes, mientras que T4a indica afectación del peritoneo visceral. Un tumor limitado a la mucosa corresponde a Tis, si alcanza la submucosa se clasifica como T1, y la categoría de tumor primario no evaluable se denomina TX, por lo que ninguna de esas opciones describe T4b."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f73") }, {"long_answer": "En la clasificación TNM del cáncer de mama adaptada de la AJCC, la categoría Tis(DCIS) corresponde al carcinoma ductal in situ, un carcinoma no invasivo en el que las células tumorales no han atravesado la membrana basal de los conductos. Un tumor primario no evaluable se clasifica como TX, la afectación ganglionar sin tumor primario detectable se clasifica como T0 con la categoría N correspondiente, y un tumor de cualquier tamaño con extensión a la piel se clasifica como T4, por lo que ninguna de estas descripciones se corresponde con Tis(DCIS)."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f78") }, {"long_answer": "En el cribado de cáncer de mama, una prueba no valorable es aquella que debe repetirse porque su resultado no permite una interpretación adecuada, ya sea por calidad insuficiente de la imagen o por errores técnicos en su realización. La prueba cuyo resultado requiere estudios adicionales para aclarar un hallazgo es una prueba positiva o con necesidad de valoración adicional, la que no detecta anomalías es una prueba negativa y la que confirma un tumor maligno corresponde a un diagnóstico de cáncer, no a una prueba no valorable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f79") }, {"long_answer": "En los indicadores del cribado de cáncer colorrectal del SICC, la edad de las personas de la cohorte de examen se calcula a la fecha de entrega de la prueba de cribado, es decir, del test de sangre oculta en heces, ya que es el momento en el que la persona participa efectivamente en el programa. La edad a la fecha de invitación se emplea para la población invitada, no para la población examinada. Calcularla a final del año natural o en el momento del diagnóstico introduciría desfases que dificultarían la comparación de indicadores entre programas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f7f") }, {"long_answer": "En adolescentes con infección por VIH se recomienda la vacunación frente al virus del papiloma humano con tres dosis en pauta 0, 1-2 y al menos 6 meses, independientemente de la edad de inicio, porque la inmunodepresión reduce la respuesta inmunitaria y aumenta el riesgo de lesiones persistentes y de cáncer asociado al VPH. La dosis única se aplica en población general sin inmunodepresión, dos dosis separadas cuatro semanas no constituyen una pauta válida, y la infección por VIH no contraindica esta vacuna, que es inactivada, sino que la hace especialmente recomendable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f80") }, {"long_answer": "En los niños prematuros clínicamente estables, la vacuna frente a rotavirus está recomendada a partir de las 6 semanas de vida, según la edad cronológica y la ficha técnica de la vacuna utilizada, ya que la prematuridad aumenta el riesgo de gastroenteritis grave por rotavirus. La pauta consta de varias dosis orales, no de una dosis única al mes de vida. La prematuridad no contraindica la vacunación, y retrasar el inicio hasta las 12 semanas acortaría el margen disponible para completar la pauta, que tiene edades máximas de administración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f83") }, {"long_answer": "En adolescentes con enfermedad renal crónica avanzada y en hemodiálisis se recomienda la vacuna frente a la hepatitis B de alta carga antigénica, de 20 µg en 0,5 ml, o una vacuna específica para pacientes en diálisis, ya que estos pacientes tienen una respuesta inmunitaria disminuida y un mayor riesgo de exposición al virus. Además, se recomienda comprobar la respuesta mediante serología posvacunal. La vacuna estándar infantil es insuficiente en este contexto, la hemodiálisis no contraindica la vacunación sino que la indica, y una pauta de dos dosis en 0 y 12 meses no es la recomendada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f86") }, {"long_answer": "En adolescentes con infección por VIH susceptibles a la varicela se recomienda la vacunación, salvo cuando presentan inmunodepresión grave según el recuento o porcentaje de linfocitos CD4 correspondiente a su edad, ya que en esas situaciones la vacuna atenuada está contraindicada. Si la situación inmunológica lo permite, se administran dos dosis. No es correcto decir que la vacunación esté contraindicada sin excepciones, una sola dosis sin seguimiento no completa la pauta y no se vacuna a quien ya ha pasado la varicela, puesto que ya es inmune."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f89") }, {"long_answer": "En un niño con antecedente de enfermedad meningocócica invasiva, aunque no tenga otras condiciones de riesgo, se recomienda la vacunación tanto con MenACWY como con MenB, siguiendo la pauta correspondiente a su edad, porque haber padecido la enfermedad no garantiza protección frente a otros serogrupos y puede indicar una susceptibilidad subyacente. Administrar únicamente MenC deja sin cubrir los serogrupos A, W, Y y B. Tampoco es correcto que la vacunación no esté recomendada, y una única dosis de MenB sin el resto de la pauta ni la vacuna MenACWY resulta insuficiente.", "option_1": "MenACWY y MenB, con la pauta correspondiente a la edad", "option_2": "Únicamente MenC conjugada en dosis única"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f8a") }, {"long_answer": "En los adolescentes varones que tienen relaciones sexuales con hombres, el documento de vacunación en grupos de riesgo recomienda la vacunación frente al virus del papiloma humano con pauta de una dosis única, en consonancia con la actualización del calendario que adoptó la dosis única en personas inmunocompetentes, dada la alta protección que confiere. La pauta de tres dosis se reserva para personas con inmunodepresión, como la infección por VIH. La vacunación sí está recomendada en hombres, especialmente en este grupo, y la pauta de dos dosis separadas seis meses no es la indicada actualmente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f8e") }, {"long_answer": "En menores con enfermedad cardiovascular crónica, la vacunación frente al neumococo debe valorarse con una pauta secuencial, combinando vacunas conjugadas y, en su caso, polisacárida, adaptada a la patología concreta, la edad y las vacunas disponibles, ya que estos niños tienen mayor riesgo de enfermedad neumocócica grave. Administrar una dosis única sin tener en cuenta la patología ignora la necesidad de individualizar. La enfermedad cardiovascular no contraindica la vacunación, sino que la indica, y su administración no depende de que exista una infección concomitante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f92") }, {"long_answer": "En menores con infección por VIH que no han completado la vacunación frente a Haemophilus influenzae tipo b, se recomienda una dosis de vacuna conjugada Hib para asegurar la protección frente a la enfermedad invasiva, a la que son más vulnerables por su inmunodepresión. La vacuna frente a Hib es conjugada e inyectable, por lo que no existe una presentación oral administrada cada tres meses. Una pauta de tres dosis de vacuna inactivada no corresponde a esta recomendación y la infección por VIH no contraindica esta vacuna, que es inactivada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f93") }, {"long_answer": "La vacunación frente a sarampión, rubeola y parotiditis está contraindicada en menores con inmunodepresión grave, ya que la triple vírica es una vacuna de virus vivos atenuados que puede causar enfermedad vacunal diseminada en estos pacientes. La enfermedad renal crónica leve y la asplenia sin disfunción inmune no contraindican esta vacuna, y en estos niños se recomienda completar el calendario. En los adolescentes ya vacunados con pauta completa no hay contraindicación, simplemente no es necesario administrar más dosis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f98") }, {"long_answer": "En los lactantes prematuros nacidos entre las semanas 25-27, según la vacuna, y la 32 de gestación que están clínicamente estables, se recomienda la vacunación frente a rotavirus a partir de las 6 semanas de vida, siguiendo las pautas autorizadas en la ficha técnica y teniendo en cuenta la edad cronológica, ya que este grupo presenta mayor riesgo de gastroenteritis grave. No se vacuna desde las 2 semanas de vida, la prematuridad no contraindica la vacunación antes de las 35 semanas de edad gestacional y la vacuna no se administra como dosis única al nacimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f9f") }, {"long_answer": "En las personas con condiciones de riesgo para la hepatitis B se recomienda realizar marcadores serológicos, como anti-HBc, anti-HBs y AgHBs, antes de vacunar para conocer su estado inmunológico previo: permiten identificar a quienes ya están infectados o son inmunes por infección pasada y no necesitan la vacuna, y a quienes son susceptibles y deben vacunarse. Estos marcadores no aportan información sobre la idoneidad de la vacuna de varicela, no determinan la coadministración con la vacuna de hepatitis A y el tabaquismo no es motivo para evitar la vacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa1") }, {"long_answer": "En adultos con infección por VIH se recomienda la vacuna meningocócica conjugada tetravalente MenACWY, ya que la infección por VIH aumenta el riesgo de enfermedad meningocócica invasiva por estos serogrupos. La vacuna MenB no se indica de forma sistemática por la infección por VIH, sino cuando coexisten otras condiciones como asplenia o déficit del complemento, por lo que no se administran ambas de forma rutinaria. La infección por VIH no contraindica la vacunación meningocócica, ya que se trata de vacunas inactivadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa2") }, {"long_answer": "Para prevenir el herpes zóster en personas con hemopatías malignas se recomienda la vacuna de subunidades adyuvada (HZ/su), que no contiene virus vivos y puede administrarse en inmunodeprimidos, con una pauta de dos dosis separadas por un intervalo mínimo de cuatro semanas en este grupo. La vacuna de virus vivo atenuado está contraindicada en pacientes inmunodeprimidos por el riesgo de diseminación del virus vacunal. No existe una vacuna inactivada de tres dosis frente al zóster, y la vacunación sí está recomendada en estas personas por su alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa3") }, {"long_answer": "La vacuna de la varicela es de virus vivos atenuados, por lo que está contraindicada en el embarazo, en las inmunodeficiencias graves y en la infección por VIH con recuento de linfocitos CD4 inferior a 200/µl, situaciones en las que existe riesgo de enfermedad vacunal. La edad superior a 65 años no es una contraindicación por sí misma, aunque a esa edad la mayoría ya es inmune. Haber recibido dos dosis significa que la vacunación está completa, no que exista contraindicación, y la enfermedad renal crónica no contraindica la vacuna, siendo incluso un grupo en el que se recomienda en susceptibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fba") }, {"long_answer": "Las personas con síndrome de Down se incluyen entre los grupos de riesgo en los que se recomienda la vacunación frente a la hepatitis B siguiendo las pautas específicas establecidas para estos grupos, por su mayor riesgo de exposición en entornos de convivencia y la posible menor respuesta inmunitaria. No tienen inmunidad natural frente al virus que haga innecesaria la vacunación. La indicación no depende de que exista una enfermedad renal concomitante, y la serología puede ayudar a conocer el estado inmunitario, pero no sustituye a la vacunación en las personas susceptibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fbd") }, {"long_answer": "En las personas sin documentación vacunal o con historial incompleto, el calendario acelerado prioriza la vacunación frente a sarampión, rubeola, poliomielitis, tétanos y difteria, por tratarse de enfermedades graves, prevenibles y sujetas a objetivos de eliminación o control, y porque su protección se puede conseguir con pautas rápidas y seguras. Limitarse a infecciones emergentes deja sin cubrir estas enfermedades prioritarias. La vacunación de rescate se aplica tanto a niños como a adultos, y no depende de la presencia de síntomas, ya que su objetivo es preventivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc0") }, {"long_answer": "En menores de 7 años con pauta incompleta pueden utilizarse las vacunas hexavalentes disponibles, que protegen frente a difteria, tétanos, tosferina, poliomielitis, Haemophilus influenzae tipo b y hepatitis B, sin problemas de seguridad ni de eficacia, lo que facilita completar la inmunización con menos inyecciones. No es cierto que deban evitarse en este grupo con vacunaciones incompletas, el problema de varias dosis en un mismo día no se plantea porque se administra una sola dosis de hexavalente por visita junto con otras vacunas distintas, y pueden usarse tanto en primovacunación como en dosis de recuerdo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fda") }, {"long_answer": "El poliovirus se transmite principalmente por vía fecal-oral, a través del contacto con heces de personas infectadas o del consumo de agua y alimentos contaminados, y en menor medida por vía respiratoria en las fases iniciales de la infección. Esta vía explica la importancia del saneamiento, de la vacunación con altas coberturas y de la vigilancia ambiental de aguas residuales. El poliovirus no se transmite por vía sexual, no necesita vectores artrópodos y el ser humano es su único reservorio, por lo que no existe transmisión a partir de animales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fdb") }, {"long_answer": "Según el Plan de acción para la erradicación de la poliomielitis, la tasa de transmisión secundaria del poliovirus entre contactos susceptibles se estima entre el 73 % y el 96 %, lo que refleja la elevada contagiosidad del virus, especialmente en el entorno doméstico y en zonas con condiciones higiénicas deficientes. Esta alta transmisibilidad justifica la necesidad de mantener coberturas vacunales iguales o superiores al 95 % para evitar bolsas de población susceptible. Los rangos del 10-20 %, 25-50 % y 40-60 % infraestiman claramente la capacidad de transmisión del poliovirus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe3") }, {"long_answer": "En personas inmunocompetentes, el poliovirus se excreta habitualmente en las heces durante unas cuatro semanas desde el inicio de los síntomas, pudiendo prolongarse hasta seis semanas, mientras que la excreción faríngea es más breve, de una a dos semanas. Esto tiene implicaciones para la toma de muestras y las medidas de control. Los periodos de 7 a 14 días o de dos semanas corresponden más bien a la excreción faríngea, y la excreción durante más de cinco años es propia de algunos pacientes con inmunodeficiencias primarias, no de personas inmunocompetentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe6") }, {"long_answer": "El Laboratorio Nacional de Polio sigue el algoritmo recomendado por la OMS: aislamiento del virus en cultivo celular utilizando las líneas RD y L20B, esta última sensible de forma específica al poliovirus, seguido de la diferenciación intratípica (ITD) mediante técnicas moleculares para distinguir entre poliovirus salvaje, vacunal o derivado de la vacuna. El cultivo en células HEp-2 con detección serológica no es el algoritmo de referencia, la PCR convencional sin cultivo no sustituye al protocolo completo y la microscopía electrónica no permite caracterizar el virus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977feb") }, {"long_answer": "La principal prioridad del Plan de Acción en España para la Erradicación de la Poliomielitis 2024-2028 es mantener coberturas de vacunación iguales o superiores al 95 % a nivel nacional y evitar bolsas de población susceptible, que serían el punto débil ante una posible importación del virus. España utiliza la vacuna inactivada desde 2004, por lo que aumentar la vacunación con vacuna oral no es un objetivo, dado el riesgo de poliovirus derivados de la vacuna. Disminuir la vigilancia o invertir solo en laboratorio sin acciones comunitarias contradice los compromisos de la OMS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fed") }, {"long_answer": "Para evaluar la calidad de la vigilancia de la parálisis flácida aguda, la OMS utiliza el Índice de Vigilancia, que combina la tasa de notificación de casos de PFA no polio con la proporción de casos con muestras adecuadas de heces; se considera que la vigilancia es de calidad cuando este índice alcanza al menos 0,8, equivalente al 80 %. Valores de 0,5 o 0,65 indican una vigilancia insuficiente para detectar con fiabilidad la circulación del poliovirus, mientras que 0,95 supera el umbral establecido como referencia por la OMS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fef") }, {"long_answer": "En las personas con excreción prolongada de poliovirus, el plan recomienda recoger muestras de heces con frecuencia semanal al inicio del seguimiento y pasar a una frecuencia mensual si la excreción se prolonga más de ocho semanas o si se trata de una persona con inmunodeficiencia primaria (TIP), en las que la excreción puede mantenerse durante largos periodos. Mantener muestras semanales sin excepción supondría una carga innecesaria, una única muestra no permite conocer la duración de la excreción ni confirmar su cese, y un muestreo mensual desde el inicio sería insuficiente en las primeras semanas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff0") }, {"long_answer": "El Plan de acción para la erradicación de la poliomielitis en España es coordinado y aprobado por la Comisión de Salud Pública del Consejo Interterritorial del Sistema Nacional de Salud, órgano en el que participan el Ministerio de Sanidad y las comunidades autónomas para acordar las actuaciones de salud pública. La OMS y la Asamblea Mundial de la Salud establecen la estrategia mundial de erradicación y evalúan a los países, pero no aprueban los planes nacionales, y el Ministerio de Ciencia e Innovación no tiene competencias en la coordinación de este plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff4") }, {"long_answer": "La pandemia de COVID-19 afectó a las coberturas de vacunación frente a la poliomielitis en España, con una disminución especialmente marcada en la primera dosis de recuerdo, como consecuencia de la reorganización de los servicios sanitarios y de la menor asistencia a los centros. Posteriormente se realizaron actividades de captación activa para recuperar a los niños con vacunaciones pendientes. No es cierto que no hubiera impacto, no se produjo un incremento de la vacunación durante la pandemia y la vacunación no se suspendió por completo, ya que se consideró un servicio esencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff8") }, {"long_answer": "Desde 2016, las muestras positivas o potencialmente infecciosas para poliovirus en España deben eliminarse siguiendo la guía de la OMS para minimizar el riesgo de liberación del virus desde los laboratorios, y los centros deben certificar al Laboratorio Nacional de Polio que la eliminación se ha realizado correctamente. Almacenarlas de forma indefinida incumpliría los requisitos de contención. Enviarlas a laboratorios extranjeros o distribuirlas para investigación sin límites tampoco es aceptable, ya que solo pueden conservarse en instalaciones esenciales certificadas para ello."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff9") }, {"long_answer": "Tras activarse por la detección de un poliovirus vacunal tipo 1 o tipo 3, el Grupo de Apoyo Técnico evalúa el riesgo de la situación, define el área de riesgo, propone las actuaciones de respuesta necesarias, como intensificar la vigilancia o la vacunación, y colabora con la comunidad autónoma afectada en su puesta en marcha. No declara el fin del evento de forma inmediata, ya que para ello se exige un periodo sin nuevas detecciones. Tampoco se limita a lanzar campañas de vacunación masiva sin análisis previo, ni espera a recibir un informe internacional antes de actuar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ffe") }, {"long_answer": "El Real Decreto 954/2015 establece que, para que las enfermeras puedan indicar, usar y autorizar la dispensación de medicamentos sujetos a prescripción médica, deben existir protocolos o guías de práctica clínica y asistencial elaborados en el seno de la Comisión Permanente de Farmacia y validados por la Dirección General de Salud Pública, actualmente de Salud Pública y Equidad en Salud. La actuación enfermera no se basa en recetas médicas emitidas por especialistas, los protocolos domiciliarios elaborados por auxiliares no tienen validez para este fin y las publicaciones científicas internacionales no constituyen por sí mismas un marco validado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fff") }, {"long_answer": "La aplicación de la guía de anestésicos locales pretende optimizar competencias enfermeras como la educación al paciente sobre el procedimiento y sus cuidados, el seguimiento del tratamiento y la detección precoz de efectos adversos, en el marco de un trabajo colaborativo con el resto del equipo. La guía no autoriza a prescribir sin supervisión ni fuera de los supuestos que define, sino que acota la indicación enfermera a protocolos validados. Tampoco persigue la realización exclusiva de procedimientos invasivos complejos ni se orienta a la gestión administrativa hospitalaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978004") }, {"long_answer": "La guía recomienda que los protocolos que adapten las comunidades autónomas incluyan, como mínimo, la población objetivo, los medicamentos autorizados para la indicación enfermera, el tipo de intervenciones que puede realizar la enfermera, los parámetros que puede ajustar y los criterios de reevaluación o derivación al médico. Estos elementos garantizan una actuación segura y homogénea. Incluir los nombres de los médicos especialistas del hospital no forma parte del contenido mínimo, las listas de productos de libre dispensación sin control contradicen el objetivo de la guía y los descuentos en medicamentos son ajenos a su ámbito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978008") }, {"long_answer": "La guía de anestésicos locales excluye de la indicación enfermera los apósitos o parches de lidocaína destinados al tratamiento del dolor neuropático periférico asociado a la infección por herpes zóster, es decir, la neuralgia postherpética, porque se trata de un tratamiento de un cuadro de dolor crónico que requiere diagnóstico y seguimiento médico, y no de una anestesia local para un procedimiento. La bupivacaína, la mepivacaína y la tetracaína mencionadas en las demás opciones no se presentan en forma de parche, por lo que no corresponden a la exclusión que recoge la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978009") }, {"long_answer": "La bupivacaína es un anestésico local de tipo amida, grupo al que pertenecen también la lidocaína, la mepivacaína y la ropivacaína. Los anestésicos tipo amida se metabolizan en el hígado y producen reacciones alérgicas con muy poca frecuencia. La cloroprocaína y la procaína son anestésicos de tipo éster, que se hidrolizan por las colinesterasas plasmáticas y se asocian a más reacciones alérgicas por su metabolito, el ácido paraaminobenzoico. La cocaína también es un éster y no figura entre los anestésicos autorizados para la indicación enfermera."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97800d") }, {"long_answer": "Según la guía, el ámbito de actuación enfermera en la administración de anestésicos locales comprende procedimientos diagnósticos o terapéuticos asociados a dolor y procedimientos de cirugía menor, tanto urgentes como programados, como suturas, curas dolorosas, canalizaciones o infiltraciones superficiales. La cirugía mayor con anestesia general o sedación profunda queda fuera de este ámbito y requiere la intervención de anestesiología. Los tratamientos psicológicos no guardan relación con los anestésicos locales y las endoscopias no forman parte de los procedimientos recogidos en la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978016") }, {"long_answer": "La guía establece que la coordinación entre las enfermeras y el resto de profesionales en el uso de anestésicos locales debe garantizar un seguimiento protocolizado del paciente y la reducción de complicaciones, compartiendo información y criterios de derivación ante cualquier incidencia. Los informes médicos aislados sin implicación enfermera contradicen el enfoque colaborativo de la guía. Administrar el anestésico sin seguimiento posterior compromete la seguridad del paciente, y el uso exclusivo de terapias alternativas no tiene relación con el objetivo de la coordinación descrita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97801e") }, {"long_answer": "En las infecciones urinarias no complicadas de mujeres adultas, la guía indica que no es necesario realizar urocultivo de forma rutinaria en la mayoría de los casos, ya que el diagnóstico se basa en la clínica típica y, en su caso, en la tira reactiva, y el tratamiento empírico es eficaz frente a los patógenos habituales, principalmente Escherichia coli. El urocultivo se reserva para situaciones como sospecha de infección complicada, recurrencias, fracaso terapéutico o embarazo. Por ello no se realiza siempre antes de tratar, y la fiebre sugiere afectación del tracto superior, que queda fuera del ámbito de la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97801f") }, {"long_answer": "Una infección urinaria se considera complicada cuando existen factores que aumentan el riesgo de afectación del parénquima renal o de fracaso terapéutico, como alteraciones estructurales o funcionales de la vía urinaria, embarazo, sexo masculino, inmunodepresión, sondaje o síntomas de pielonefritis. Por el contrario, una infección con síntomas leves y sin complicaciones previas es no complicada. Ser mujer mayor de 50 años sin otras patologías no convierte la infección en complicada, y la polaquiuria sin dolor suprapúbico es un síntoma típico de cistitis no complicada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978020") }, {"long_answer": "Las mujeres embarazadas con infección urinaria no se incluyen en la población diana de la guía para la indicación enfermera, porque la infección urinaria en el embarazo se considera complicada, requiere urocultivo y seguimiento médico y obstétrico, y limita la elección de antibióticos. La guía se dirige a mujeres mayores de 14 años con infección urinaria no complicada, como las que presentan cistitis sin factores de riesgo o disuria y urgencia miccional sin antecedentes de complicaciones, situaciones en las que el tratamiento empírico protocolizado es seguro y eficaz."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978023") }, {"long_answer": "La fosfomicina trometamol en dosis única de 3 g es el antibiótico de primera elección en el tratamiento empírico de la infección urinaria no complicada según la guía, por su eficacia frente a Escherichia coli, las bajas tasas de resistencia en nuestro medio, la comodidad de su pauta y su buen perfil de seguridad. La nitrofurantoína es una alternativa válida, pero no la primera elección en esta guía. La amoxicilina con ácido clavulánico y el ciprofloxacino no se recomiendan como tratamiento empírico inicial por las tasas de resistencia y por el impacto ecológico de su uso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978027") }, {"long_answer": "Según la guía, la infección urinaria recurrente se define como la aparición de dos o más episodios en un periodo de seis meses, o de tres o más episodios en un año. Esta definición identifica a las pacientes que requieren urocultivo, estudio y un abordaje específico, en general fuera de la indicación enfermera protocolizada. Un único episodio en el último año no constituye recurrencia, la persistencia de síntomas durante más de siete días orienta a fracaso terapéutico o a infección complicada, y la infección tras un tratamiento antibiótico no define por sí misma la recurrencia.", "option_1": "Dos o más episodios en 6 meses, o tres o más en un año"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97802f") }, {"long_answer": "De acuerdo con la guía y con el Real Decreto 954/2015, la autorización de dispensación de medicamentos por parte de la enfermera acreditada se realiza mediante la correspondiente orden de dispensación, que es el documento normalizado que permite al farmacéutico dispensar el medicamento indicado. No se requiere una receta médica tradicional, ya que la indicación la realiza la enfermera dentro del marco del protocolo. La indicación verbal carece de validez para autorizar la dispensación, y los farmacéuticos no emiten prescripciones, por lo que la última opción tampoco es correcta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978030") }, {"long_answer": "Escherichia coli es el microorganismo causante más frecuente de la infección urinaria no complicada en mujeres adultas, responsable de alrededor del 70-80 % de los casos, seguido a distancia por otros gérmenes como Staphylococcus saprophyticus, Klebsiella o Proteus. Por eso el tratamiento empírico se elige teniendo en cuenta su patrón de sensibilidad. Staphylococcus aureus es un agente poco habitual en la cistitis no complicada, Klebsiella pneumoniae causa una proporción menor de casos y Pseudomonas aeruginosa se asocia sobre todo a infecciones complicadas, sondaje o ámbito hospitalario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978033") }, {"long_answer": "La guía justifica la implementación del tratamiento empírico precoz en la infección urinaria no complicada por su alta prevalencia, la sólida evidencia científica que respalda la eficacia y seguridad de este enfoque y el beneficio que aporta en atención primaria, ya que permite resolver los síntomas con rapidez y mejorar la accesibilidad. No se fundamenta en la incertidumbre del diagnóstico microbiológico, ya que el diagnóstico clínico es fiable en este contexto. El objetivo no es prevenir infecciones complicadas en la población general ni reducir el uso de medidas no farmacológicas, que se siguen recomendando."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978034") }, {"long_answer": "La revisión periódica de la guía, como mínimo cada cinco años, permite incorporar la nueva evidencia científica, los cambios en los patrones de resistencia antimicrobiana, las actualizaciones terapéuticas y las modificaciones normativas, de modo que las recomendaciones sigan siendo seguras y eficaces. No se trata de introducir cambios puramente administrativos sin revisión clínica, ni de eliminar fármacos por motivos de financiación sin análisis de su utilidad, y la actualización no depende de la existencia de reclamaciones legales, sino del avance del conocimiento científico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978038") }, {"long_answer": "La indicación, uso y autorización de dispensación de medicamentos por enfermeras en España se regula en el Real Decreto 954/2015, modificado por el Real Decreto 1302/2018, que establece los requisitos de acreditación, el marco de los protocolos y guías de práctica clínica y el modelo de orden de dispensación. La Ley General de Sanidad de 1986 es la norma marco del Sistema Nacional de Salud, pero no regula esta facultad. No existe una ley de ordenación sanitaria del año 2000 que la regule, y el Código Deontológico orienta la conducta ética pero no tiene rango normativo para habilitar la dispensación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978039") }, {"long_answer": "Las actuaciones enfermeras recogidas en la guía de infección urinaria no complicada tienen como objetivos la educación sanitaria de la paciente, el fomento de la adherencia terapéutica, la detección de efectos adversos, el seguimiento de la evolución y la mejora de la accesibilidad a la atención. No se limitan a la administración puntual de un fármaco, ya que incluyen una valoración y un seguimiento integrales. La derivación inmediata al hospital solo procede ante signos de complicación, y el urocultivo no se realiza de forma rutinaria en la infección no complicada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97803f") }, {"long_answer": "En el ámbito de las Fuerzas Armadas, la enfermera o el enfermero puede consignar en la orden de dispensación el número de su Tarjeta Militar de Identidad en lugar del número de colegiación, ya que este código permite identificarle profesionalmente dentro de la sanidad militar, donde la acreditación corresponde al Ministerio de Defensa. El número de identificación fiscal y el pasaporte son documentos de identificación personal que no acreditan la condición profesional, y el número de expediente clínico corresponde al paciente, no al profesional que emite la orden."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978049") }, {"long_answer": "El procedimiento para la acreditación de las enfermeras para indicar, usar y autorizar la dispensación de medicamentos lo regulan las comunidades autónomas en el ámbito de sus competencias, ya que son ellas las que otorgan la acreditación a los profesionales de su territorio, salvo en las Fuerzas Armadas, donde corresponde al Ministerio de Defensa. El Ministerio de Sanidad fija los requisitos básicos en el Real Decreto, pero no aprueba un reglamento único de procedimiento. La Comisión Permanente de Farmacia se ocupa de los protocolos y guías, y el Consejo General de Enfermería no tiene atribuida esta función."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978051") }, {"long_answer": "El Real Decreto 1302/2018, que modifica el Real Decreto 954/2015, entró en vigor el día siguiente al de su publicación en el Boletín Oficial del Estado, según establece su disposición final. Esta entrada en vigor inmediata se debió a la necesidad de desbloquear la aplicación de la indicación enfermera tras la controversia generada por la redacción original de la norma. No se estableció un periodo de seis meses ni de un año de vacatio legis, y la entrada en vigor no coincidió con el mismo día de la publicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978054") }, {"long_answer": "La norma prevé que, de forma excepcional, los protocolos y guías de práctica clínica y asistencial puedan exigir a las enfermeras una formación complementaria cuando se trate de medicamentos de especial complejidad, para garantizar la seguridad en su indicación. No se exige una formación universitaria reglada obligatoria para todas las enfermeras, ya que la acreditación se basa en la titulación y la experiencia o en un curso de adaptación. La formación en habilidades administrativas no responde a este objetivo, y no se establecen cursos de actualización bianuales obligatorios para todo el colectivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978058") }, {"long_answer": "La regulación se justifica conforme a los principios de buena regulación del artículo 129 de la Ley 39/2015, del Procedimiento Administrativo Común, entre los que se encuentran la necesidad, la eficacia, la proporcionalidad, la seguridad jurídica, la transparencia y la eficiencia; este último implica evitar cargas administrativas innecesarias y simplificar los procedimientos. Los principios de legalidad y jerarquía normativa son principios constitucionales generales, no los que enumera este artículo. La igualdad en el acceso a medicamentos y la confidencialidad de los datos no forman parte de los principios de buena regulación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771df") }, {"long_answer": "Las recomendaciones de salud y seguridad vial para la embarazada aconsejan caminar a diario como actividad física segura, pero eligiendo entornos tranquilos y evitando las aglomeraciones, donde aumenta el riesgo de empujones, golpes en el abdomen y caídas, que pueden comprometer el bienestar materno-fetal. Por ello la respuesta correcta es evitar las aglomeraciones. Las zonas verdes, al contrario, son espacios recomendables para pasear. Cruzar por cualquier lugar en vez de hacerlo por pasos señalizados incrementa el riesgo de atropello, y el calzado debe ser cómodo, estable y antideslizante, nunca inadecuado, para prevenir caídas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771e0") }, {"option_1": "Pedalear muy rápido", "long_answer": "Durante el embarazo la bicicleta puede mantenerse con precaución si la mujer ya la practicaba, y una de las medidas básicas es elegir una bicicleta adecuada, cómoda, con manillar alto que permita una postura erguida y un sillín confortable, para mantener el equilibrio y reducir el riesgo de caídas y traumatismos abdominales. Pedalear muy rápido aumenta el riesgo de pérdida de control y de lesiones. Ir en línea recta no es en sí una medida preventiva específica, y no planificar la ruta impide elegir trayectos seguros, con poco tráfico y sin desniveles bruscos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ec") }, {"option_2": "La supresión de la coordinación entre las comunidades autónomas", "long_answer": "La Comisión frente a la violencia en los niños, niñas y adolescentes (CoViNNA), creada en el seno del Consejo Interterritorial del SNS en desarrollo de la Ley Orgánica 8/2021 (LOPIVI), tiene como uno de sus primeros cometidos la elaboración de un Protocolo común de actuación sanitaria que evalúe y proponga las medidas necesarias para la correcta aplicación de la ley en el ámbito sanitario. La CoViNNA no suprime la coordinación entre comunidades autónomas, sino que la favorece. El acceso universal a servicios de tratamiento y la promoción del buen trato son principios y objetivos del abordaje de la violencia, no lo que implica en sí la constitución de la comisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771f7") }, {"long_answer": "El alcohol y otras drogas alteran el funcionamiento del sistema nervioso central y producen euforia, desinhibición y falsa sensación de seguridad, lo que se traduce en un comportamiento imprudente al volante, como exceso de velocidad o maniobras arriesgadas, y aumenta el riesgo de siniestros. Por eso la respuesta correcta es el comportamiento imprudente. Las demás opciones son falsas: estas sustancias disminuyen la capacidad de atención, empeoran la coordinación psicomotora y alargan el tiempo de reacción, no lo acortan, de modo que el conductor tarda más en responder ante cualquier imprevisto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771fa") }, {"long_answer": "En ciclomotores y motocicletas el pasajero debe avisar al conductor antes de subir y antes de bajar, y hacerlo solo cuando este lo autorice, ya que el movimiento brusco del acompañante desequilibra el vehículo y puede provocar una caída. Además, debe sujetarse bien, llevar casco homologado y acompañar los movimientos del conductor en las curvas. No es cierto que el pasajero no tenga ninguna responsabilidad ni que el conductor deba encargarse de todo. Tampoco tiene sentido no subir nunca a la moto ni solicitar ayuda a peatones, que no garantiza la estabilidad del vehículo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771fb") }, {"long_answer": "El permiso A2, que habilita para conducir motocicletas con una potencia máxima de 35 kW y una relación potencia/peso no superior a 0,2 kW/kg, puede obtenerse a partir de los 18 años. Por ello la respuesta correcta es 18 años. A los 15 años solo se puede obtener la licencia o permiso AM para ciclomotores, y a los 16 años el permiso A1, que permite motocicletas de hasta 125 cc y 11 kW. Los 21 años no corresponden al A2, sino a la posibilidad de acceder al permiso A tras dos años de experiencia con el A2."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977205") }, {"long_answer": "Al desplazarse con un carrito de bebé, se recomienda cruzar siempre por los pasos de peatones señalizados, respetando los semáforos y asegurándose de que los vehículos se han detenido antes de iniciar el cruce, sin adelantar el carrito sobre la calzada mientras se espera. Esta conducta hace a los peatones más visibles y previsibles para los conductores. Cruzar por cualquier punto, hacerlo en la zona más transitada o correr para cruzar rápido aumenta el riesgo de atropello y de caídas o vuelcos del carrito, por lo que son conductas que deben evitarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977208") }, {"long_answer": "En los taxis, la exención de llevar sistema de retención infantil solo se aplica en vías urbanas; fuera de la ciudad, el niño debe viajar en una silla o sistema de retención homologado y adecuado a su peso y talla, igual que en un vehículo particular. Por eso la respuesta correcta es la sillita adecuada a su peso y altura. No llevar ningún sistema es inseguro y no está permitido en vía interurbana. El cinturón de adulto por sí solo no protege correctamente a un niño de baja estatura, y una silla plegable no homologada no es un sistema de retención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97720a") }, {"long_answer": "En los vuelos comerciales, los menores de 2 años suelen viajar en el regazo del adulto sujetos con un cinturón supletorio o arnés que se engancha al cinturón de la persona adulta, que es la recomendación recogida por los materiales de seguridad infantil en los desplazamientos. Afirmar que no es necesario ningún sistema de retención es incorrecto, ya que las turbulencias pueden causar lesiones. El cinturón de seguridad del asiento, diseñado para adultos, no sujeta adecuadamente a un lactante, y la cuna se usa para dormir en vuelos largos, pero no sustituye a la sujeción durante el despegue, el aterrizaje o las turbulencias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97720b") }, {"long_answer": "El virus respiratorio sincitial (VRS) es el principal agente causal de las infecciones de vías respiratorias inferiores en menores de un año, responsable de la mayoría de las bronquiolitis y de una parte importante de las neumonías en lactantes, y la primera causa de hospitalización por enfermedad respiratoria en esta edad. Bronquiolitis y neumonía no son causas, sino cuadros clínicos que el propio VRS produce con frecuencia. La COVID-19 tiene en lactantes un impacto respiratorio inferior grave mucho menor que el VRS, por lo que no es la causa principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97720c") }, {"long_answer": "Nirsevimab (Beyfortus) es el primer anticuerpo monoclonal de vida media prolongada frente a la proteína F del VRS en su conformación de prefusión, con una modificación que permite proteger durante al menos cinco meses con una sola dosis intramuscular, y está indicado en recién nacidos y lactantes durante su primera temporada de VRS. Palivizumab (Synagis) es un anticuerpo de vida media corta que requiere dosis mensuales y se reserva a grupos de alto riesgo. RSVpreF (Abrysvo) y mRESVIA (mRNA-1345) son vacunas, no anticuerpos monoclonales; la primera se usa en embarazadas y adultos mayores, y la segunda en adultos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97720e") }, {"long_answer": "Las recomendaciones de utilización de nirsevimab para la temporada 2023-2024 se elaboraron tras el enorme pico epidémico de VRS de la temporada 2022-2023, ocurrido después de la alteración de la circulación del virus durante la pandemia de COVID-19, que causó una gran presión asistencial en las unidades pediátricas. A esto se sumó la disponibilidad de nirsevimab, autorizado en la Unión Europea. No hubo una disminución de casos, sino lo contrario. La vacuna RSVpreF no fue el motivo de estas recomendaciones, centradas en el anticuerpo, y palivizumab nunca se aprobó para cualquier recién nacido, sino solo para grupos de alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977215") }, {"option_1": "Aumento de las hospitalizaciones por VRS durante la pandemia", "option_2": "Descenso de las hospitalizaciones por VRS durante la pandemia", "option_3": "Desaparición definitiva de la estacionalidad del VRS", "option_4": "Ausencia de cambios en la circulación del VRS", "answer": 2, "long_answer": "Durante la pandemia de COVID-19, las medidas no farmacológicas como el confinamiento, la mascarilla, la distancia interpersonal y el cierre de escuelas redujeron drásticamente la circulación del VRS, con un descenso marcado de las hospitalizaciones por este virus en la temporada 2020-2021. Posteriormente, al relajarse las medidas, se observaron temporadas desplazadas y un gran repunte, con más hospitalizaciones y mayor edad de los niños afectados. Por tanto, no hubo un aumento durante la pandemia, no desapareció de forma definitiva la estacionalidad, que se recuperó en las temporadas siguientes, y sí se produjeron cambios evidentes en la circulación del virus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977217") }, {"option_1": "1,69-3,87", "option_2": "2,26", "option_3": "1,27-3,98", "option_4": "1,93", "long_answer": "Según los datos recogidos en el documento de recomendaciones sobre VRS, los prematuros nacidos con menos de 32 semanas de gestación presentan tasas de incidencia de infección de vías respiratorias inferiores por VRS y de hospitalización significativamente superiores a las de los nacidos a término, con razones de tasas que oscilan entre 1,69 y 3,87. Este exceso de riesgo se explica por la menor transferencia de anticuerpos maternos, la inmadurez inmunológica y pulmonar y la mayor frecuencia de comorbilidades. Las demás cifras no corresponden al intervalo descrito para este grupo en la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977218") }, {"option_1": "62,3%", "option_2": "76,4%", "option_3": "49,6%", "option_4": "85,2%", "long_answer": "El ensayo MELODY, realizado en lactantes sanos nacidos a término y prematuros tardíos de 35 semanas o más en su primera temporada de VRS, mostró con una única dosis de nirsevimab una eficacia del 76,4% frente a la infección de vías respiratorias inferiores por VRS atendida médicamente en el análisis de la cohorte completa, durante los 150 días posteriores a la administración. Las cifras del 62,3%, el 49,6% y el 85,2% no corresponden a este resultado principal. MELODY complementa al ensayo de fase IIb en prematuros de 29 a 35 semanas, con eficacia similar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977219") }, {"option_1": "Más del 75% de virus procedentes del grupo control", "option_2": "Más del 90% de virus procedentes del grupo control", "option_3": "Menos del 50% de virus procedentes del grupo control", "option_4": "Igual número de virus procedentes del grupo control y del grupo tratado", "long_answer": "En el estudio realizado en Francia tras la introducción de nirsevimab, la vigilancia virológica mostró que más del 75% de los virus analizados procedían de lactantes del grupo control, es decir, no inmunizados, lo que refleja que los niños que recibieron el anticuerpo se infectaron mucho menos y que la protección del producto es real en condiciones de uso. Las cifras de más del 90% o menos del 50% no son las descritas en el documento, y una proporción igual entre grupos indicaría ausencia de efecto protector, lo que no se observó."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97721d") }, {"long_answer": "En el ensayo de fase III de la vacuna materna RSVpreF (Abrysvo), administrada durante la gestación, la eficacia frente a la infección de vías respiratorias inferiores grave por VRS atendida médicamente en el lactante fue del 70,0% a los 180 días de vida, inferior a la observada en los primeros 90 días, en torno al 82%, lo que refleja el descenso progresivo de los anticuerpos transferidos por vía transplacentaria. Las cifras del 49,2% y del 57,6% se sitúan en el rango de la eficacia frente a la infección de vías respiratorias inferiores atendida médicamente de cualquier gravedad, y el 50,0% no corresponde a la forma grave a los 180 días."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977225") }, {"long_answer": "Según los estudios de efectividad incluidos en el documento, el número necesario a inmunizar (NNI) con nirsevimab para evitar una hospitalización por VRS en los menores inmunizados al nacimiento, durante su primera temporada, fue de 26, cifra que indica un elevado impacto poblacional del anticuerpo. Es menor que en los inmunizados en la campaña de rescate antes de la temporada, porque los recién nacidos en temporada son quienes tienen mayor riesgo de hospitalización. Las cifras de 34, 21 y 93 no corresponden a este grupo concreto en los datos de la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97722d") }, {"long_answer": "En la Comunidad Foral de Navarra, el estudio de efectividad de nirsevimab se realizó en los lactantes a los que se recomendó la inmunización por haber nacido durante la temporada, entre octubre de 2023 y enero de 2024, administrándose el anticuerpo poco después del nacimiento. Este estudio contribuyó a demostrar en condiciones reales una importante reducción de las hospitalizaciones por VRS. No se limitó a los nacidos en septiembre ni a cualquier mes del año, y sí existió una recomendación expresa de administración, enmarcada en la campaña nacional de inmunización frente al VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977231") }, {"option_4": "Tratamiento antiviral sistemático con ribavirina en todos los lactantes", "answer": 1, "long_answer": "En España, la estrategia recomendada por la Comisión de Salud Pública para prevenir la enfermedad por VRS en lactantes es la inmunización pasiva con el anticuerpo monoclonal nirsevimab, dirigida a todos los menores de seis meses al inicio o durante su primera temporada de VRS y a los niños con factores de riesgo en su segunda temporada. La vacunación de la embarazada y la estrategia mixta se valoraron como alternativas, pero no son la estrategia programática general. La ribavirina no se emplea como prevención sistemática, ya que es un antiviral de uso muy restringido en casos graves."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977235") }, {"long_answer": "Las estimaciones globales de carga de enfermedad publicadas para 2019 cifraron en unos 3,6 millones los ingresos hospitalarios por infección de vías respiratorias inferiores asociada al VRS en niños menores de cinco años en todo el mundo, junto con unos 33 millones de episodios de infección respiratoria inferior y más de 100.000 fallecimientos atribuibles al virus. Por tanto, la respuesta correcta es 3,6 millones. Las cifras de 2,5, 3,1 y 4,2 millones no corresponden a la estimación recogida en estos estudios y en la documentación de referencia del Ministerio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977236") }, {"long_answer": "La mayor carga de hospitalizaciones y fallecimientos por VRS se concentra en los lactantes menores de seis meses, que en las estimaciones globales suponen alrededor de la mitad de los ingresos y de las muertes hospitalarias por este virus en menores de cinco años. Esto se debe al pequeño calibre de su vía aérea, la inmadurez inmunológica y el descenso de los anticuerpos maternos. Por ello, las estrategias de prevención con nirsevimab se dirigen sobre todo a esta franja. Los menores de tres meses son un subgrupo de máximo riesgo, pero la carga global se describe en los menores de seis meses; los de 12 y 24 meses son franjas más amplias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97723e") }, {"long_answer": "Los estudios de administración concomitante de Abrysvo con la vacuna dTpa en mujeres no gestantes mostraron una menor respuesta inmunitaria frente a algunos antígenos de la tosferina, sin alcanzar la no inferioridad para todos ellos, aunque se desconoce su relevancia clínica. Por eso se recomienda priorizar la vacunación frente a tosferina y separar ambas vacunas cuando sea posible. No se observó una mayor respuesta inmune global ni un aumento de la efectividad de la vacuna antigripal. Afirmar que no hay ningún efecto adverso es incorrecto, ya que se describen reacciones locales y sistémicas leves, como con otras vacunas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977242") }, {"long_answer": "El virus respiratorio sincitial es una de las principales causas de infección de vías respiratorias inferiores tanto en lactantes como en personas mayores y en adultos con patología crónica, en quienes puede provocar complicaciones graves como neumonía o la descompensación de la enfermedad de base, por ejemplo de EPOC, asma o insuficiencia cardiaca. La gripe y la COVID-19 también pueden descompensar patologías crónicas, pero la pregunta se refiere al VRS, objeto del documento. La varicela es una infección exantemática que no se considera una causa principal de infección respiratoria inferior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977243") }, {"long_answer": "En los países de alta renta y clima templado, el VRS presenta una circulación estacional con picos en otoño e invierno que generan cada año una importante sobrecarga asistencial en atención primaria, urgencias y hospitalización pediátrica, coincidiendo con otros virus respiratorios. Por ello la respuesta correcta son los países de alta renta. En los países de baja renta la mayor parte de la mortalidad por VRS ocurre fuera del hospital, por falta de acceso a la atención. En los países tropicales la circulación es más prolongada o ligada a las lluvias, y Europa del Este no se cita específicamente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977246") }, {"long_answer": "El desarrollo de vacunas frente al VRS se vio frenado durante décadas por la experiencia de los años sesenta con una vacuna inactivada con formalina, que en lugar de proteger provocó una enfermedad potenciada en los niños vacunados que después se infectaron, con hospitalizaciones y fallecimientos. Este riesgo de enfermedad potenciada por anticuerpos condicionó la investigación posterior. El VRS no presenta escasa diversidad que facilite las vacunas, ni se neutraliza con facilidad, ya que evade la respuesta inmune y permite reinfecciones. La dificultad para encontrar voluntarios no es la razón descrita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977247") }, {"long_answer": "Las glicoproteínas de superficie F, de fusión, y G, de adhesión, son las más importantes para la infectividad y la patogenia del VRS. La proteína G media la unión del virus a la célula del epitelio respiratorio, y la F permite la fusión de la envoltura viral con la membrana celular y la formación de sincitios. La proteína F, muy conservada entre los subgrupos A y B, es la diana de nirsevimab y de las vacunas actuales en su conformación de prefusión. Las combinaciones A y B, que designan subgrupos, C y D o X e Y no corresponden a glicoproteínas del VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97724a") }, {"option_3": "Reordenamiento de segmentos genómicos (salto antigénico)", "long_answer": "El principal mecanismo de evolución molecular del VRS es la deriva genética, es decir, la acumulación progresiva de mutaciones puntuales, sobre todo en el gen de la glicoproteína G, que da lugar a la aparición de nuevos genotipos y contribuye a las reinfecciones. La recombinación genética es muy poco frecuente en este virus. El reordenamiento de segmentos o salto antigénico no es posible, porque el VRS tiene un genoma ARN no segmentado, a diferencia del virus de la gripe. La inserción genética no constituye un mecanismo principal, aunque existan algunas duplicaciones descritas en el gen G."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97725c") }, {"long_answer": "Según los datos recogidos en el documento sobre vacunación frente al VRS en población adulta, la letalidad estimada de la infección por VRS en receptores de trasplante de progenitores hematopoyéticos es del 7,28%, una de las más elevadas entre los grupos de riesgo, debido a la profunda inmunosupresión, que favorece la progresión a vías respiratorias inferiores. Esta elevada letalidad justifica que este grupo se considere prioritario en las estrategias de prevención. Las cifras del 5,4%, el 10% y el 12,5% no corresponden a la estimación recogida en la fuente para este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97725e") }, {"long_answer": "Las revisiones sistemáticas recogidas en el documento sobre vacunación frente a VRS en adultos estiman una tasa de ataque de la infección respiratoria aguda por VRS del 1,62% en personas de 60 o más años en países de alta renta, lo que, aplicado a una población envejecida, supone un gran número de casos, hospitalizaciones y fallecimientos cada temporada. Las cifras del 2,26%, el 3,5% y el 4,8% no corresponden a esta estimación. El dato pone de manifiesto que el VRS no es solo un problema pediátrico, sino también relevante en las personas mayores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97725f") }, {"option_1": "Bivalente (subgrupos A y B): 120 μg de proteína pre-F no adyuvada, 60 μg de pre-F de VRS-A y 60 μg de pre-F de VRS-B", "option_3": "60 μg de pre-F monovalente de VRS-A adyuvada con hidróxido de aluminio", "option_4": "120 μg de RSVPreF3 adyuvada con AS01E", "long_answer": "Abrysvo (RSVpreF) es una vacuna bivalente de proteína recombinante que contiene 120 μg de la proteína F estabilizada en conformación de prefusión, 60 μg del subgrupo A y 60 μg del subgrupo B, sin adyuvante. Se utiliza en embarazadas para proteger al lactante y en adultos mayores. La opción de 50 μg de ARNm que codifica la pre-F de VRS-A corresponde a mRESVIA, de Moderna. La de 120 μg de RSVPreF3 con AS01E corresponde a Arexvy, de GSK, que es monovalente y adyuvada. Abrysvo no es monovalente ni lleva hidróxido de aluminio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977262") }, {"long_answer": "En el ensayo de fase III AReSVi-006, la vacuna RSVPreF3 adyuvada (Arexvy) mostró en personas de 60 o más años una eficacia del 82,6% frente a la enfermedad del tracto respiratorio inferior (ETRI) por VRS confirmada durante la primera temporada. El 94,1% corresponde a la eficacia frente a la ETRI grave en esa misma temporada, por lo que no es la eficacia global frente a ETRI. El 67,2% refleja la eficacia acumulada a lo largo de dos temporadas, y el 55,9% no corresponde a la primera temporada, en la que la protección es máxima antes de disminuir con el tiempo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977265") }, {"answer": 1, "long_answer": "En el ensayo AReSVi-006, la eficacia de RSVPreF3 adyuvada (Arexvy) frente a la enfermedad del tracto respiratorio inferior por VRS durante la primera temporada fue del 81,0% en el grupo de 60 a 69 años, con resultados similares al 82,6% global. El 93,8% corresponde al grupo de 70 a 79 años, en el que se observó la estimación puntual más alta. Las cifras del 74,9% y del 65,4% no corresponden a la eficacia en primera temporada en el grupo de 60 a 69 años. La vacuna mostró, por tanto, una protección elevada en ambos grupos de edad."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977267") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97726e") }, {"question": "¿Cuándo se produce habitualmente la primoinfección por VRS?", "option_1": "En la adolescencia", "option_2": "En la edad adulta", "option_3": "En los dos primeros años de vida", "option_4": "Después de los 65 años", "long_answer": "La primoinfección por VRS se produce de forma casi universal en los dos primeros años de vida, ya que prácticamente todos los niños se han infectado antes de cumplir dos años. Es en esta primera infección cuando el virus causa con mayor frecuencia bronquiolitis y neumonía, sobre todo en lactantes pequeños. La inmunidad que deja no es duradera, por lo que las reinfecciones son frecuentes a lo largo de toda la vida, en general más leves, aunque graves en mayores e inmunodeprimidos. Por ello, la primera infección no ocurre en la adolescencia, la edad adulta ni después de los 65 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977271") }, {"long_answer": "En la temporada 2023-2024, la actividad del VRS en España siguió el patrón estacional clásico de otoño-invierno, con aumento de la circulación desde octubre y pico epidémico en torno a diciembre, de forma similar a las temporadas anteriores a la pandemia, tras las temporadas desplazadas observadas durante y después de la COVID-19. Por tanto, la respuesta correcta es otoño-invierno. Los patrones de primavera-verano y verano-otoño corresponden a la circulación atípica de 2021, y el de invierno-primavera no describe la actividad de la temporada 2023-2024."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977275") }, {"long_answer": "Tras administrarse más de 10 millones de dosis de las vacunas de proteínas recombinantes frente al VRS en adultos mayores en EE. UU. durante la temporada 2023-2024, la farmacovigilancia detectó una tasa de notificación de síndrome de Guillain-Barré superior a la esperada, especialmente con la vacuna RSVpreF, lo que llevó a incluir este riesgo en la ficha técnica, aunque el balance beneficio-riesgo se considera favorable. La reducción de hospitalizaciones es un beneficio, no la consecuencia de seguridad destacada. No se relacionó con un aumento de infecciones por gripe ni con una pérdida de efectividad de las vacunas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97727a") }, {"option_1": "Exclusivamente la logística de distribución de las vacunas", "option_2": "La efectividad y la seguridad de la vacunación aplicada en programas poblacionales", "option_3": "Únicamente el precio de adquisición de las vacunas", "option_4": "La retirada de todas las vacunas frente al VRS autorizadas", "answer": 2, "long_answer": "El documento sobre vacunación frente al VRS en población adulta plantea que las recomendaciones deberán revisarse a medida que se obtenga más evidencia, especialmente sobre la efectividad y la seguridad de las vacunas cuando se apliquen en programas poblacionales, la duración de la protección, la necesidad de revacunación y el uso de distintas estrategias de prevención de la enfermedad grave. No se trata de valorar exclusivamente la logística ni únicamente el precio, aunque la evaluación económica forma parte del análisis. La retirada de las vacunas autorizadas no se contempla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97727d") }, {"long_answer": "La prevención de los errores asociados al uso de los medicamentos constituye un área fundamental de actuación en Seguridad del Paciente, ya que los medicamentos son una de las principales causas de eventos adversos evitables en la asistencia sanitaria. Por ello, es una de las líneas prioritarias de la Estrategia de Seguridad del Paciente del SNS y del tercer reto mundial de la OMS, Medicación sin daño. La prevención de enfermedades infecciosas es un objetivo de salud pública más general. La reducción de costes y la mejora de la eficiencia pueden ser consecuencias deseables, pero no son áreas propias de la seguridad del paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977282") }, {"long_answer": "El tercer reto mundial por la seguridad del paciente de la OMS, Medicación sin daño, insta a los países a priorizar tres áreas: las transiciones asistenciales, la polifarmacia inapropiada y las situaciones de alto riesgo, que incluyen los medicamentos de alto riesgo, los pacientes vulnerables y los entornos con mayor probabilidad de error. En ellas se concentran la mayoría de los errores de medicación con daño. Las combinaciones de atención primaria, salud mental y cuidados paliativos, o de enfermedades infecciosas, crónicas y salud materno-infantil, no son las del reto, ni tampoco el desarrollo de nuevos tratamientos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977287") }, {"long_answer": "El Plan de Acción Mundial para la Seguridad del Paciente 2021-2030 de la OMS recomienda, en relación con los medicamentos, implantar prácticas seguras que mejoren la seguridad en todas las etapas del proceso de utilización, en línea con el reto Medicación sin daño, priorizando las situaciones de alto riesgo, la polifarmacia y las transiciones asistenciales, y promoviendo la participación de los pacientes. Centrarse en las enfermedades crónicas o priorizar la prevención de enfermedades infecciosas no son recomendaciones del plan para el uso de medicamentos. Desarrollar nuevos tratamientos tampoco forma parte de sus objetivos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977289") }, {"option_3": "Para reducir el número de medicamentos disponibles en pediatría", "long_answer": "Las recomendaciones sobre medicamentos de alto riesgo se adaptaron a la población pediátrica para facilitar la puesta en marcha de programas de prevención de errores en los centros que atienden a niños, ya que estos pacientes presentan particularidades, como la dosificación por peso, la necesidad de diluciones y la escasez de formas adaptadas, que aumentan el riesgo y la gravedad de los errores. No se pretende estandarizar los medicamentos en todo el ámbito sanitario ni reducir el número de medicamentos disponibles en pediatría. La mejora de la eficiencia del sistema tampoco es la razón principal de la adaptación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97728e") }, {"option_2": "Aplicación de una única práctica segura limitada a la fase de administración", "option_3": "Exclusión de pacientes y familiares del programa y formación solo del personal médico", "long_answer": "Los programas de mejora de la seguridad de los medicamentos de alto riesgo deben regirse por el apoyo y liderazgo institucional, un enfoque multidisciplinar y el establecimiento por cada centro de su propia lista de medicamentos de alto riesgo, a partir de la cual se implantan prácticas seguras. Aplicar una única práctica limitada a la administración es insuficiente, porque se recomiendan múltiples prácticas en todas las etapas del proceso. Excluir a pacientes y familiares o formar solo al personal médico contradice el enfoque de seguridad, que exige su participación y la formación de todos los profesionales implicados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977295") }, {"long_answer": "Según la jerarquía de efectividad de las prácticas de prevención de errores, las más eficaces son las funciones forzadas y las restricciones, que hacen imposible o muy difícil cometer el error, por ejemplo retirar el cloruro potásico concentrado de las unidades o usar conexiones incompatibles para la vía enteral. Le siguen la automatización y la estandarización. Las alertas informáticas y el etiquetado diferenciado de las gavetas son medidas útiles pero de efectividad intermedia, porque dependen de la atención humana. La educación y la información son las de menor efectividad para eliminar errores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97729f") }, {"option_3": "Permitir el almacenamiento de todas las presentaciones en todas las unidades sin restricción", "long_answer": "Entre las prácticas de prevención de errores con anticoagulantes orales dirigidas a los centros sanitarios figura limitar el número de presentaciones disponibles en el hospital, para reducir la posibilidad de confusiones entre dosis y principios activos y facilitar la estandarización. Permitir el almacenamiento de todas las presentaciones en todas las unidades sin restricción aumenta el riesgo de error. Disponer de equipo de monitorización y de resucitación es una práctica propia de la sedación, y la valoración inicial de los antecedentes del paciente es una práctica dirigida a los profesionales, no a los centros."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a2") }, {"option_2": "Utilizar bombas de infusión inteligentes con bibliotecas de fármacos", "option_3": "Estandarizar la prescripción mediante protocolos y formularios normalizados", "option_4": "Realizar un doble chequeo independiente durante la elaboración de la mezcla", "long_answer": "Entre los errores más frecuentes con la nutrición parenteral destacan los cometidos al convertir las dosis prescritas en volúmenes en mililitros o al transcribir las órdenes médicas al programa de elaboración, que pueden originar mezclas con cantidades erróneas de nutrientes o electrolitos y causar daños graves, sobre todo en neonatos y niños. Las demás opciones no son errores, sino prácticas recomendadas para prevenirlos: usar bombas de infusión inteligentes con bibliotecas de fármacos, estandarizar la prescripción mediante protocolos y formularios normalizados, y realizar un doble chequeo independiente durante la elaboración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a6") }, {"long_answer": "Una práctica de prevención de errores con paracetamol intravenoso dirigida a los centros es incorporar en los sistemas de prescripción electrónica herramientas de ayuda a la prescripción y al seguimiento, como alertas de dosis máximas por peso y edad y de duplicidades con paracetamol oral, que reducen el riesgo de sobredosificación y hepatotoxicidad. Las demás opciones describen lo contrario de lo recomendado: se deben disponer de protocolos actualizados de dosificación, preparación y administración, restringir la vía intravenosa a situaciones en las que no sean posibles la oral o la rectal y vigilar los niveles plasmáticos cuando haya sospecha de sobredosis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a7") }, {"long_answer": "Uno de los errores más frecuentes con el potasio intravenoso es prescribir y administrar una dosis, concentración o velocidad de infusión incorrecta, lo que puede provocar hiperpotasemia, arritmias graves e incluso parada cardiaca. Por ello es un medicamento de alto riesgo. Usar presentaciones orales de sales de potasio cuando sea posible no es un error, sino una práctica segura recomendada. No establecer un protocolo que estandarice las soluciones y no diferenciar los viales de potasio de otros medicamentos son deficiencias organizativas que favorecen los errores, pero no constituyen el error de administración detectado con mayor frecuencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ae") }, {"long_answer": "Las recomendaciones de seguridad para familias aconsejan hablar con el niño sobre los medicamentos que toma, explicándole qué son y para qué sirven, para que no los confunda con golosinas o bebidas especiales, lo que reduce el riesgo de ingestiones accidentales e intoxicaciones. Por eso nunca deben presentarse como caramelos. Que conozca el nombre o la hora de la toma puede ser útil, pero la responsabilidad de la administración corresponde a los adultos. Medir las dosis es tarea del cuidador, no del niño, y requiere utilizar el dosificador adecuado de cada medicamento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772af") }, {"long_answer": "Ante cualquier reacción inusual que aparezca tras la toma de un medicamento, como erupción, dificultad respiratoria, hinchazón o vómitos, se recomienda consultar de inmediato con el médico o el profesional sanitario, que valorará si se trata de una reacción adversa y qué hacer con el tratamiento; la reacción también debe notificarse. Seguir administrando la dosis normal o aumentarla puede agravar el cuadro. Suspender por cuenta propia todos los medicamentos tampoco es adecuado, porque algunos no pueden interrumpirse bruscamente y la decisión debe tomarla el profesional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771b1") }, {"long_answer": "Para organizar bien las tomas de medicación se recomienda elaborar una lista o calendario de recordatorio con el nombre de cada medicamento, la dosis, la hora y la duración del tratamiento, y apoyarse en pastilleros o alarmas si es necesario. Esta herramienta mejora la adherencia y evita olvidos y duplicidades, sobre todo cuando se toman varios fármacos. No organizar las tomas o tomarlas a cualquier hora favorece errores y reduce la eficacia del tratamiento. Las dudas deben consultarse con profesionales sanitarios, como el médico, la enfermera o el farmacéutico, no con personas no profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771b8") }, {"long_answer": "La alcoholemia expresada en gramos por litro (g/L) indica la cantidad de alcohol presente en la sangre, es decir, los gramos de etanol por cada litro de sangre, y es la unidad que se utiliza para establecer los límites legales para conducir, junto con su equivalente en aire espirado en mg/L. Por tanto, la respuesta correcta es la cantidad de alcohol en sangre. Las opciones referidas al contenido alcohólico de la cerveza, del vino o de una copa de vino son incorrectas, porque el contenido de las bebidas se expresa en grados o en gramos de alcohol por unidad de bebida estándar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ba") }, {"option_1": "Solo cuando se superan claramente los límites legales", "option_2": "Solo si se han tomado más de tres copas", "long_answer": "La recomendación sanitaria es no conducir después de haber consumido alcohol, en cualquier cantidad, porque incluso dosis bajas alteran la atención, la percepción del riesgo y el tiempo de reacción, y no existe un consumo seguro compatible con la conducción. Por ello son incorrectas las opciones que limitan la prohibición a superar claramente los límites legales o a haber tomado más de tres copas, ya que se puede tener la capacidad alterada por debajo de esos umbrales. Haber comido no impide conducir, aunque una comida copiosa puede favorecer la somnolencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771bc") }, {"option_4": "Todas las anteriores", "answer": 4, "long_answer": "El alcohol es un depresor del sistema nervioso central y, al volante, produce simultáneamente varios efectos: empeora el control muscular y la coordinación, genera una falsa sensación de seguridad que lleva a asumir más riesgos, altera la visión, que se vuelve borrosa, con reducción del campo visual y peor adaptación a la oscuridad y a los deslumbramientos, y deteriora la capacidad de decisión y el cálculo de distancias y velocidades. Por eso la respuesta correcta es todas las anteriores. Elegir solo uno de estos efectos sería incompleto, ya que todos contribuyen a aumentar el riesgo de siniestro vial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771bf") }, {"option_2": "615.281 €", "option_3": "3.230.562 €", "option_4": "161.528 €", "long_answer": "Según los datos de 2019 recogidos en el documento, el coste económico asociado a cada persona fallecida por siniestro vial se estimó en 1.615.281 euros, cifra que integra costes sanitarios, de servicios de emergencia, daños materiales, pérdida de productividad y, sobre todo, el valor de la pérdida de vida y del sufrimiento humano. Este dato pone de manifiesto que la siniestralidad vial es un problema de salud pública con gran impacto económico y social. Las cifras de 615.281, 3.230.562 y 161.528 euros no corresponden a la estimación recogida en la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771c0") }, {"long_answer": "El Ministerio de Sanidad recomienda no consumir alcohol cuando se vaya a conducir, siguiendo el principio de que alcohol y conducción son incompatibles, ya que cualquier cantidad altera la capacidad para conducir con seguridad. Conducir despacio no compensa la pérdida de reflejos, de atención ni de coordinación. Comer antes solo retrasa algo la absorción del alcohol, pero no evita sus efectos, y el café puede reducir la sensación de somnolencia sin disminuir la alcoholemia ni mejorar la capacidad de reacción, por lo que da una falsa sensación de seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771c4") }, {"long_answer": "En situaciones de inundaciones, la principal recomendación de salud pública en materia de vacunación es mantener las coberturas de las vacunas del calendario a lo largo de toda la vida y las indicadas en grupos de riesgo, revisando el estado vacunal, especialmente frente al tétanos en quienes participan en tareas de limpieza o sufren heridas. No está indicada una vacunación masiva de toda la población, porque las inundaciones no suelen asociarse a epidemias prevenibles por vacunación en nuestro medio. Tampoco es correcto renunciar a cualquier actuación ni priorizar a los adultos en general, sin atender al calendario y a los grupos de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771d1") }, {"question": "¿Cuál es el efecto de la entrada en vigor del Real Decreto 47/2023, que modifica la regulación de los productos del tabaco?", "long_answer": "El Real Decreto 47/2023 actualiza la reglamentación vigente sobre los productos del tabaco calentado, eliminando determinadas excepciones de las que se beneficiaban, de modo que se les prohíben los aromas característicos y se les exigen las mismas advertencias sanitarias que al resto de productos del tabaco para fumar. Por tanto, no se prohíbe la venta de productos del tabaco, que siguen comercializándose bajo regulación, ni se eliminan las advertencias sanitarias, que precisamente se refuerzan. Tampoco aumentan las excepciones aplicables al tabaco calentado, sino que se suprimen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771d4") }, {"long_answer": "El protocolo para la detección precoz y el manejo de los casos de viruela del mono (MPX) tiene como objetivo principal garantizar la detección y el diagnóstico precoz de los casos para adoptar a tiempo las medidas de control, como el aislamiento y el estudio de contactos, y evitar así la aparición de casos secundarios. Evitar la propagación internacional y aplicar medidas a nivel mundial corresponden a organismos internacionales como la OMS, no a un protocolo nacional de detección. Identificar a los casos más vulnerables es una actuación del manejo clínico, pero no el objetivo principal del protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771d5") }, {"long_answer": "Según el protocolo de viruela del mono, se considera caso sospechoso a la persona con exantema vesicular o pustuloso, en cualquier parte del cuerpo, acompañado de síntomas como fiebre, cefalea, astenia, mialgias o linfadenopatías, sin otra causa que lo explique. El elemento clínico característico es la lesión cutánea vesiculopustulosa. La fiebre superior a 39 °C, la mialgia intensa o la presencia aislada de linfadenopatía no bastan para clasificar un caso como sospechoso, porque son manifestaciones inespecíficas que aparecen en muchas otras infecciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771d8") }, {"option_4": "Vacunación pre y posexposición en grupos de riesgo definidos", "long_answer": "La recomendación de vacunación frente a la viruela del mono (MPX) en España es selectiva: profilaxis preexposición en personas con alto riesgo, como personas con prácticas sexuales de riesgo o determinados profesionales, y profilaxis posexposición en contactos estrechos de casos confirmados, preferentemente en los primeros días tras la exposición. No es una vacunación obligatoria para toda la población, ni se dirige a niños y ancianos como grupos prioritarios. Tampoco es cierto que no se recomiende por falta de disponibilidad, aunque inicialmente las dosis fueron limitadas y se priorizaron los grupos de mayor riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771dc") }, {"long_answer": "En los sistemas de alerta temprana basados en eventos, el filtrado inicial es la primera fase del proceso y tiene como propósito filtrar la información procedente de las fuentes informales, como medios de comunicación, redes sociales o plataformas en línea, para descartar lo irrelevante y quedarse solo con las posibles señales de interés para la salud pública. Verificar y evaluar las señales son fases posteriores, que se aplican cuando la información ya ha superado el filtrado. La búsqueda activa de información complementaria también corresponde a etapas posteriores de verificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771e7") }, {"long_answer": "Aunque en vía urbana los taxis estén exentos de la obligación, la recomendación de seguridad es que el bebé viaje siempre en un sistema de retención infantil homologado adecuado a su peso y talla, por lo que conviene solicitarlo al pedir el taxi o llevar el propio. Fuera de la ciudad, además, es obligatorio. Llevarlo en brazos es muy peligroso, ya que en una colisión el adulto no puede sujetarlo y puede incluso aplastarlo. Dejarlo suelto en el asiento o asumir que el sistema de retención no es necesario expone al bebé a lesiones graves en caso de frenazo o accidente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771e9") }, {"option_2": "Sustituir la intervención de los servicios sociales y judiciales", "option_3": "Centralizar la atención exclusivamente en los servicios de urgencias", "long_answer": "El Protocolo Común de Actuación Sanitaria frente a la violencia contra niños, niñas y adolescentes tiene entre sus objetivos la promoción del buen trato a la infancia y la adolescencia, junto con la prevención, la detección precoz, la atención y la coordinación ante situaciones de violencia. El protocolo no pretende sustituir a los servicios sociales ni judiciales, sino coordinarse con ellos, ni centralizar la atención en urgencias, ya que implica a todos los niveles, especialmente a la atención primaria. La elaboración del informe anual es una función de la CoViNNA, no un objetivo del protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ea") }, {"long_answer": "Entre las funciones de la Comisión frente a la violencia en los niños, niñas y adolescentes (CoViNNA) del Consejo Interterritorial figura prestar apoyo y orientación a las administraciones sanitarias en la planificación de las medidas para prevenir, detectar y abordar la violencia contra la infancia, además de elaborar el protocolo común y un informe anual. Los protocolos específicos los elaboran las administraciones sanitarias de cada comunidad autónoma, no la comisión. La representación de las comunidades describe su composición, no una función, y el acceso universal a la información no es una de sus funciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771eb") }, {"option_2": "Eliminación de la evaluación del protocolo", "option_3": "Supresión de la formación de los profesionales", "option_4": "Restricción del protocolo a la violencia física exclusivamente", "long_answer": "Una de las novedades del nuevo Protocolo Común de Actuación Sanitaria es la incorporación de una definición amplia de violencia contra la infancia y la adolescencia y de su tipología, en línea con la LOPIVI, que incluye violencia física, psicológica, sexual, negligencia, violencia digital y otras formas. No se elimina la evaluación del protocolo, sino que se prevén su difusión, monitorización y evaluación. Tampoco se suprime la formación de los profesionales, que es un elemento clave para la detección, ni se restringe a la violencia física, sino que abarca todas sus formas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771f0") }, {"long_answer": "Para que los niños, niñas y adolescentes víctimas de violencia puedan acceder a los servicios de tratamiento y recuperación es imprescindible la información: deben conocer, de forma adaptada a su edad y madurez, sus derechos, los recursos disponibles y cómo acceder a ellos, en un lenguaje comprensible. Por ello la respuesta correcta es la información. La representación de las comunidades autónomas se refiere a la composición de la CoViNNA, la definición de violencia y su tipología es un contenido del protocolo, y la capacitación de profesionales es una medida formativa, no un requisito de acceso para el menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771f3") }, {"long_answer": "Según la información de seguridad vial recogida en el documento, que sigue las indicaciones de la DGT, la edad mínima que se establece para el uso de patinetes eléctricos es de 15 años, ya que requieren una madurez suficiente para circular entre el tráfico, percibir los riesgos y respetar las normas. Por debajo de esta edad no se recomienda su uso. Los 12 años quedan por debajo del umbral indicado, y los 18 y 21 años son edades vinculadas a la obtención de permisos de conducción, no al uso de patinetes eléctricos. En todo caso, se recomienda siempre el uso de casco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771f8") }, {"answer": 2, "long_answer": "El Reglamento General de Circulación establece que los ciclistas menores de 16 años deben usar casco de protección homologado en cualquier vía, tanto urbana como interurbana o travesía, y no solo en carretera. Por tanto, la respuesta correcta es en cualquier vía. Limitar la obligación a la ciudad o solo a las autovías es incorrecto, y además las bicicletas tienen prohibido circular por autovías salvo excepciones. Afirmar que no es obligatorio también es falso para este grupo de edad. Para los mayores de 16 años el casco es obligatorio en vías interurbanas, salvo excepciones, y siempre recomendable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771fc") }, {"question": "¿Cuál es el número máximo de plazas, incluido el conductor, de los vehículos que se pueden conducir con el permiso B, obtenible a partir de los 18 años?", "long_answer": "El permiso B, que puede obtenerse a partir de los 18 años, autoriza a conducir automóviles con una masa máxima autorizada de hasta 3.500 kg y diseñados para el transporte de no más de nueve personas, incluido el conductor. Por tanto, la respuesta correcta es 9 plazas. Las cifras de 5 y 7 plazas corresponden a configuraciones habituales de turismos, pero no al límite del permiso. Un vehículo de 10 plazas o más se considera autobús y requiere los permisos de la categoría D, con mayor edad mínima y formación específica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ff") }, {"long_answer": "Se recomienda que los menores de 16 años usen siempre casco homologado y bien ajustado cuando utilicen bicicleta o patinete, tanto en la ciudad como en carretera, porque los traumatismos craneoencefálicos son la principal causa de muerte y lesiones graves en caídas y atropellos, y el casco reduce de forma importante ese riesgo. En bicicleta, además, es obligatorio para menores de 16 en cualquier vía. Por ello son incorrectas las opciones que afirman que no es necesario, que solo se use en la ciudad o que no se use en carretera, donde las velocidades y la gravedad de las lesiones son mayores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977201") }, {"long_answer": "Para circular con seguridad en bicicleta o patinete se recomienda hacerlo solo por las zonas señalizadas o habilitadas para ello, como carriles bici o espacios destinados a estos vehículos, respetando las normas y a los peatones, ya que así se reduce la exposición al tráfico. Circular con auriculares es peligroso porque impide oír avisos, sirenas o vehículos que se aproximan. Hacer competiciones con otros niños favorece velocidades excesivas y caídas, y circular por cualquier lugar, incluidas aceras o calzadas no adecuadas, aumenta el riesgo de atropellos y colisiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977202") }, {"long_answer": "El uso de luces en bicicletas y patinetes es obligatorio de noche y en condiciones de poca iluminación o visibilidad reducida, como al atravesar túneles o con niebla, para ver y, sobre todo, ser visto por el resto de usuarios de la vía. Se recomienda además usar prendas o elementos reflectantes. Afirmar que nunca es necesario es falso. Limitar su uso a los días de lluvia es incompleto, porque la obligación depende de la iluminación, no solo del clima, y en los días soleados con buena luz no son obligatorias, por lo que esa opción es incorrecta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977204") }, {"long_answer": "Aunque la normativa obliga a utilizar un sistema de retención infantil homologado en menores de hasta 135 cm de altura, las recomendaciones de seguridad aconsejan mantenerlo hasta que el niño alcance 1,50 metros, ya que por debajo de esta talla el cinturón de seguridad del adulto no se ajusta correctamente sobre la clavícula y la pelvis y puede causar lesiones en el cuello y el abdomen. Por eso la respuesta correcta es hasta 1,50 metros. El metro y el 1,20 metros son tallas claramente insuficientes, y 1,35 metros es el límite legal, no la altura recomendada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97720d") }, {"long_answer": "Nirsevimab es un anticuerpo monoclonal de administración única por temporada que, por su forma de uso poblacional en todos los lactantes en su primera temporada de VRS, se asemeja en la práctica a una vacuna de calendario frente a una enfermedad infecciosa epidémica, aunque confiere inmunidad pasiva. Su autorización en la Unión Europea se produjo en 2022, no en 2023, y en 2023-2024 comenzó a utilizarse en varios países, entre ellos España, por lo que no es cierto que no se haya aprobado en ningún país. Tampoco está indicado en mayores de dos años, sino en recién nacidos, lactantes y niños de hasta 24 meses vulnerables."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977212") }, {"long_answer": "La vacuna Arexvy (RSVPreF3 adyuvada con AS01E) se autorizó inicialmente para la prevención de la enfermedad del tracto respiratorio inferior por VRS en personas de 60 o más años, y posteriormente su indicación se amplió a adultos de 50 a 59 años con mayor riesgo de enfermedad por VRS, tras demostrar en ellos una respuesta inmunitaria no inferior. Por ello, entre las opciones propuestas, la correcta es de 50 a 59 años. Las franjas de 20 a 29, de 30 a 39 y de 40 a 49 años no están incluidas en la indicación de la vacuna."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977213") }, {"long_answer": "Durante la temporada 2023-2024, primera campaña de inmunización con nirsevimab en España, la cobertura alcanzada en los recién nacidos durante la temporada fue de alrededor del 90%, muy elevada para una intervención nueva, gracias a su administración precoz en la maternidad o en las primeras semanas de vida. Esta alta cobertura contribuyó a la marcada reducción de las hospitalizaciones por VRS en lactantes. Las cifras del 60% y el 80% subestiman la cobertura alcanzada, y una cobertura del 100% no se logró, aunque varias comunidades se acercaron a ella."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977214") }, {"long_answer": "En la temporada 2023-2024, la cobertura de inmunización con nirsevimab en los lactantes nacidos antes de la temporada, entre el 1 de abril y el 30 de septiembre de 2023, a quienes se captó en una campaña de rescate, fue en torno al 70% según los datos del documento. Fue inferior a la de los recién nacidos en temporada, que se inmunizaban en la maternidad, porque la captación activa de estos niños en atención primaria resulta más compleja. Las cifras del 50%, el 60% y el 80% no corresponden al dato recogido en la fuente para esta cohorte."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97721a") }, {"long_answer": "En el ensayo de fase III de la vacuna materna RSVpreF (Abrysvo), la eficacia frente a la infección de vías respiratorias inferiores grave por VRS atendida médicamente fue del 81,8% en los primeros 90 días de vida del lactante, cuando los niveles de anticuerpos transferidos por la madre son más elevados. El 69,4% corresponde a la eficacia frente a la forma grave a los 180 días, y el 57,1% a la eficacia frente a la infección de vías respiratorias inferiores de cualquier gravedad a los 90 días. El 40,6% no corresponde a la eficacia frente a enfermedad grave."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977220") }, {"long_answer": "La vacuna materna frente al VRS consigue la mayor eficacia en la prevención de la infección de vías respiratorias inferiores grave del lactante cuando se administra entre las semanas 32 y 36 de gestación, ya que se asegura un tiempo suficiente para la transferencia transplacentaria de anticuerpos y se reduce el riesgo asociado al parto prematuro observado en algunos análisis. El intervalo de 24 a 36 semanas es el autorizado inicialmente en ficha técnica, pero no el óptimo. Entre 28 y 32 semanas la protección es menor, y entre 36 y 40 semanas puede no haber tiempo suficiente para transferir anticuerpos antes del parto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977221") }, {"answer": 2, "long_answer": "En el ensayo de la vacuna materna RSVpreF, la eficacia frente a la infección de vías respiratorias inferiores de cualquier causa atendida médicamente en los lactantes fue muy baja, del 7,3%, sin significación estadística, porque muchas de estas infecciones se deben a virus distintos del VRS, frente a los que la vacuna no protege. Por el contrario, el 51,3% corresponde a la eficacia frente a la infección de vías respiratorias inferiores atendida médicamente específicamente por VRS a los 180 días, por lo que no responde a la pregunta. El 56,8% y el 34,7% tampoco corresponden al dato de cualquier causa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977223") }, {"option_1": "Fue similar en el grupo vacunado y en el grupo placebo", "long_answer": "En el ensayo de la vacuna materna RSVpreF, la incidencia de eventos adversos graves en los niños desde el nacimiento hasta los 24 meses fue similar en el grupo de madres vacunadas y en el grupo placebo, sin diferencias que sugieran un problema de seguridad atribuible a la vacuna. Por tanto, no es cierto que fuera mayor en el grupo vacunado ni mayor en el placebo. Tampoco es correcto afirmar que no se dispone de esta información, ya que el seguimiento de seguridad de los lactantes hasta los 24 meses formó parte del ensayo y sus resultados se recogen en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977227") }, {"long_answer": "Según el documento, el estudio realizado en tres comunidades autónomas mediante el método del cribado, que compara la proporción de inmunizados entre los casos hospitalizados con la cobertura en la población, estimó una reducción del riesgo de hospitalización por VRS asociada a nirsevimab del 84,4%, en línea con la alta efectividad observada en otros estudios españoles durante la temporada 2023-2024. Las cifras del 70,2%, el 38,3% y el 76,8% no corresponden al resultado obtenido con este método en dichas comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977229") }, {"long_answer": "Según el estudio multicéntrico prospectivo recogido en el documento, las hospitalizaciones por VRS en la temporada 2023-2024 se redujeron un 41,1% respecto al mismo periodo de la temporada 2022-2023, coincidiendo con la primera campaña de inmunización con nirsevimab en lactantes. Esta reducción refleja el impacto poblacional del anticuerpo, aunque la intensidad de la temporada también influye en la comparación. Las cifras del 31,1%, el 51,1% y el 21,1% no corresponden a la reducción descrita en este estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97722c") }, {"long_answer": "En Galicia, comunidad pionera en la campaña de inmunización con nirsevimab, la cohorte de lactantes nacidos entre abril y septiembre de 2023, inmunizados en la campaña de rescate antes de la temporada, mostró una reducción muy significativa de las tasas semanales de hospitalización por VRS respecto a temporadas anteriores, que se sumó a la observada en los nacidos en temporada. Esto confirma el beneficio de captar también a los nacidos antes de la temporada. No es cierto que no se observara reducción, y calificarla de moderada o generalizada no recoge la magnitud descrita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977233") }, {"long_answer": "La estrategia mixta, que combina la vacunación de la embarazada con nirsevimab para los lactantes no protegidos por la madre, presenta varias desventajas: una logística y una captación más complejas, al requerir coordinar dos intervenciones y verificar el estado vacunal materno; el riesgo de que queden sin proteger los recién nacidos de madres no vacunadas o vacunadas demasiado cerca del parto si falla su captación para el anticuerpo; y la posible interferencia de la vacuna materna con la respuesta a la vacuna frente a la tosferina. Por ello la respuesta correcta es todas las anteriores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977237") }, {"answer": 1, "long_answer": "Hasta la fecha del documento, el único tratamiento antiviral específico autorizado para la enfermedad por VRS es la ribavirina, de uso muy restringido por su eficacia limitada, su toxicidad y su forma de administración, de modo que en la práctica se reserva a pacientes inmunodeprimidos graves y el manejo se basa en medidas de soporte. Palivizumab y nirsevimab son anticuerpos monoclonales indicados para la prevención, no para el tratamiento de la enfermedad ya establecida. El oseltamivir es un antiviral frente a la gripe, sin actividad frente al VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97723b") }, {"long_answer": "En el ensayo de fase III de la vacuna materna RSVpreF (Abrysvo), la eficacia frente a la infección de vías respiratorias inferiores grave por VRS atendida médicamente en los primeros 90 días de vida del lactante fue del 81,8%, el resultado principal que sustentó su autorización. Esta protección disminuye después, hasta alrededor del 69% a los 180 días. Las cifras del 74,5%, el 79,9% y el 85,2% no corresponden a este resultado. La vacuna se administra en la embarazada para que los anticuerpos se transfieran al feto a través de la placenta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977244") }, {"long_answer": "Según el informe de carga mundial de enfermedades recogido en el documento sobre vacunación frente al VRS en adultos, la tasa de mortalidad por VRS en las personas mayores de 70 años es de 34,51 muertes por 100.000 personas-año, la más alta entre los grupos de adultos, lo que evidencia la importancia de este virus como causa de muerte en las personas mayores, junto con la gripe. Las tasas de 15,21, 25,34 y 45,67 muertes por 100.000 personas-año no corresponden al dato recogido para este grupo de edad en la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97724c") }, {"option_4": "Mastocitos", "long_answer": "Los linfocitos T CD8+ o citotóxicos reconocen los antígenos del VRS presentados por moléculas del complejo mayor de histocompatibilidad de clase I y eliminan directamente las células infectadas, siendo fundamentales para el aclaramiento viral. Los linfocitos B producen anticuerpos, que neutralizan el virus pero no destruyen directamente la célula infectada. Los linfocitos T CD4+ coordinan la respuesta inmune mediante citocinas, ayudando a linfocitos B y T CD8+. Los mastocitos participan en reacciones inflamatorias y alérgicas, pero no se encargan de eliminar las células infectadas por virus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977250") }, {"long_answer": "Una de las características más llamativas de la infección por VRS es su capacidad para causar reinfecciones sintomáticas a lo largo de toda la vida, ya que la infección natural no genera una inmunidad duradera ni completa, incluso frente a cepas muy similares. Por ello, las personas se reinfectan repetidamente, con cuadros generalmente más leves, aunque pueden ser graves en mayores e inmunodeprimidos. La inmunidad tras la primoinfección no es duradera. Tampoco es una característica destacada la rápida resolución de los síntomas ni una baja mortalidad, ya que causa una importante carga de enfermedad grave."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977253") }, {"long_answer": "Según las estimaciones recogidas en el documento sobre vacunación frente al VRS en adultos, el número de hospitalizaciones anuales por infección por VRS en España en personas mayores de 80 años es de 19.247, la cifra más alta de todos los grupos de edad adultos, lo que pone de manifiesto que el riesgo de ingreso aumenta con la edad. Las cifras de 2.159, 7.992 y 15.055 corresponden a grupos de edad más jóvenes o no se ajustan a la estimación para este grupo. Este dato apoya priorizar la prevención en las personas de mayor edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977254") }, {"long_answer": "Según los datos de vigilancia recogidos en el documento, la tasa de hospitalización por VRS en el grupo de 1 a 4 años disminuyó en la temporada 2023-2024 en comparación con la temporada 2022-2023, que había sido excepcionalmente intensa tras la pandemia por la acumulación de niños susceptibles que no se habían infectado antes. Por tanto, no aumentó ni se mantuvo constante. La opción de que no se menciona es incorrecta, ya que la fuente analiza la evolución por grupos de edad, en paralelo a la reducción observada en los lactantes inmunizados con nirsevimab."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977258") }, {"long_answer": "Según los datos recogidos en el documento sobre vacunación frente al VRS en adultos, la letalidad intrahospitalaria de la infección por VRS en los mayores de 85 años es del 10%, la más alta de los grupos de edad, comparable o superior a la de la gripe en esa población. Esto refleja la fragilidad, la comorbilidad y el riesgo de complicaciones respiratorias y cardiovasculares en las personas muy mayores. Las cifras del 8%, el 20% y el 25% no corresponden al dato recogido en la fuente para este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977261") }, {"long_answer": "El ensayo clínico pivotal de fase III para evaluar la eficacia de la vacuna RSVPreF3 adyuvada con AS01E (Arexvy) fue el estudio AReSVi-006, aleatorizado y controlado con placebo, que incluyó a cerca de 25.000 personas de 60 o más años de varios países y demostró una eficacia del 82,6% frente a la enfermedad del tracto respiratorio inferior por VRS en la primera temporada. Los estudios AReSVi-004 y AReSVi-002 evaluaron aspectos de inmunogenicidad, seguridad, revacunación o coadministración, y AReSVi-008 no es el ensayo pivotal de eficacia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97726a") }, {"long_answer": "Según los datos de efectividad en vida real recogidos en el documento, procedentes de los primeros estudios realizados en EE. UU. durante la temporada 2023-2024, las vacunas de proteínas recombinantes frente al VRS mostraron en personas de 60 o más años una efectividad del 90% para prevenir hospitalizaciones asociadas al VRS, confirmando en condiciones reales los buenos resultados de los ensayos clínicos. Las cifras del 81%, el 75% y el 73% no corresponden al dato de prevención de hospitalizaciones señalado en la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97726c") }, {"long_answer": "Según los datos recogidos en el documento, la vacuna basada en vector adenoviral Ad26.RSV.preF combinada con proteína preF mostró una eficacia del 65,7% para la prevención de la enfermedad del tracto respiratorio inferior por VRS durante la segunda temporada, inferior a la de la primera temporada, lo que refleja la pérdida progresiva de protección con el tiempo, algo común a las vacunas frente al VRS en adultos. Las cifras del 78,7%, el 42,9% y el 59% no corresponden a la eficacia de segunda temporada recogida en la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97726d") }, {"long_answer": "Según la revisión de las recomendaciones internacionales recogida en el documento, en el momento de su elaboración países como Australia, Canadá y Noruega habían emitido recomendaciones de vacunación frente al VRS en adultos de 60 o más años, generalmente priorizando a los de mayor edad o con factores de riesgo. En cambio, en España, Italia y Francia, así como en los demás grupos de países propuestos, las recomendaciones no se habían establecido aún con esos criterios o eran más restrictivas en ese momento, por lo que esas combinaciones no son correctas según la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97726f") }, {"long_answer": "Entre las opciones propuestas, la tasa de mortalidad por infección por VRS es más alta en los adultos mayores de 70 años, ya que la inmunosenescencia, la fragilidad y la elevada prevalencia de enfermedades crónicas cardiacas y respiratorias favorecen la neumonía y la descompensación de la patología de base. Los menores de cinco años presentan una gran carga de hospitalizaciones, pero su tasa de mortalidad, sobre todo en países de alta renta, es menor. Los adolescentes de 15 a 18 años y los adultos de 30 a 40 años sanos tienen una mortalidad muy baja por este virus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977274") }, {"question": "¿Qué eficacia ha mostrado la vacuna RSVPreF3 (Arexvy) frente a la enfermedad del tracto respiratorio inferior por VRS en personas de 70-79 años en la primera temporada?", "long_answer": "En el ensayo AReSVi-006, la vacuna RSVPreF3 adyuvada (Arexvy) mostró una eficacia del 93,8% frente a la enfermedad del tracto respiratorio inferior por VRS en las personas de 70 a 79 años durante la primera temporada, la estimación puntual más alta por grupos de edad. El 81,0% corresponde al grupo de 60 a 69 años, el 82,6% a la eficacia global en mayores de 60 años, y el 60,0% no corresponde a la eficacia en este grupo durante la primera temporada. Estos resultados respaldan priorizar la vacunación en los grupos de mayor edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977276") }, {"long_answer": "Según el documento sobre vacunación frente al VRS en adultos, en la temporada 2023-2024 EE. UU. fue el país que estableció un programa de vacunación a nivel poblacional, tras la recomendación de los CDC de vacunar a las personas de 60 o más años mediante decisión clínica compartida, lo que permitió administrar millones de dosis y obtener los primeros datos de efectividad y seguridad en vida real. España, Italia y Francia no habían implantado aún en esa temporada un programa poblacional de vacunación frente al VRS en adultos, por lo que esas opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977279") }, {"long_answer": "En el momento de elaboración del documento, la Comisión de Salud Pública no estableció recomendaciones de vacunación sistemática frente al VRS en la población adulta, a la espera de disponer de más evidencia sobre la efectividad y la seguridad en programas poblacionales, la duración de la protección y el impacto económico, aunque se reconoce la carga de enfermedad en las personas mayores. Por tanto, no se recomendó vacunar a toda la población adulta, ni restringir la recomendación a mayores de 70 años o a personas con comorbilidades, ya que no se emitió una recomendación programática."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97727b") }, {"long_answer": "En las evaluaciones económicas de la vacunación frente al VRS en adultos, la variable que genera mayor variabilidad en los resultados es el precio de la vacuna, de modo que pequeñas variaciones en el coste por dosis cambian de forma importante la razón coste-efectividad y pueden determinar si la intervención resulta eficiente. La edad de los vacunados, la duración de la protección y la eficacia también influyen en los análisis de sensibilidad, pero según el documento su impacto sobre la variabilidad de los resultados es menor que el del precio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97727f") }, {"long_answer": "Según la OMS, los daños causados por los medicamentos y otros tratamientos representan alrededor del 50% de todos los daños prevenibles derivados de la asistencia sanitaria, lo que convierte la seguridad del uso de los medicamentos en una prioridad mundial y justifica el tercer reto mundial, Medicación sin daño, y su inclusión en el Plan de Acción Mundial para la Seguridad del Paciente 2021-2030. Las cifras del 20%, el 70% y el 90% no corresponden a la estimación de la OMS, que sitúa en la mitad la proporción de daños prevenibles atribuibles a medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977283") }, {"long_answer": "Los pacientes pediátricos son un colectivo de especial riesgo con la medicación porque presentan diferencias en sus procesos fisiológicos básicos, como la absorción, la distribución, el metabolismo y la eliminación de fármacos, que varían con la edad y el desarrollo, lo que obliga a calcular dosis individualizadas por peso y a preparar diluciones, aumentando la probabilidad y la gravedad de los errores. No se debe a que sean más propensos a infecciones, a que no sigan las indicaciones, ya que dependen de sus cuidadores, ni a que reciban menos atención médica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977286") }, {"long_answer": "El Plan de Acción Mundial para la Seguridad del Paciente 2021-2030 de la OMS incluye una estrategia para mejorar la seguridad del uso de los medicamentos, dentro de su objetivo de garantizar la seguridad de los procesos clínicos, en línea con el reto Medicación sin daño, con acciones sobre las situaciones de alto riesgo, la polifarmacia y las transiciones asistenciales. El plan no se centra en mejorar la eficiencia del sistema, ni en la gestión de enfermedades infecciosas como tal, ni en el desarrollo de nuevos tratamientos médicos, aspectos ajenos a la seguridad del paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97728a") }, {"long_answer": "A PINCH es un acrónimo utilizado como lista básica de medicamentos de alto riesgo en hospitales, que agrupa los grupos con mayor probabilidad de causar daño grave si se produce un error: antiinfecciosos, potasio y otros electrolitos, insulina, narcóticos u opioides y sedantes, quimioterápicos, y heparina y otros anticoagulantes. Ayuda a recordar los medicamentos que requieren prácticas seguras específicas. No es una lista de tratamientos de enfermedades infecciosas, ni específica de la administración en pediatría, ni de atención primaria, ámbito para el que existe la lista MARC de pacientes crónicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97728f") }, {"long_answer": "Los programas de mejora de la seguridad de los medicamentos de alto riesgo deben implicar a todos los profesionales que intervienen en su utilización, es decir, a médicos, enfermeras, farmacéuticos, técnicos y gestores, en todas las fases del proceso: selección, prescripción, validación, dispensación, preparación, administración y seguimiento, además de contar con la participación de los pacientes y sus familias. Limitarlos solo a médicos y enfermeras deja fuera eslabones esenciales del proceso. Restringirlos a pacientes pediátricos o a pacientes crónicos es incorrecto, porque afectan a todos los pacientes que reciben estos medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977291") }, {"long_answer": "Cada centro debe elaborar su propia lista de medicamentos de alto riesgo, incluyendo como mínimo los recomendados por el ISMP y, en el ámbito de la atención a pacientes crónicos, los de la lista MARC, y adaptándola a los medicamentos que utiliza y a los incidentes que se producen en él. Incluir solo los medicamentos con altas tasas de error es incorrecto, porque lo que define a un medicamento de alto riesgo es la gravedad del daño cuando se produce un error, no su frecuencia. Una lista excesivamente amplia diluye su utilidad, y limitarla a pacientes crónicos es insuficiente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97729b") }, {"option_2": "Almacenar juntos los medicamentos con nombres similares", "long_answer": "Una práctica recomendada para reducir errores en la fase de prescripción de medicamentos de alto riesgo en pediatría es disponer de protocolos de uso y guías de prescripción accesibles y actualizados, con dosis estandarizadas por peso y edad, concentraciones normalizadas y dosis máximas, que facilitan una prescripción correcta y homogénea. El doble chequeo independiente se aplica sobre todo en la preparación y administración. Almacenar juntos los medicamentos con nombres similares favorece las confusiones, por lo que se recomienda lo contrario. Incentivar la notificación de incidentes es una medida general de aprendizaje, no específica de la prescripción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a1") }, {"option_2": "Omitir la evaluación de antecedentes antes de la sedación para agilizar el procedimiento", "long_answer": "Entre las prácticas de prevención de errores con medicamentos para sedación moderada y mínima dirigidas a los profesionales figura mantener al paciente en observación con monitorización continua durante unos 30 minutos tras la finalización del procedimiento, ya que el efecto depresor respiratorio puede persistir o aparecer cuando cesa el estímulo. Omitir la evaluación de antecedentes antes de la sedación es lo contrario de lo recomendado. Comprobar la presentación adecuada a la vía de administración y administrar la insulina IV con bomba de infusión inteligente son prácticas correspondientes a otros grupos de medicamentos de alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a8") }, {"option_2": "Utilizar el peso apropiado para calcular la dosis en pacientes con bajo peso u obesidad", "option_4": "Revisar la medicación activa para evitar duplicidades entre la vía oral y la intravenosa", "long_answer": "Uno de los errores más frecuentes detectados con la vancomicina se produce en la preparación del medicamento, sobre todo cuando son necesarias varias diluciones para administrar dosis muy bajas, como ocurre en neonatos y lactantes, lo que favorece errores de cálculo y de concentración. Las demás opciones no describen errores, sino prácticas seguras: ajustar la dosis a la indicación y a los factores que la modifican, utilizar el peso apropiado en pacientes con bajo peso u obesidad, y revisar la medicación activa para evitar duplicidades entre la vía oral y la intravenosa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ad") }, {"long_answer": "Al recoger la medicación en la farmacia se recomienda asegurarse de que los medicamentos dispensados coinciden con los prescritos en cuanto a nombre, dosis y forma farmacéutica, y preguntar al farmacéutico si se observa cualquier cambio en el envase o en la apariencia, como ocurre con los genéricos, para evitar confusiones y duplicidades. Por ello son incorrectas las opciones de no revisar los medicamentos, no preguntar ante cambios de aspecto y no consultar el prospecto, ya que todas ellas aumentan el riesgo de errores en la toma de la medicación en el domicilio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b1") }, {"long_answer": "Según los estándares y recomendaciones del Ministerio de Sanidad, el bloque quirúrgico (BQ) es una unidad intermedia que presta servicio a los servicios clínicos finales, como las especialidades quirúrgicas, que son las responsables de los pacientes, ofreciéndoles los espacios, el equipamiento y el personal necesarios para realizar los procedimientos quirúrgicos. No se limita a prestar servicio a urgencias, que es una de las vías de entrada de pacientes, ni a rehabilitación o diagnóstico por imagen, que son a su vez servicios intermedios o finales distintos y no los destinatarios principales del BQ."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b3") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b4") }, {"long_answer": "Según el documento de estándares y recomendaciones, el cumplimiento de los estándares básicos por parte de los hospitales se evalúa en los dominios de seguridad, calidad y eficiencia, que permiten valorar si la organización, los recursos y los procesos garantizan una atención segura, de calidad y con un uso adecuado de los recursos. Las combinaciones de efectividad, gobernanza y entorno, de atención al paciente, accesibilidad y salud pública, y de producción, distribución y servicio de atención no corresponden a los dominios definidos en la fuente para esta evaluación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b5") }, {"long_answer": "Según el documento, la tasa de cirugía mayor ambulatoria (CMA) en los hospitales españoles es inferior a la de los estándares y referencias internacionales, por lo que existe margen para aumentar la proporción de procedimientos realizados sin ingreso, con beneficios para el paciente, como menor riesgo de infección nosocomial y más rápida reincorporación, y para el sistema, por el ahorro de estancias. Por tanto, no es superior ni igual a la de esos estándares, y la opción de que no se menciona es incorrecta, ya que la fuente compara expresamente ambos datos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe2") }, {"long_answer": "En su primera temporada de VRS, los lactantes reciben una dosis única intramuscular de nirsevimab ajustada al peso: 50 mg si pesan menos de 5 kg y 100 mg si pesan 5 kg o más. Por tanto, la respuesta correcta es 50 mg. La dosis de 25 mg no está establecida, 75 mg no corresponde a ninguna pauta y 100 mg es la dosis de los lactantes de 5 kg o más. En la segunda temporada, los niños que siguen siendo vulnerables reciben una dosis también según el peso, según las recomendaciones del Ministerio de Sanidad: 100 mg si pesan menos de 10 kg y 200 mg, en dos inyecciones de 100 mg en el mismo acto, si pesan 10 kg o más."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe6") }, {"long_answer": "Nirsevimab es un anticuerpo monoclonal indicado para prevenir la enfermedad de las vías respiratorias inferiores producida por el VRS en recién nacidos y lactantes durante su primera temporada, y en niños vulnerables en la segunda, con el fin de reducir las bronquiolitis y neumonías, las consultas, las hospitalizaciones y los ingresos en UCI. No está indicado para tratar la infección ya establecida. Su objetivo principal no es reducir la transmisión del virus en la comunidad, y no produce inmunidad permanente, ya que confiere una protección pasiva y transitoria de al menos cinco meses."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe7") }, {"long_answer": "Los prematuros de menos de 35 semanas pueden recibir nirsevimab hasta los 12 meses de edad cronológica, incluso si ya lo recibieron en la temporada anterior. Según las recomendaciones del Ministerio de Sanidad, en la segunda temporada la dosis se ajusta al peso: 100 mg en una única inyección si pesan menos de 10 kg, y 200 mg, en dos inyecciones de 100 mg en el mismo acto, si pesan 10 kg o más. Por eso a este niño le corresponden 100 mg. La dosis de 50 mg es la de los lactantes de menos de 5 kg en su primera temporada, 200 mg se reserva a los de 10 kg o más y 75 mg no es una dosis establecida.", "question": "¿Qué dosis de nirsevimab recibirá un prematuro de menos de 35 semanas de gestación que, antes de cumplir 12 meses de edad cronológica, afronta su segunda temporada de VRS con un peso inferior a 10 kg?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ffa") }, {"long_answer": "La OMS recomienda facilitar a los pacientes y cuidadores herramientas que les ayuden a organizar y administrar sus tratamientos, como listas actualizadas de medicación, tarjetas o aplicaciones y materiales como la iniciativa de cinco momentos para la seguridad de la medicación, con el fin de que participen activamente y pregunten cualquier duda. Proporcionar información sobre enfermedades no relacionadas no favorece esta implicación. Limitar el acceso a la información sobre los medicamentos o desalentar la participación son actuaciones contrarias a la seguridad del paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977003") }, {"long_answer": "Fomentar que pacientes, familiares y cuidadores participen en la identificación de incidentes permite proteger a los pacientes de posibles daños evitables, ya que pueden detectar errores, como un medicamento de aspecto distinto o una dosis duplicada, que han pasado inadvertidos a los profesionales, y comunicarlos a tiempo. Además, mejora la confianza en el sistema y el aprendizaje organizativo. Las demás opciones describen efectos contrarios a los buscados: evitar la participación del paciente, aumentar los eventos adversos evitables o reducir la confianza en el sistema sanitario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977005") }, {"long_answer": "Diversas organizaciones de seguridad del paciente recomiendan que los pacientes y sus acompañantes estén alerta y comuniquen a los profesionales sanitarios los posibles riesgos en la administración de medicamentos, como recibir un fármaco desconocido, una dosis distinta de la habitual, un medicamento al que se es alérgico o la omisión de una toma, ya que actúan como una última barrera frente a los errores. Los eventos sociales, los cambios en las políticas de salud y los problemas económicos no guardan relación con la seguridad de la medicación durante la asistencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97700c") }, {"long_answer": "Durante la estancia hospitalaria, la medicación propia que aporta el paciente debe ser identificada y conciliada, y la enfermería se encarga de custodiarla, administrarla y registrarla convenientemente, para garantizar que se administra lo prescrito, evitar duplicidades con la medicación del hospital y asegurar la trazabilidad. Utilizarla sin consultar con el personal sanitario o dejar que el paciente se la administre por su cuenta puede causar duplicidades, interacciones o errores de dosis. Entregarla a otros pacientes es una práctica peligrosa e inaceptable."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97700e") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977010") }, {"long_answer": "Según el documento sobre el abordaje del pie diabético, la tasa de amputaciones en hombres con diabetes mostró una tendencia descendente en los años analizados, probablemente relacionada con la mejora del control de la diabetes, del cribado del pie de riesgo y del acceso a unidades multidisciplinares, aunque se mantiene más elevada que en las mujeres. Por tanto, no es ascendente ni estable. La opción de que no se menciona en el documento es incorrecta, ya que la fuente analiza expresamente la evolución de las amputaciones por sexo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977011") }, {"long_answer": "Según los datos internacionales recogidos en el documento sobre pie diabético, la tasa de amputaciones mayores de miembro inferior en personas con diabetes en España duplica la de otros países de referencia, lo que pone de manifiesto la necesidad de mejorar la prevención, el cribado del pie de riesgo, la educación del paciente y el acceso precoz a equipos multidisciplinares. Por tanto, no es igual a la media de los países comparados ni menor. La opción de que no se menciona es incorrecta, porque la fuente incluye esta comparación internacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977013") }, {"long_answer": "Según el documento sobre pie diabético, en 2018 la tasa de amputaciones presentó una amplia variabilidad entre comunidades autónomas, desde unas 3 por 100.000 habitantes en Navarra hasta unas 18 por 100.000 habitantes en la ciudad autónoma de Ceuta, diferencias que reflejan desigualdades en la prevalencia de diabetes, en la organización asistencial y en el acceso a la prevención. El rango de 5 a 10 por 100.000 entre La Rioja y la Comunidad Valenciana no corresponde a los datos de la fuente, y no es cierto que la tasa sea la misma en todas las comunidades ni que no se mencione."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977018") }, {"long_answer": "El monofilamento de Semmes-Weinstein de 5,07, que ejerce una presión de 10 g, es el recurso material recomendado para la estratificación del pie de riesgo en la persona con diabetes, ya que permite detectar la pérdida de sensibilidad protectora por neuropatía, uno de los principales factores de riesgo de úlcera. Se complementa con el diapasón, la palpación de pulsos y el índice tobillo-brazo. Los pulsiómetros digitales y las básculas no se utilizan para estratificar el riesgo del pie, y los ecógrafos no forman parte del cribado básico en atención primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97701a") }, {"long_answer": "En el abordaje del pie diabético, se recomienda derivar a los pacientes con alteraciones ungueales, como onicocriptosis, onicomicosis o uñas engrosadas, a su podólogo o podóloga habitual, que es el profesional encargado del cuidado de las uñas y de las durezas para prevenir lesiones y úlceras. El especialista en cirugía ortopédica se reserva para deformidades estructurales complejas, el de angiología y cirugía vascular para la enfermedad arterial periférica significativa, y el médico de atención primaria coordina el seguimiento, pero no realiza el tratamiento podológico de las uñas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97701b") }, {"long_answer": "Los pacientes con diabetes y enfermedad arterial periférica clínicamente significativa, con ausencia de pulsos, índice tobillo-brazo alterado o síntomas de isquemia, deben ser evaluados por el especialista en angiología y cirugía vascular, que valorará la necesidad de pruebas de imagen y de revascularización, fundamental para la cicatrización de las úlceras y la prevención de amputaciones. El podólogo se ocupa del cuidado del pie y de las uñas, el especialista en rehabilitación de la recuperación funcional, y el cirujano ortopédico de las deformidades estructurales, no de la isquemia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97701c") }, {"long_answer": "Según el documento sobre pie diabético, la educación estructurada y la concienciación de pacientes y familiares sobre el pie diabético ulcerado debe coordinarla el líder del proceso en atención primaria, que organiza las intervenciones educativas del equipo, garantiza su continuidad y asegura que el paciente sepa cómo cuidar sus pies y cómo reconocer signos de alarma. El especialista en cirugía ortopédica y el médico de urgencias intervienen de forma puntual en el proceso asistencial, y el podólogo participa en la educación, pero no es el responsable de coordinarla según la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97701f") }, {"long_answer": "Para que los pacientes con diabetes puedan contactar con su equipo asistencial de atención primaria en cuanto aparezca una úlcera, se recomienda establecer un número de teléfono abierto en horario asistencial, que permita una consulta rápida y una valoración precoz, ya que el retraso en la atención empeora el pronóstico y aumenta el riesgo de infección y amputación. El correo electrónico no garantiza una respuesta ágil, la atención telefónica 24/7 no es lo que se propone en la fuente para este circuito, y la aplicación móvil no es la medida recomendada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977022") }, {"long_answer": "Ante un episodio de hemólisis aguda durante la sesión de hemodiálisis, el material necesario incluye un tensiómetro para controlar la tensión arterial y las constantes vitales, ya que puede aparecer hipotensión e inestabilidad hemodinámica, junto con el material para detener la diálisis, pinzar las líneas sin retornar la sangre y obtener muestras para analítica. Los juegos de mesa, las gafas de sol y una botella de agua no tienen ninguna utilidad clínica en el manejo de esta complicación, por lo que son opciones claramente incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977025") }, {"long_answer": "Una medida de seguridad clave en hemodiálisis es parar la diálisis ante cualquier sospecha de hemólisis aguda, con signos como sangre de color oscuro en la línea venosa, dolor torácico o lumbar, disnea o hipotensión, pinzando las líneas sin retornar la sangre al paciente, porque esa sangre contiene potasio liberado por los hematíes y puede causar hiperpotasemia grave. Incrementar la temperatura del líquido de diálisis puede provocar hemólisis. No verificar las medidas de seguridad del circuito extracorpóreo ni comprobar la correcta colocación de las líneas son prácticas inseguras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97702b") }, {"long_answer": "El ictus isquémico se produce por una falta de aporte sanguíneo a una zona del cerebro, habitualmente por la oclusión de una arteria por un trombo o un émbolo, lo que impide que lleguen oxígeno y glucosa al tejido nervioso y origina el infarto cerebral. La falta de oxígeno es la consecuencia de la isquemia, no el mecanismo que la produce, y puede darse por otras causas como la parada cardiaca. La rotura de un vaso sanguíneo produce el ictus hemorrágico, y la inflamación del tejido cerebral corresponde a encefalitis, no a ictus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97702d") }, {"long_answer": "Los síntomas de presentación más frecuentes del ictus son la pérdida brusca de fuerza en la cara, el brazo o la pierna, generalmente de un lado del cuerpo, y la dificultad para hablar o comprender, que son los síntomas que recogen las campañas de reconocimiento rápido para activar el Código Ictus. Los mareos y la visión borrosa pueden aparecer en algunos ictus, como los de territorio posterior, pero son menos frecuentes y más inespecíficos. El dolor abdominal intenso y la dificultad para respirar no son síntomas típicos de ictus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977031") }, {"option_2": "Edad, sexo, raza y antecedentes familiares de ictus", "option_3": "Edad avanzada, herencia genética y antecedentes personales de ictus", "option_4": "Sexo masculino, etnia y antecedentes familiares de enfermedad cardiovascular", "long_answer": "Los factores de riesgo modificables del ictus son aquellos sobre los que se puede intervenir para reducir el riesgo, como la presión arterial elevada, que es el más importante, la dislipemia, el tabaquismo, la dieta poco saludable, la obesidad y la inactividad física, junto con la diabetes, el consumo de alcohol y la fibrilación auricular. Las demás opciones incluyen factores no modificables, como la edad, el sexo, la raza o etnia, la herencia genética y los antecedentes familiares o personales, que identifican a personas de mayor riesgo pero no pueden cambiarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97703f") }, {"question": "¿Cuántos nodos de trombectomía hay en la Comunidad Autónoma de Aragón?", "long_answer": "Según la Estrategia en Ictus del SNS, la Comunidad Autónoma de Aragón cuenta con un único nodo de trombectomía mecánica, ubicado en Zaragoza, que actúa como centro de referencia para el tratamiento endovascular del ictus isquémico agudo de toda la comunidad, mientras que el resto de hospitales derivan a los pacientes candidatos mediante el Código Ictus. Por ello la respuesta correcta es un nodo. Las cifras de 6, 2 y 4 nodos no corresponden a la organización descrita para Aragón, aunque pueden darse en comunidades más pobladas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977043") }, {"long_answer": "Tras una hemorragia subaracnoidea, la complicación más temida y la causa más frecuente de morbilidad en los supervivientes es el daño cerebral diferido, o isquemia cerebral diferida, que suele aparecer entre el tercer y el decimocuarto día y se relaciona con el vasoespasmo y otros mecanismos, provocando nuevos déficits neurológicos. Por ello se vigila estrechamente y se administra nimodipino de forma preventiva. La hidrocefalia aguda, las crisis epilépticas y el estado epiléptico no convulsivo son complicaciones posibles, pero menos determinantes de la morbilidad a largo plazo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97704e") }, {"long_answer": "Entre las medidas generales en el manejo del ictus agudo figura mantener la permeabilidad de la vía aérea y una adecuada función ventilatoria y oxigenación, administrando oxígeno solo si la saturación es baja, junto con el control de la tensión arterial, la glucemia y la temperatura, para proteger la zona de penumbra isquémica. Aplicar frío local o realizar masajes de drenaje linfático no forma parte del manejo del ictus. La anticoagulación en las primeras 24 horas no es una medida general y está contraindicada tras la trombólisis por el riesgo de transformación hemorrágica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977052") }, {"long_answer": "Las leyes de derechos y garantías de la dignidad de la persona en el proceso de la muerte se inspiran, entre otros principios básicos, en la protección de la dignidad de la persona en el proceso final de su vida, junto con el respeto a su autonomía, a su voluntad y a sus valores y el derecho a recibir cuidados paliativos integrales. Las demás opciones, como mejorar la calidad de los servicios de atención al ictus, incrementar la independencia funcional al alta o reducir la mortalidad intrahospitalaria por ictus, son objetivos de la Estrategia en Ictus, no principios de esta ley."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977053") }, {"long_answer": "Entre las recomendaciones que deben abordarse en todos los pacientes que ingresan en una unidad de ictus figura asegurar el acceso a los cuidados paliativos y de final de la vida a los pacientes con ictus que los requieran, ya que una parte de ellos presenta ictus graves con mal pronóstico y precisa control de síntomas, apoyo a la familia y respeto a sus voluntades. Realizar evaluaciones anuales de indicadores, obtener los indicadores de calidad de la Estrategia y promover la formación continuada son acciones de planificación y evaluación del sistema, no recomendaciones asistenciales para cada paciente ingresado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977056") }, {"long_answer": "Las terapias de reperfusión del ictus isquémico, la trombólisis intravenosa y la trombectomía mecánica, tienen una ventana terapéutica de horas, de hasta 4,5 horas para la trombólisis y ampliable hasta 24 horas en la trombectomía en pacientes seleccionados mediante neuroimagen. Su beneficio depende del tiempo, ya que cada minuto de isquemia supone la pérdida de millones de neuronas, lo que justifica la activación del Código Ictus. Por tanto, la ventana no se mide en días, semanas ni meses, plazos en los que el tejido isquémico ya no es recuperable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977059") }, {"option_1": "Abandonar las estrategias de prevención primaria del ictus", "option_3": "Reducir el número de unidades de ictus", "option_4": "Limitar la atención al ictus a la fase aguda hospitalaria", "long_answer": "El Plan de Acción Europeo en Ictus 2018-2030 abarca toda la cadena asistencial, desde la prevención primaria hasta la vida después del ictus, y entre sus objetivos principales incluye establecer planes de rehabilitación a largo plazo, con acceso precoz a la rehabilitación y seguimiento de las secuelas. Abandonar la prevención primaria es contrario al plan, que pretende reducir el número absoluto de ictus. Reducir las unidades de ictus contradice su objetivo de tratar a la mayoría de pacientes en ellas, y limitar la atención a la fase aguda ignora la rehabilitación y la reintegración social."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977061") }, {"long_answer": "Se considera criptogénico el ictus isquémico en el que, tras un estudio etiológico completo, no se identifica una causa definida, y según el documento representa alrededor del 25% de los ictus isquémicos, una proporción relevante que ha impulsado conceptos como el ESUS, ictus embólico de origen indeterminado, y la búsqueda de fibrilación auricular oculta mediante monitorización prolongada. La cifra del 10% o del 8-10% infraestima su frecuencia, y el 50% la sobreestima, ya que la mayoría de los ictus tienen una causa aterotrombótica, cardioembólica o lacunar identificable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977064") }, {"long_answer": "En el ensayo CAPRIE, el tratamiento con clopidogrel en monoterapia en prevención secundaria redujo, en comparación con el ácido acetilsalicílico, el riesgo relativo del objetivo combinado de ictus isquémico, infarto de miocardio o muerte vascular en torno a un 8%, una diferencia modesta que lo sitúa como alternativa válida, especialmente en intolerantes al AAS. No reduce el riesgo de ictus isquémico en un 40% frente al AAS, y no aumenta las complicaciones hemorrágicas respecto a este, con perfil de sangrado similar o algo menor. Afirmar que no tiene efecto es incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977069") }, {"long_answer": "Según la evidencia disponible y las guías de atención al parto normal, se recomienda que la mujer decida libremente la posición que adopta durante el periodo expulsivo, animándola a elegir la que le resulte más cómoda, ya que las posiciones verticales o laterales se asocian a menos partos instrumentales y episiotomías y a menor dolor. Seguir sin más las indicaciones del profesional no respeta la autonomía de la mujer. La posición supina o de litotomía no debe imponerse, ya que dificulta el expulsivo, y no tomar decisiones informadas contradice el modelo de atención centrado en la mujer."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97706b") }, {"long_answer": "En España se observa una gran variabilidad en el uso de la episiotomía entre comunidades autónomas y entre hospitales, con tasas en algunos centros muy superiores a las recomendadas, pese a que la evidencia y la Estrategia de Atención al Parto Normal aconsejan un uso restrictivo y no rutinario, solo ante indicación clínica. Por tanto, la respuesta correcta es la variabilidad en su uso. Describirla como práctica común generalizada o como de poca utilización no refleja esa heterogeneidad, y la opción de uso exclusivo carece de sentido en este contexto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97706c") }, {"long_answer": "Según la evidencia recogida en el documento, para monitorizar adecuadamente la práctica de la episiotomía en España se necesita más información, es decir, sistemas de registro homogéneos y datos fiables y comparables entre centros y comunidades, que permitan conocer las tasas reales, evaluar la variabilidad y comprobar el cumplimiento de la recomendación de uso restrictivo. No se requiere una mejor tecnología ni más personal médico para este fin, y tampoco nuevas recomendaciones, ya que las vigentes ya establecen que la episiotomía no debe practicarse de forma rutinaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977074") }, {"long_answer": "La analgesia epidural es el método farmacológico que proporciona el alivio del dolor más eficaz durante el trabajo de parto: la evidencia muestra que reduce la intensidad del dolor en mayor medida que cualquier otra alternativa y que las mujeres que la reciben refieren mayor satisfacción con el control del dolor, aunque se asocia a una segunda etapa más prolongada y a más partos instrumentales. El óxido nitroso ofrece una analgesia moderada e inferior a la epidural. La acupuntura y los masajes son métodos no farmacológicos que pueden ayudar a sobrellevar el dolor y reducir la necesidad de analgesia, pero su eficacia analgésica es claramente menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97707a") }, {"option_2": "Separar a la madre y al recién nacido durante las primeras horas", "long_answer": "La Estrategia de atención al parto normal recomienda trabajar con los grupos de apoyo a la lactancia materna como medida para fomentar las buenas prácticas, ya que estos grupos de madres ofrecen acompañamiento, información práctica y apoyo emocional que mejoran el inicio y la duración de la lactancia. Separar a la madre y al recién nacido en las primeras horas es una práctica contraria a la evidencia, pues dificulta el contacto piel con piel y el inicio precoz del amamantamiento. Dar información sobre lactancia artificial no fomenta la lactancia materna, y promover el parto en el hogar no guarda relación con esta recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977080") }, {"long_answer": "Para orientar adecuadamente las expectativas de las usuarias se recomienda compartir con ellas información sobre las limitaciones de la efectividad de algunas prácticas. Una información veraz y completa, que incluya lo que una intervención puede y no puede conseguir, permite que la mujer tenga expectativas realistas, participe en la toma de decisiones informadas y se reduzca la frustración ante resultados no deseados. Brindar información inexacta, no compartir u ocultar esas limitaciones son actitudes contrarias al derecho a la información y a la autonomía de la usuaria, y generan expectativas irreales que deterioran la relación de confianza con los profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97708a") }, {"long_answer": "Compartir con las usuarias información sobre las limitaciones de la efectividad de algunas prácticas permite ajustar sus expectativas a la realidad, de modo que, cuando se produce un resultado adverso, este no se vive como un fallo inesperado de la atención. Por ello se espera que esta información reduzca las reclamaciones ante resultados adversos, además de favorecer la confianza y la toma de decisiones compartida. No es esperable que aumente las reclamaciones ni que resulte indiferente, ya que la información realista es precisamente un factor protector frente a ellas. No informar sobre las limitaciones es lo contrario de lo que se recomienda."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97709f") }, {"option_2": "Privatización de la atención cardiológica especializada", "option_3": "Reducción de los programas de rehabilitación cardiaca", "option_4": "Centralización de toda la atención en hospitales de tercer nivel", "long_answer": "El empoderamiento y la participación ciudadana es una de las áreas de actuación que recoge la Estrategia en Salud Cardiovascular del SNS, que busca que pacientes, cuidadores y ciudadanía adquieran conocimientos y capacidades para el autocuidado y participen activamente en las decisiones sobre su salud y en el diseño de los servicios. La privatización de la atención especializada, la reducción de los programas de rehabilitación cardiaca o la centralización de toda la atención en hospitales de tercer nivel no forman parte de la Estrategia, que apuesta precisamente por reforzar la rehabilitación, la continuidad asistencial y la coordinación entre niveles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a3") }, {"long_answer": "En España, en 2019, las enfermedades cardiovasculares (enfermedades del sistema circulatorio) fueron la primera causa de muerte, por delante de los tumores, según los datos de defunciones del INE recogidos en la Estrategia en Salud Cardiovascular. Los tumores ocuparon el segundo lugar, muy próximos, y en los hombres llegan a superar a las causas circulatorias, pero en el conjunto de la población las ECV siguieron encabezando la mortalidad. Las enfermedades respiratorias se situaron en tercer lugar, y los accidentes de tráfico representan una proporción muy pequeña del total de defunciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a4") }, {"long_answer": "Un bajo nivel de actividad física, es decir, el sedentarismo, es un factor de riesgo cardiovascular modificable bien establecido: se asocia a mayor prevalencia de obesidad, hipertensión, dislipemia y diabetes, y aumenta de forma independiente la incidencia de enfermedad coronaria e ictus. Las demás opciones describen situaciones protectoras o no asociadas a mayor riesgo: un alto nivel socioeconómico se relaciona con menor carga de ECV (son los niveles bajos los que se asocian a más riesgo), y un consumo elevado de frutas y verduras y unos hábitos de sueño saludables son factores que contribuyen a reducir el riesgo cardiovascular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ad") }, {"long_answer": "La Estrategia en Salud Cardiovascular, al analizar el enfoque de género, recoge que alrededor del 45 % de las mujeres con sobrepeso u obesidad cancela o retrasa sus citas médicas por el estigma social asociado al peso, sobre todo por miedo a ser juzgadas o a que se les recomiende perder peso como respuesta a cualquier problema. Este comportamiento retrasa la detección y el control de factores de riesgo cardiovascular y es un ejemplo de cómo la presión social sobre la imagen corporal genera inequidades en el acceso a la atención. Los porcentajes del 15 %, 25 % y 35 % infravaloran la magnitud de este fenómeno descrito en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ba") }, {"long_answer": "La Estrategia en Salud Cardiovascular del SNS identifica la continuidad asistencial como elemento clave para una atención sanitaria de calidad, eficiente y segura, y plantea promocionarla y potenciarla mediante la coordinación entre atención primaria, hospitalaria, urgencias y servicios sociales, la transición segura tras el alta y la información compartida. La promoción y prevención, la gestión del conocimiento y la equidad y género son también áreas o ejes de la Estrategia, pero el documento no las define como el elemento clave de la calidad y seguridad de la atención, sino que abordan otros objetivos como reducir la incidencia, generar evidencia o eliminar desigualdades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770bd") }, {"long_answer": "Dentro del eje de equidad y género, la Estrategia en Salud Cardiovascular señala como punto crítico promocionar el conocimiento y el autocuidado de la salud cardiovascular en la mujer, dado que existe una menor percepción del riesgo, presentaciones clínicas atípicas y retrasos en el diagnóstico y tratamiento de las mujeres con ECV. Mejorar las redes asistenciales de atención al síndrome coronario agudo corresponde a la cardiopatía isquémica, mejorar el acceso a la reanimación cardiopulmonar corresponde a la parada cardiaca y promover el diagnóstico precoz de la fibrilación auricular corresponde al área de arritmias, por lo que no son puntos críticos de equidad y género."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770bf") }, {"long_answer": "Impulsar el diagnóstico precoz de la insuficiencia cardiaca es uno de los puntos críticos que la Estrategia en Salud Cardiovascular asocia a esta enfermedad, ya que su detección suele ser tardía, lo que empeora el pronóstico y aumenta los ingresos hospitalarios; para ello se promueven herramientas como la determinación de péptidos natriuréticos y la ecocardiografía accesible desde atención primaria. Organizar la atención al shock cardiogénico mediante un código shock se vincula a la atención urgente y a la cardiopatía isquémica, el diagnóstico precoz de la fibrilación auricular pertenece al área de arritmias y la mejora del acceso a la reanimación cardiopulmonar al área de parada cardiaca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c2") }, {"long_answer": "El mapa estratégico de la Estrategia en Salud Cardiovascular (ESCAV) se articula en torno a cuatro objetivos estratégicos, que constituyen el nivel superior del mapa y orientan el resto de áreas de resultados y líneas de actuación. Estos objetivos resumen la finalidad de la Estrategia: mejorar la salud cardiovascular de la población, reducir la incidencia y la mortalidad de la ECV y mejorar la calidad de vida de las personas que la padecen, con equidad. Las cifras de tres, cinco o seis objetivos no se corresponden con la estructura del mapa estratégico descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c3") }, {"long_answer": "El mapa estratégico de la ESCAV contempla seis áreas de resultados finales, que concretan los resultados en salud que se persiguen (por ejemplo, en promoción y prevención, cardiopatía isquémica, insuficiencia cardiaca, arritmias, ictus u otras patologías cardiovasculares) y que se derivan de los objetivos estratégicos del nivel superior. Por debajo de ellas se sitúan las áreas de resultados intermedios y los mapas transversales. Las cifras de cinco, siete u ocho áreas no se corresponden con la estructura recogida en el mapa estratégico de la Estrategia en Salud Cardiovascular del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c6") }, {"long_answer": "La ESCAV cuenta con siete mapas estratégicos individuales relativos a ejes transversales de actuación específica, que desarrollan aspectos comunes a todas las patologías cardiovasculares, como la equidad y el género, el empoderamiento y la participación ciudadana, la continuidad asistencial, los sistemas de información o la gestión del conocimiento, la investigación y la innovación. Estos mapas complementan al mapa estratégico general y permiten abordar de forma específica cada eje transversal. Las cifras de seis, ocho o nueve mapas no se ajustan a la estructura descrita en la Estrategia en Salud Cardiovascular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770cf") }, {"long_answer": "El mapa estratégico de la ESCAV contempla once áreas de obtención de resultados intermedios, situadas por debajo de las áreas de resultados finales. Estas áreas recogen los cambios en procesos asistenciales, organización y capacidades que hay que conseguir para alcanzar los resultados en salud, como la mejora de la detección precoz, de las redes asistenciales, de la rehabilitación cardiaca o de la continuidad asistencial. Las cifras de diez, doce o trece áreas no se corresponden con la estructura del mapa estratégico definida en la Estrategia en Salud Cardiovascular del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770df") }, {"long_answer": "La Estrategia en Salud Cardiovascular señala que los roles y presiones sociales de género condicionan la forma en que las mujeres acceden al sistema sanitario, y en concreto que la presión social sobre la imagen corporal y el estigma del peso hacen que muchas mujeres retrasen o eviten las consultas, lo que demora la detección de factores de riesgo. No es cierto que las mujeres tengan, en general, más acceso efectivo que los hombres a la atención cardiovascular, ya que se describen infradiagnóstico e infratratamiento. Tampoco se atribuye la menor accesibilidad a factores genéticos, y la situación económica sí influye en el acceso, por lo que la opción que lo niega es falsa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e0") }, {"long_answer": "El empoderamiento de las mujeres es uno de los mecanismos fundamentales para alcanzar la equidad de género en salud cardiovascular, porque les permite conocer su riesgo, reconocer síntomas que con frecuencia son atípicos, practicar el autocuidado y demandar una atención adecuada, reduciendo el infradiagnóstico y el retraso terapéutico. La exclusión de las mujeres de los ensayos clínicos es precisamente una de las causas de la inequidad, ya que limita la evidencia aplicable a ellas, y la discriminación de género en la atención la agrava. Utilizar terapias basadas únicamente en evidencia generada sin perspectiva de género tampoco garantiza la equidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ea") }, {"option_2": "3,3 % en 2009 y 2,8 % en 2019", "long_answer": "Según los datos recogidos en la Estrategia en Salud Cardiovascular, la prevalencia declarada de cardiopatía isquémica en España pasó del 2,8 % en 2009 al 3,3 % en 2019, lo que refleja un aumento progresivo atribuible en parte al envejecimiento poblacional y a la mayor supervivencia tras los eventos coronarios. La opción que invierte las cifras (3,3 % en 2009 y 2,8 % en 2019) describe un descenso que no se produjo. Las opciones que desglosan por sexo no reflejan los datos de prevalencia de cardiopatía isquémica del documento; además, la que atribuye mayor prevalencia a las mujeres es incorrecta, ya que la CI es más prevalente en hombres."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770eb") }, {"long_answer": "Según la Estrategia en Salud Cardiovascular, la cardiopatía isquémica es responsable de aproximadamente el 25,1 % de las muertes por enfermedad cardiovascular en España, lo que la convierte, junto con la enfermedad cerebrovascular, en una de las principales causas de mortalidad dentro de este grupo. El porcentaje del 48,5 % sobreestima claramente su peso, ya que la CI no supone la mitad de las muertes cardiovasculares. Las cifras del 13,6 % y del 16,1 % corresponden a otros indicadores del documento y no a la proporción de muertes por ECV atribuibles a la cardiopatía isquémica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ec") }, {"long_answer": "La prevalencia de la insuficiencia cardiaca en la población adulta española se estima en torno al 1,89 %, según los datos que recoge la Estrategia en Salud Cardiovascular, y aumenta de forma muy marcada con la edad, superando ampliamente esta cifra en mayores de 75 años. Es una de las principales causas de hospitalización en personas mayores y se asocia a elevada mortalidad y reingresos, de ahí la importancia de su diagnóstico precoz. El 3,3 % corresponde a la prevalencia de cardiopatía isquémica en 2019, el 4,2 % a otro indicador por sexo, y el 16,1 % sobreestima de forma desproporcionada la prevalencia de la insuficiencia cardiaca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ee") }, {"option_2": "Reducir la coordinación entre atención primaria y hospitalaria", "option_3": "Limitar el acceso de la ciudadanía a la información sobre su salud cardiovascular", "option_4": "Disminuir la oferta de rehabilitación cardiaca en atención primaria", "long_answer": "A partir del análisis de situación de la salud cardiovascular en España, la Estrategia identifica como punto crítico promover y potenciar la continuidad asistencial, considerada elemento clave para una atención de calidad, eficiente y segura, ya que las personas con ECV transitan entre distintos niveles y profesionales y requieren coordinación, información compartida y transiciones seguras. Reducir la coordinación entre atención primaria y hospitalaria, limitar el acceso de la ciudadanía a la información sobre su salud cardiovascular o disminuir la oferta de rehabilitación cardiaca son medidas contrarias a los principios de la Estrategia, que apuesta por la integración asistencial, el empoderamiento y la prevención secundaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f0") }, {"option_2": "Reducir los programas comunitarios de actividad física", "long_answer": "En el área de promoción de la salud y prevención de la enfermedad cardiovascular, la Estrategia recoge como punto crítico desarrollar la capacitación de los profesionales sanitarios y de otros profesionales relacionados con la promoción de la salud cardiovascular y la prevención, de forma que puedan intervenir eficazmente sobre los factores de riesgo y los estilos de vida. Reducir los programas comunitarios de actividad física iría en contra de la promoción de la salud. Mejorar las redes asistenciales de atención al síndrome coronario agudo pertenece al área de cardiopatía isquémica, y potenciar la continuidad asistencial es un punto crítico transversal relacionado con la calidad asistencial, no con la promoción y prevención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f1") }, {"option_3": "Limitar la rehabilitación cardiaca a los pacientes de bajo riesgo", "long_answer": "Entre los puntos críticos asociados a la cardiopatía isquémica, la ESCAV señala desarrollar programas de rehabilitación cardiaca y prevención secundaria, tanto hospitalarios como en atención primaria, adaptados al riesgo de cada paciente, ya que reducen la mortalidad, los reingresos y mejoran la calidad de vida, pero su implantación en España es todavía insuficiente. Limitar la rehabilitación cardiaca a los pacientes de bajo riesgo contradice este planteamiento, pues los de mayor riesgo son los que más se benefician. El diagnóstico precoz de la fibrilación auricular pertenece al área de arritmias y la detección precoz de la insuficiencia cardiaca al área de insuficiencia cardiaca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f7") }, {"long_answer": "El Código Europeo contra el Cáncer recoge recomendaciones basadas en la evidencia sobre lo que cada persona puede hacer para reducir su riesgo de cáncer (no fumar, mantener un peso saludable, limitar el alcohol, protegerse del sol o participar en los cribados), y subraya que el éxito de estas acciones individuales depende también de políticas y acciones gubernamentales que las faciliten, como la regulación del tabaco o la organización de programas de cribado. Por eso su enfoque combina acciones individuales y gubernamentales. No se limita exclusivamente a una de ellas, y aunque la comunidad es relevante, el Código no se centra en acciones sociales y comunitarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977100") }, {"answer": 4, "long_answer": "Según los datos de la Estrategia en Cáncer del SNS, en los hombres la incidencia de cáncer de vejiga urinaria fue claramente superior en España que en el conjunto de la UE-27; España presenta una de las tasas más altas de cáncer vesical masculino de Europa, en relación con la elevada prevalencia histórica de tabaquismo y con exposiciones ocupacionales. El cáncer de estómago y el de riñón no muestran en los hombres españoles una incidencia claramente superior a la media europea, y el cáncer de pulmón, aunque muy frecuente, tampoco destaca por superar de forma clara a la UE-27 en la comparación del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977102") }, {"long_answer": "Según los datos de incidencia recogidos en la Estrategia en Cáncer del SNS para 2020, la tasa de incidencia de cáncer de próstata en España fue de 163,3 casos por 100.000 hombres, lo que lo sitúa como el tumor más frecuente en los varones. Su elevada incidencia se relaciona con el envejecimiento de la población y con la detección mediante determinación del PSA. Las cifras de 158,8, 155,7 y 160,2 casos por 100.000 hombres son valores próximos pero no corresponden a la tasa recogida en el documento para ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ed3") }, {"long_answer": "La Meta 1 de las Metas Internacionales de Seguridad del Paciente es la identificación inequívoca del paciente, que exige utilizar al menos dos identificadores (por ejemplo, nombre completo y fecha de nacimiento, nunca el número de habitación) antes de administrar medicamentos, hemoderivados, extraer muestras o realizar procedimientos. Es la base de todas las demás metas, ya que una identificación errónea puede originar errores graves en cualquier fase de la atención. La comunicación efectiva corresponde a la Meta 2, la mejora de la seguridad de los medicamentos de alto riesgo a la Meta 3 y la cirugía y procedimiento seguros en el sitio correcto a la Meta 4."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ed4") }, {"long_answer": "La Meta 3 de las Metas Internacionales de Seguridad del Paciente es la mejora de la seguridad de los medicamentos de alto riesgo (MAR), es decir, aquellos que, utilizados de forma incorrecta, tienen alta probabilidad de causar daños graves, como electrolitos concentrados, insulinas, anticoagulantes u opioides. Incluye medidas como su almacenamiento diferenciado, el etiquetado específico, la estandarización de concentraciones y el doble chequeo independiente. La identificación inequívoca del paciente corresponde a la Meta 1, la comunicación efectiva a la Meta 2 y la cirugía y el procedimiento seguro en el sitio correcto a la Meta 4."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ed7") }, {"long_answer": "La quinta Meta Internacional de Seguridad del Paciente es la disminución del riesgo de infecciones asociadas a la atención sanitaria, cuyo pilar fundamental es la higiene de manos según los cinco momentos de la OMS, junto con las precauciones estándar y los paquetes de medidas para prevenir infecciones asociadas a dispositivos. Las infecciones relacionadas con la asistencia son uno de los eventos adversos más frecuentes y prevenibles. La identificación inequívoca del paciente es la Meta 1, la comunicación efectiva la Meta 2 y la mejora de la seguridad de los medicamentos de alto riesgo la Meta 3; la Meta 6 se refiere a la reducción del riesgo de caídas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ede") }, {"long_answer": "Las recomendaciones para organizar los servicios de salud mental en catástrofes tienen como objetivo fortalecer las capacidades locales y promover la participación activa de la comunidad afectada, integrando la atención psicosocial en los recursos y redes ya existentes para que la respuesta sea sostenible cuando termine la fase aguda. Proporcionar una respuesta inicial y retirarse deja a la población sin continuidad de cuidados, y crear una red de apoyo solo a corto plazo no garantiza la atención de las necesidades que persisten meses o años después. Evitar el deterioro a corto plazo es insuficiente, porque la recuperación psicosocial exige una planificación a medio y largo plazo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976eec") }, {"long_answer": "Entre las opciones planteadas, las infecciones de la piel y de los tejidos blandos son las más frecuentemente relacionadas con las inundaciones, ya que el contacto prolongado con agua contaminada y las heridas producidas durante la limpieza y la evacuación favorecen la entrada de microorganismos, incluidas infecciones de heridas y dermatitis; también son relevantes las gastroenteritis y la leptospirosis por contaminación del agua. Las enfermedades respiratorias pueden aparecer por hacinamiento o humedad, pero no son las más características. Las enfermedades cardiovasculares no son infecciosas ni se asocian directamente a la inundación, y las de transmisión sexual no guardan relación con este tipo de catástrofe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef5") }, {"long_answer": "Según los datos de la OMS recogidos en el documento, la letalidad de los casos humanos notificados de gripe A (H5N1) se sitúa en torno al 51,4 %, es decir, aproximadamente la mitad de las personas con infección confirmada han fallecido desde 2003. Esta elevada letalidad se calcula sobre casos confirmados, en su mayoría graves y con exposición directa a aves infectadas, por lo que probablemente sobreestima la letalidad real al no detectarse las formas leves. Las cifras del 20 %, 30 % y 40 % infravaloran la letalidad comunicada por la OMS para este subtipo de gripe aviar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976eff") }, {"long_answer": "En relación con la Esclerosis Lateral Amiotrófica, el Plan de Formación de la Estrategia en Enfermedades Neurodegenerativas incluye la formación en la detección precoz de la ELA, dirigida especialmente a profesionales de atención primaria, para que reconozcan los signos de alarma y deriven sin demora a las unidades especializadas, ya que el retraso diagnóstico suele ser de muchos meses. Los cuidados paliativos, el abordaje de los trastornos neurológicos en general y el fomento de la investigación son aspectos que la Estrategia aborda en otras líneas, pero el contenido formativo específico que destaca para la ELA en esta pregunta es la detección precoz."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f04") }, {"long_answer": "La línea estratégica 5 de la Estrategia en Enfermedades Neurodegenerativas, dedicada a la autonomía del paciente, incluye la elaboración de protocolos, programas y folletos de información a la persona enferma y a su familia, ya que una información adecuada y comprensible es la base para que el paciente pueda participar en las decisiones sobre su atención, planificar anticipadamente sus cuidados y ejercer su autonomía. El asesoramiento sobre procesos de incapacidad o tutela, el directorio de recursos y la normativa para simplificar visados son medidas de apoyo y de gestión de recursos, pero no son el aspecto que el documento vincula a la autonomía del paciente en esta línea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f09") }, {"long_answer": "No existe tratamiento curativo para la Esclerosis Lateral Amiotrófica, por lo que el principal objetivo del tratamiento farmacológico modificador de la enfermedad, fundamentalmente el riluzol, es prolongar la supervivencia del paciente, retrasando la necesidad de ventilación mecánica o traqueostomía, con un beneficio modesto de algunos meses. Revertir la enfermedad no es posible con los fármacos disponibles. El alivio del dolor y los calambres y la reducción de la espasticidad son objetivos del tratamiento sintomático, importantes para la calidad de vida, pero no constituyen el objetivo principal del tratamiento farmacológico específico de la ELA."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f10") }, {"long_answer": "Según el protocolo de mpox del Ministerio de Sanidad, la muestra de elección para el diagnóstico de laboratorio es la obtenida de las lesiones cutáneas o mucosas: exudado o raspado de vesículas o pústulas, o costras, recogido con hisopo y enviado para PCR. Estas lesiones contienen la mayor carga viral y ofrecen la mayor rentabilidad diagnóstica. La sangre puede ser positiva en la fase prodrómica, pero su rendimiento es menor y no es la muestra de elección. Las heces y la orina no se emplean de forma rutinaria para el diagnóstico de mpox."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f14") }, {"long_answer": "Para el diagnóstico de laboratorio del virus mpox (MPXV) se recomienda trabajar en un nivel de bioseguridad BSL2, utilizando una cabina de seguridad biológica para la manipulación inicial de las muestras y las prácticas adecuadas de protección del personal. Este nivel es suficiente para la extracción de ácidos nucleicos y la realización de PCR. El BSL1 resulta insuficiente para un agente patógeno transmisible como el MPXV. El BSL3 se reserva para procedimientos de mayor riesgo, como el cultivo y la propagación del virus, y el BSL4 se reserva para patógenos de máxima peligrosidad, como el ébola."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f15") }, {"answer": 2, "long_answer": "El protocolo del Ministerio de Sanidad establece que los cadáveres de personas fallecidas por mpox se manejen como cadáveres del Grupo II según la Guía de consenso sobre sanidad mortuoria, es decir, como cadáveres que suponen un riesgo infeccioso y requieren precauciones como introducirlos en bolsa sanitaria estanca y que el personal utilice equipo de protección adecuado, aunque permiten prácticas como el enterramiento o la incineración habituales. El Grupo I se reserva para enfermedades de muy alto riesgo, como la fiebre hemorrágica por ébola, y el Grupo III corresponde a cadáveres sin riesgo sanitario, por lo que afirmar que no se requiere precaución especial es incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f16") }, {"long_answer": "La transmisión de persona a persona del MPXV se produce principalmente por contacto físico estrecho con las lesiones cutáneas y los fluidos corporales de una persona infectada, como el exudado de las vesículas, así como por contacto con mucosas durante las relaciones sexuales; de las opciones planteadas, el contacto con fluidos corporales es la que describe el mecanismo principal. La transmisión por aerosoles a distancia no se considera relevante, aunque puede haber transmisión por gotas en contactos cara a cara prolongados. No se transmite por vectores, y la saliva por sí sola no constituye el mecanismo principal de contagio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f19") }, {"long_answer": "Para el manejo de la ropa y los objetos contaminados con MPXV se recomienda lavarlos con agua caliente y detergente, preferiblemente a 60 °C, evitando sacudir la ropa sucia para no dispersar partículas infecciosas, y desinfectar las superficies con productos virucidas como el hipoclorito diluido. El lavado con agua fría y jabón común no garantiza la inactivación del virus, y el MPXV puede permanecer viable durante un tiempo en tejidos y superficies, por lo que sí es necesaria una limpieza especial. Dejar los objetos al sol no es una medida de desinfección validada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f1e") }, {"option_4": "Demencias de origen infeccioso", "long_answer": "Las demencias degenerativas primarias, que incluyen la enfermedad de Alzheimer, la demencia frontotemporal, la demencia por cuerpos de Lewy y la demencia asociada a la enfermedad de Parkinson, se caracterizan por pérdida neuronal y sináptica y por el depósito cerebral de agregados proteicos insolubles intra o extracelulares, como beta-amiloide, tau o alfa-sinucleína. Las demencias secundarias y las mixtas se deben a otras causas o combinaciones de mecanismos, la demencia vascular se origina por lesiones cerebrovasculares y no por agregados proteicos, y las demencias de origen infeccioso son secundarias a la acción de un agente infeccioso, por lo que no comparten este mecanismo neurodegenerativo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f21") }, {"long_answer": "La Estrategia en Enfermedades Neurodegenerativas recomienda que, ante la detección de quejas de pérdida de memoria y declive cognitivo, el médico de atención primaria realice un cribado activo mediante una anamnesis dirigida, preferiblemente con informante, y tests cognitivos breves validados, para identificar precozmente un posible deterioro cognitivo y orientar el estudio. El electroencefalograma, el análisis de sangre y la resonancia magnética son pruebas complementarias que pueden formar parte del estudio diagnóstico posterior, pero no constituyen la actuación inicial recomendada ante estas quejas, que es la valoración y el cribado cognitivo en atención primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f22") }, {"option_3": "Únicamente el tratamiento farmacológico de los síntomas cognitivos", "option_4": "Un plan integrado de cuidados sanitarios y sociales coordinado entre niveles asistenciales", "long_answer": "La Estrategia en Enfermedades Neurodegenerativas establece que, desde el diagnóstico, las personas con enfermedad de Alzheimer y otras demencias deben contar con un Plan Individualizado de Atención que integre los cuidados sanitarios y sociales y se coordine entre atención primaria, atención especializada y servicios sociales, contemplando la prevención y atención de la discapacidad, la comorbilidad y el apoyo a la persona cuidadora. Un plan de ejercicio físico o de alimentación especial pueden ser componentes puntuales, pero no definen el plan. Limitarlo únicamente al tratamiento farmacológico de los síntomas cognitivos contradice el enfoque integral y centrado en la persona que propone la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f25") }, {"long_answer": "La participación de las asociaciones de familiares y pacientes de Alzheimer y otras demencias tiene, entre sus objetivos principales, disminuir el estigma asociado a la enfermedad, mediante la sensibilización social, la visibilización de las personas afectadas y la defensa de sus derechos, lo que favorece el diagnóstico precoz y la inclusión social. Fomentar el estigma es justo lo contrario de su finalidad. Conseguir financiación para investigación o desarrollar programas de prevención pueden ser actividades que algunas asociaciones realicen, pero no constituyen el objetivo que la Estrategia atribuye a su participación, centrado en la lucha contra el estigma, el apoyo a las familias y la representación de sus intereses."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f27") }, {"long_answer": "En el estudio de pie diabético (EPD) al que se refiere el documento, el principal resultado evaluado es la presencia de diabetes mellitus con pie de riesgo, es decir, la proporción de personas con diabetes que presentan factores como neuropatía, enfermedad arterial periférica, deformidades o antecedentes de úlcera o amputación, que predisponen a lesiones graves. Identificar el pie de riesgo es la base de la estratificación y de la prevención. La mortalidad y la tasa de amputaciones son resultados de gravedad posteriores, y las diferencias en el control y la prevalencia son análisis complementarios, pero no el resultado principal del estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f2d") }, {"long_answer": "Las inclusiones intracitoplasmáticas típicas de la enfermedad de Parkinson son los cuerpos de Lewy, agregados eosinófilos formados fundamentalmente por alfa-sinucleína que se acumulan en las neuronas dopaminérgicas de la sustancia negra y en otras regiones del sistema nervioso, y que definen a esta enfermedad como una sinucleinopatía. Las placas de amiloide son depósitos extracelulares característicos de la enfermedad de Alzheimer. La proteína tau hiperfosforilada forma los ovillos neurofibrilares de la enfermedad de Alzheimer y de las taupatías, y las neurofibrillas no son la lesión distintiva del Parkinson."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f2f") }, {"option_3": "El grupo sanguíneo ABO", "answer": 4, "long_answer": "La mayoría de los estudios coinciden en que los antecedentes familiares aumentan el riesgo de padecer enfermedad de Parkinson: tener un familiar de primer grado afectado incrementa claramente la probabilidad de desarrollarla, y entre un 10 y un 15 % de los casos presentan agregación familiar, con algunas formas monogénicas identificadas. La dieta y el nivel de actividad física se han estudiado con resultados inconsistentes o como posibles factores protectores, sin un consenso sólido sobre su papel causal. El grupo sanguíneo ABO no se ha establecido como factor que influya en el riesgo de enfermedad de Parkinson."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f37") }, {"option_3": "Despreocupación", "long_answer": "Ante el nacimiento de un niño enfermo o prematuro, los padres experimentan con frecuencia sentimientos intensos de culpa, al preguntarse si algo que hicieron o dejaron de hacer durante el embarazo pudo provocar la situación, junto con ansiedad, miedo y tristeza. Reconocer este sentimiento es esencial para que los profesionales ofrezcan apoyo emocional e información que lo alivie, en el marco de los cuidados centrados en la familia. La alegría propia del nacimiento suele quedar desplazada por la preocupación, y la despreocupación o la indiferencia no son reacciones esperables en esta situación de crisis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f39") }, {"long_answer": "El método canguro, basado en el contacto piel con piel prolongado entre el niño y su madre o padre, se asocia a una mejora del desarrollo psicomotor y neurosensorial, ya que proporciona estímulos táctiles, auditivos y vestibulares adecuados, favorece la organización del sueño y reduce el estrés del recién nacido; además mejora la termorregulación, la estabilidad cardiorrespiratoria y la lactancia materna. No aumenta el llanto, sino que lo disminuye, ni reduce la estabilidad metabólica, ya que favorece el control de la glucemia y la temperatura. Tampoco incrementa las infecciones; al contrario, se ha asociado a una menor incidencia de infecciones nosocomiales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f3a") }, {"long_answer": "En el ingreso del niño en la unidad neonatal, la propuesta operativa que plantea el documento de cuidados centrados en el desarrollo y la familia es favorecer la unión y la fuerza de la familia dentro de la unidad, facilitando la presencia de los padres las 24 horas, su participación en los cuidados y en las decisiones, y su papel como cuidadores principales. Limitar la participación de la familia, restringir las visitas de otros miembros o promover la separación de los padres y el niño son prácticas contrarias a este enfoque, ya que aumentan el estrés familiar y dificultan el vínculo y el desarrollo del recién nacido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f3e") }, {"long_answer": "El Método Madre Canguro surgió como alternativa a la incubadora para recién nacidos prematuros y de bajo peso en países con pocos recursos, pero sus beneficios sobre la termorregulación, la lactancia materna, el vínculo y la estabilidad fisiológica han hecho que se haya extendido tanto a recién nacidos prematuros como a término, y a países de cualquier nivel de desarrollo. Por ello no se limita solo a prematuros estables. Tampoco se restringe a países en vías de desarrollo ni únicamente a países desarrollados, ya que se aplica en unidades neonatales de todo el mundo y en el cuidado del recién nacido sano en la maternidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f47") }, {"long_answer": "La evidencia recomienda disminuir los niveles de luz en las unidades de cuidados intensivos neonatales y evitar la exposición directa a la luz, especialmente en los prematuros, para proteger la retina inmadura, ya que sus párpados son finos y no filtran bien la luz, y favorecer así el desarrollo visual, el descanso y los ciclos de sueño. Aumentar la exposición a la luz no reduce el estrés, sino que lo incrementa. Reducir la intensidad de la luz no tiene como finalidad principal mejorar la alimentación, y sí existen recomendaciones específicas sobre la iluminación en las unidades neonatales, como el uso de cobertores en las incubadoras y luces individuales para procedimientos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f4a") }, {"long_answer": "Aunque en las unidades neonatales se recomienda mantener una iluminación ambiental baja para proteger a los recién nacidos, las tareas que exigen precisión requieren una iluminación focal suficiente; para la preparación de la medicación el documento recomienda un nivel de en torno a 500 lux en la zona de trabajo, de manera que se puedan leer correctamente etiquetas y escalas y se eviten errores de dosificación, sin iluminar de forma directa al neonato. Los niveles de 1000 y 3000 lux serían excesivos para esta tarea y contribuirían a elevar la luz ambiental de la unidad. Sí existe una recomendación específica para esta actividad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f4d") }, {"option_2": "Mejora la calidad del sueño del neonato", "long_answer": "El ruido excesivo en las unidades de cuidados intensivos neonatales dificulta la comunicación interpersonal entre profesionales y con las familias, lo que aumenta el riesgo de errores, y además genera estrés en el personal. En los recién nacidos produce efectos negativos como alteraciones del sueño, taquicardia, aumento de la presión arterial, desaturaciones y posible daño auditivo. Por tanto, no mejora la calidad del sueño del neonato, sino que la empeora. No disminuye el ritmo cardiaco, sino que tiende a aumentarlo como respuesta de estrés, y tampoco facilita la atención de los profesionales, ya que interfiere con la concentración y la comunicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f53") }, {"long_answer": "El contacto piel con piel precoz entre la madre y el recién nacido se asocia a mayores niveles de glucosa en sangre del neonato, ya que reduce el estrés y el gasto energético, además de mejorar la termorregulación y la estabilidad cardiorrespiratoria. También favorece una mayor frecuencia y duración de la lactancia materna, por lo que la opción que habla de menor lactancia es incorrecta. No disminuye la estabilidad cardiorrespiratoria, sino que la mejora, y en las madres se asocia a menor ingurgitación mamaria y menor dolor, no a un aumento de este."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f54") }, {"long_answer": "Las recomendaciones del Ministerio de Sanidad sobre cuidados desde el nacimiento indican que el contacto piel con piel tras el parto debe mantenerse sin interrupción durante un tiempo mínimo de unos 50 minutos, ya que los recién nacidos que permanecen en contacto con su madre al menos ese tiempo tienen mayor probabilidad de realizar espontáneamente la primera toma de pecho y de mantener la lactancia materna. Durante este periodo deben posponerse los procedimientos rutinarios que no sean urgentes. Los tiempos de 30 y 40 minutos son insuficientes para que la mayoría de los neonatos inicien la succión, y 60 minutos no es el mínimo establecido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f5b") }, {"long_answer": "Cuando los padres rechazan la administración intramuscular de vitamina K al recién nacido, se recomienda ofrecer la administración por vía oral, informándoles de que, aunque es menos eficaz que la intramuscular para prevenir la enfermedad hemorrágica tardía, proporciona protección y requiere completar varias dosis según la pauta establecida. Insistir en la vía intramuscular sin respetar la decisión informada de la familia no es adecuado. No dar ninguna alternativa dejaría al niño sin profilaxis, y esperar a que los padres cambien de opinión retrasa una medida preventiva que debe aplicarse tras el nacimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f5e") }, {"long_answer": "Para la profilaxis con vitamina K en recién nacidos se recomienda el preparado Konakion® 2 mg pediátrico, una presentación de fitomenadiona (vitamina K1) en solución micelar que permite tanto la administración intramuscular como la oral y que está adaptada a las dosis neonatales, habitualmente 1 mg por vía intramuscular o 2 mg por vía oral en varias tomas. Konakion® 10 mg es la presentación para adultos, con una concentración no adecuada para el neonato. Las presentaciones citadas como VitaK® 5 mg y VitaminaK® 1 mg no son los preparados recomendados en el documento para este uso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f61") }, {"long_answer": "La profilaxis con solución de nitrato de plata al 1 % aplicada en los ojos de los recién nacidos, conocida como método de Credé, logró reducir la incidencia de oftalmia neonatal en torno a un 97 %, al disminuir la incidencia de oftalmia gonocócica desde cifras cercanas al 10 % hasta menos del 0,5 %. Este impacto histórico explica que la profilaxis ocular se generalizara. Las reducciones del 10 % y del 50 % infravaloran claramente su efecto, y el 90 % no es la cifra recogida en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f62") }, {"long_answer": "En los países desarrollados la profilaxis de la oftalmia neonatal se ha orientado hacia otros fármacos, como la eritromicina o la tetraciclina en pomada, para cubrir mejor la infección por Chlamydia trachomatis, que se ha convertido en la causa más frecuente de conjuntivitis neonatal de transmisión vertical y frente a la cual el nitrato de plata es poco eficaz, además de provocar conjuntivitis química con frecuencia. La profilaxis ocular no guarda relación con la fiebre posparto, el tratamiento de la ictericia neonatal ni la prevención de la otitis neonatal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f71") }, {"long_answer": "El programa de cribado neonatal de la cartera común del SNS en España incluye, entre otras, el hipotiroidismo congénito, la fenilcetonuria y la fibrosis quística, junto con otras enfermedades como la deficiencia de MCAD, la de LCHAD, la acidemia glutárica tipo I y la anemia falciforme, que se detectan mediante la prueba del talón. Son enfermedades en las que el diagnóstico y tratamiento precoces evitan secuelas graves. La fiebre reumática y la diabetes tipo 1, la leucemia infantil y la anemia hemolítica, y los síndromes de Down y Turner no forman parte del cribado neonatal de metabolopatías."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f72") }, {"long_answer": "Para el cribado metabólico neonatal se recomienda obtener la muestra de sangre del talón entre las 48 horas y el séptimo día de vida, y en los prematuros o en caso de alta precoz, antes del alta. Este momento permite que el recién nacido haya iniciado la alimentación y se reduzcan los falsos resultados, por ejemplo en la fenilcetonuria o el hipotiroidismo congénito, sin retrasar el diagnóstico y el tratamiento. Tomar la muestra en las primeras 24 horas aumenta los falsos negativos y positivos. A partir de los 7 días o entre la cuarta y la sexta semana el diagnóstico sería demasiado tardío."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f73") }, {"long_answer": "Para reducir el dolor del recién nacido durante la punción del talón se han mostrado eficaces medidas no farmacológicas como el contacto piel con piel con la madre, las caricias o la contención, el amamantamiento durante el procedimiento y la administración oral de pequeñas cantidades de soluciones de glucosa o sacarosa antes de la punción. Estas medidas disminuyen las respuestas de dolor y el llanto. Los antibióticos no tienen efecto analgésico. Las vendas compresivas no reducen el dolor, y la aplicación de frío en el talón no se recomienda, ya que dificulta la obtención de la muestra al producir vasoconstricción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f76") }, {"long_answer": "Entre las competencias específicas del personal de enfermería implicado en la hemodiálisis está realizar la extracción de sangre para valorar el hematocrito, los electrolitos y otros parámetros analíticos, que permiten evaluar la adecuación de la diálisis y detectar alteraciones como la hiperpotasemia o la anemia. Controlar el estado de ánimo, mantener conversaciones con el paciente o aplicar vendajes son actuaciones que forman parte del cuidado general, pero no constituyen competencias específicas de la técnica de hemodiálisis, que incluyen el manejo del acceso vascular, la programación y monitorización del circuito extracorpóreo y el control analítico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f78") }, {"long_answer": "Una medida fundamental para la seguridad del paciente durante la sesión de hemodiálisis es verificar que se cumplen todas las medidas de seguridad del circuito extracorpóreo y del monitor: correcta conexión y fijación de las líneas, ausencia de aire, funcionamiento de alarmas, detector de aire y pinzas, así como los parámetros del líquido de diálisis. Dejar las agujas insertadas al desechar la sangre dializada supone riesgo de punción accidental, la conductividad y temperatura del líquido de diálisis deben ajustarse al inicio, no al final, y no comprobar la colocación de las líneas puede provocar desconexiones, hemorragias o embolia gaseosa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f82") }, {"long_answer": "Según los datos de vigilancia epidemiológica recogidos en el documento, en España se notificaron 894 casos de hepatitis A durante el año 2024, lo que refleja la circulación del virus con brotes asociados sobre todo a la transmisión de persona a persona, incluida la transmisión sexual, y a alimentos contaminados. Esta cifra justifica mantener las recomendaciones de vacunación en grupos de riesgo y en el control de brotes. Las cifras de 265, 336 y 461 casos no corresponden a los casos notificados en ese año según el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f83") }, {"long_answer": "En los hombres, la mayor incidencia acumulada de hepatitis A se observó en el grupo de 25 a 44 años, lo que se relaciona con la transmisión sexual, especialmente en hombres que tienen sexo con hombres, y con los viajes a zonas endémicas en población adulta joven no inmunizada. Los grupos de 15 a 24 y de 5 a 14 años presentaron menor incidencia, ya que la vacunación y la menor exposición limitan los casos. En las personas de 65 años o más la incidencia es baja, porque muchas pasaron la infección en la infancia y están inmunizadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f86") }, {"long_answer": "En la vacunación frente a la hepatitis A se recomienda realizar un estudio serológico de IgG frente al virus antes de vacunar a las personas nacidas en 1967 o antes, porque en España la circulación del virus era muy elevada en esas décadas y es muy probable que hayan pasado la infección y estén inmunizadas, por lo que la serología previa evita vacunaciones innecesarias. No es correcto afirmar que no sea necesario el estudio en este grupo. Restringirlo solo a casos de exposición o de inmunodeficiencia no se corresponde con la recomendación, que se basa en el año de nacimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f90") }, {"long_answer": "La vacuna combinada frente a hepatitis A y B en adultos se administra habitualmente con una pauta de tres dosis a los 0, 1 y 6 meses, que proporciona una protección duradera frente a ambos virus. Existe una pauta acelerada de 0, 7 y 21 días con una dosis de refuerzo a los 12 meses para situaciones en las que se necesita protección rápida, pero la pauta estándar es la de tres dosis. Una dosis única no es suficiente para la protección frente a la hepatitis B. La pauta de dos dosis a los 0 y 1 mes es incompleta, y la de cuatro dosis a los 0, 1, 2 y 6 meses no es la recomendada para esta vacuna."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f93") }, {"option_1": "Utilizar cabinas de rayos UVA como alternativa segura al sol", "option_3": "Prolongar la terapia hormonal sustitutiva más allá de lo indicado", "option_4": "Evitar la lactancia materna", "long_answer": "El Código Europeo contra el Cáncer recomienda participar en los programas organizados de cribado de cáncer, que en el caso de las mujeres incluyen el cribado de cáncer de mama, de cuello uterino y de colon y recto, ya que permiten detectar lesiones precursoras o tumores en fases precoces y reducir la mortalidad. Utilizar cabinas de rayos UVA es contrario al Código, que desaconseja su uso. El Código recomienda limitar el uso de la terapia hormonal sustitutiva, no prolongarla, y promueve la lactancia materna porque reduce el riesgo de cáncer de mama en la madre."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f94") }, {"long_answer": "El Código Europeo contra el Cáncer, en su cuarta edición, recomienda que, si se consumen bebidas alcohólicas de cualquier tipo, se limite su consumo, es decir, se tome con moderación, y señala además que no beber alcohol es lo más beneficioso para prevenir el cáncer, puesto que cualquier cantidad aumenta el riesgo. Consumir alcohol en ocasiones especiales no es una recomendación del Código. Beber solo cerveza sin alcohol no aparece como recomendación, y la recomendación formulada en el Código es limitar el consumo, añadiendo que no consumir es mejor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f9a") }, {"long_answer": "El Código Europeo contra el Cáncer recomienda realizar acciones individuales para contribuir a prevenir el cáncer, como no fumar, mantener un peso saludable, ser físicamente activo, seguir una dieta saludable, limitar el alcohol, protegerse del sol, vacunarse frente a VHB y VPH y participar en los cribados, y reconoce que las políticas públicas facilitan estas conductas. Depender únicamente de las políticas gubernamentales ignora el papel de cada persona. No hacer nada al respecto es contrario a la prevención, y no existe un consumo de tabaco responsable, ya que el Código recomienda no consumir ningún tipo de tabaco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f9c") }, {"question": "¿Cuáles son las reacciones adversas sistémicas más frecuentes tras la vacunación frente a la COVID-19?", "option_1": "Exantema generalizado y prurito", "long_answer": "Tras la vacunación frente a la COVID-19, las reacciones adversas sistémicas más frecuentes son la astenia o cansancio intenso y las mialgias, junto con la cefalea, el malestar general y, en menor medida, la fiebre; suelen ser leves o moderadas y desaparecen en uno o dos días. El exantema generalizado con prurito es una reacción poco frecuente. El dolor de garganta y la tos son síntomas de infección respiratoria, no reacciones habituales a la vacuna. Los escalofríos pueden aparecer, pero junto con el dolor de espalda no constituyen las reacciones sistémicas más frecuentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa0") }, {"option_2": "Aplicación de calor local tras la inyección", "long_answer": "En las personas con trastornos de la coagulación o en tratamiento anticoagulante se recomienda administrar las vacunas intramusculares con una aguja fina, de calibre 23G o menor, y aplicar después presión firme en el lugar de inyección durante al menos dos minutos sin frotar, para minimizar el riesgo de hematoma. Utilizar una aguja gruesa aumenta el daño tisular y el sangrado. La aplicación de calor local favorece la vasodilatación y el sangrado, y frotar la zona de inyección está desaconsejado porque puede provocar la formación de un hematoma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa2") }, {"long_answer": "Según el documento sobre vacunación, se considera que un intervalo de tres meses desde la dosis previa de vacuna o desde una infección es el óptimo para obtener una respuesta inmune adecuada con la siguiente dosis, ya que permite la maduración de la respuesta de memoria y evita la interferencia con niveles elevados de anticuerpos recientes. Un intervalo de un mes es demasiado corto para conseguir una buena respuesta de refuerzo. Los intervalos de seis meses y un año no son los indicados como óptimos en el documento, aunque pueden utilizarse en otras pautas de recuerdo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976faa") }, {"long_answer": "La hoja de ruta para el abordaje de la fragilidad, elaborada en el marco de la Estrategia de Promoción de la Salud y Prevención en el SNS, tiene como objetivo contribuir a un abordaje más homogéneo de la fragilidad en el conjunto del Sistema Nacional de Salud, reduciendo la variabilidad entre comunidades autónomas en su detección, valoración e intervención. Promover el envejecimiento saludable, mejorar la prevención de la fragilidad y fomentar la coordinación entre ámbitos de atención son metas relacionadas que se recogen en las distintas líneas de acción de la hoja de ruta, pero no constituyen su objetivo general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fac") }, {"long_answer": "Una de las funciones del Grupo de Trabajo de prevención de Fragilidad y caídas es valorar la revisión y actualización de los documentos producidos por el propio grupo, como el documento de consenso sobre prevención de la fragilidad y las caídas, para mantenerlos acordes con la evidencia disponible. Elaborar la hoja de ruta para el abordaje de la fragilidad fue una tarea puntual y no una función permanente del grupo. Desarrollar una campaña nacional de concienciación sobre envejecimiento o definir una estrategia común para Europa exceden el ámbito de sus funciones, que se limita al SNS español."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fae") }, {"long_answer": "La puesta en marcha de iniciativas comunitarias coordinadas e intersectoriales busca promover el envejecimiento saludable, mediante actividades en el entorno local como programas de actividad física, de alimentación o de participación social en las que colaboran servicios sanitarios, sociales, ayuntamientos y asociaciones. El abordaje de la fragilidad en los procesos asistenciales es una actuación del ámbito sanitario, no comunitario. Las reuniones periódicas del Grupo de Trabajo no son una iniciativa comunitaria, y la detección precoz poblacional de fragilidad se realiza principalmente desde atención primaria mediante el cribado de las personas mayores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976faf") }, {"long_answer": "La acción de establecer y mejorar de forma continuada un modelo integrado y coordinado de cuidado que aborde la fragilidad tiene como objetivo promocionar ese modelo integrado de cuidado en todo el SNS, de manera que las personas mayores frágiles reciban una atención continua y centrada en sus necesidades. Fomentar la coordinación entre ámbitos y promover el envejecimiento saludable son objetivos más amplios de la hoja de ruta que se recogen en otras acciones, e identificar buenas prácticas en modelos de cuidados integrados es una herramienta para lograrlo, no el objetivo de la acción. Por ello, la opción que mejor responde es promocionar el modelo integrado de cuidado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fb1") }, {"long_answer": "Las recomendaciones de comunicación en el ámbito comunitario sobre la viruela M (mpox) indican ofrecer mensajes prácticos que orienten sobre cómo actuar en situaciones concretas, por ejemplo qué hacer ante lesiones sospechosas, cómo reducir el riesgo en contactos estrechos o dónde acudir, utilizando un lenguaje claro y no estigmatizante. Centrarse en el contacto sexual como única vía de transmisión es incorrecto, ya que el virus se transmite por cualquier contacto físico estrecho. No trasladar la información oficial a la comunidad favorece la desinformación, y utilizar un lenguaje técnico o confuso dificulta la comprensión y la adopción de medidas preventivas."});
print(`\nParte terminada: ${ok} corregidas, ${del} borradas, ${warn} avisos.`);
